@st.cache_data(ttl=1800, show_spinner=False)
def consultar_orgaos_estatutarios_result(cnpj: str, id_bacen: str = "") -> dict:
    resultado = consultar_pessoas_juridicas(cnpj, id_bacen=id_bacen)
    payload = resultado.payload if resultado.sucesso and isinstance(resultado.payload, dict) else {}
    df_orgaos = _extrair_orgaos_do_json(payload)
    return {
        "sucesso": resultado.sucesso,
        "status": resultado.status,
        "mensagem": resultado.mensagem,
        "status_code": resultado.status_code,
        "method": resultado.method,
        "payload": payload,
        "df_orgaos": df_orgaos,
    }


def consultar_orgaos_estatutarios(cnpj: str, id_bacen: str = "") -> pd.DataFrame:
    resultado = consultar_orgaos_estatutarios_result(cnpj, id_bacen=id_bacen)
    if not resultado.get("sucesso"):
        raise RuntimeError(str(resultado.get("mensagem") or "API de pessoas jurídicas indisponível"))
    return resultado.get("df_orgaos", pd.DataFrame())


def gerar_excel_orgaos_estatutarios(
    df_orgaos: pd.DataFrame,
    titulo: str,
    cor_fundo: str = "#F5F5F5",
    fonte: str = "Banco Central do Brasil via API /informes/rest/pessoasJuridicas",
    data_extracao: str = "",
) -> bytes:
    output = io.BytesIO()
    data_txt = data_extracao or datetime.now().strftime("%d/%m/%Y")

    with pd.ExcelWriter(output, engine="xlsxwriter") as writer:
        df_export = df_orgaos[["Nome", "Cargo"]].copy() if {"Nome", "Cargo"}.issubset(df_orgaos.columns) else df_orgaos.copy()
        df_export.to_excel(writer, sheet_name="Órgãos", index=False, startrow=2)

        workbook = writer.book
        worksheet = writer.sheets["Órgãos"]

        title_fmt = workbook.add_format({"bold": True, "font_size": 14, "font_color": "#2b2f3a"})
        subtitle_fmt = workbook.add_format({"italic": True, "font_color": "#50555f"})
        header_fmt = workbook.add_format({"bold": True, "bg_color": "#D6D8DE", "border": 1, "align": "left"})
        row_a_fmt = workbook.add_format({"border": 1, "bg_color": cor_fundo})
        row_b_fmt = workbook.add_format({"border": 1, "bg_color": "#F8F9FC"})

        worksheet.merge_range(0, 0, 0, 1, titulo, title_fmt)
        worksheet.merge_range(1, 0, 1, 1, f"Fonte: {fonte} | Data de extração: {data_txt}", subtitle_fmt)

        worksheet.write(2, 0, "Nome", header_fmt)
        worksheet.write(2, 1, "Cargo", header_fmt)
        worksheet.set_column(0, 0, 46)
        worksheet.set_column(1, 1, 34)

        for i in range(len(df_export)):
            fmt = row_a_fmt if i % 2 == 0 else row_b_fmt
            worksheet.write(i + 3, 0, str(df_export.iloc[i]["Nome"]), fmt)
            worksheet.write(i + 3, 1, str(df_export.iloc[i]["Cargo"]), fmt)

    output.seek(0)
    return output.getvalue()


def _listar_periodos_documento_cdsfn(qtd: int = 20) -> list[str]:
    if qtd <= 0:
        return []

    agora = _agora_brasilia()
    quarter_months = [3, 6, 9, 12]
    candidatos = [m for m in quarter_months if m < agora.month or (m == agora.month and agora.day >= 15)]
    if candidatos:
        mes = candidatos[-1]
        ano = agora.year
    else:
        mes = 12
        ano = agora.year - 1

    periodos: list[str] = []
    for _ in range(qtd):
        periodos.append(f"{ano}{mes:02d}")
        idx = quarter_months.index(mes)
        if idx == 0:
            mes = 12
            ano -= 1
        else:
            mes = quarter_months[idx - 1]
    return periodos


def _filtrar_instituicoes_cdsfn(df_instituicoes: pd.DataFrame, termo: str) -> pd.DataFrame:
    termo = str(termo or "").strip()
    if not termo:
        return df_instituicoes

    termo_nome = _normalizar_texto_sem_acento(termo).upper()
    termo_cnpj = re.sub(r"\D", "", termo)

    mask_nome = df_instituicoes["nome"].fillna("").astype(str).map(
        lambda valor: termo_nome in _normalizar_texto_sem_acento(valor).upper()
    )
    if termo_cnpj:
        mask_cnpj = df_instituicoes["cnpj"].fillna("").astype(str).str.contains(termo_cnpj, na=False)
        mask = mask_nome | mask_cnpj
    else:
        mask = mask_nome
    return df_instituicoes[mask].reset_index(drop=True)


def _formatar_valor_cdsfn(valor) -> str:
    valor_num = pd.to_numeric(valor, errors="coerce")
    if pd.isna(valor_num):
        return "—"
    casas = 0 if float(valor_num).is_integer() else 2
    return formatar_numero_br(float(valor_num), casas=casas)


def _rotulo_tipo_referencia_cdsfn(prefixo: str) -> str:
    prefixo = str(prefixo or "").strip().upper()
    if prefixo == "A":
        return "Anual (A)"
    if prefixo == "S":
        return "Semestral (S)"
    return prefixo or "Sem prefixo"


def _render_cdsfn_hierarchy_table(
    df_view: pd.DataFrame,
    value_columns: list[str],
    *,
    column_labels: dict[str, str] | None = None,
    block_key: str | None = None,
) -> None:
    if df_view.empty:
        st.info("Sem linhas para exibir nesta seção.")
        return

    html = """
    <style>
    .cdsfn-table-wrap {
        width: 100%;
        overflow-x: auto;
        margin-top: 0.4rem;
        border: 1px solid #d9d9d9;
        border-radius: 10px;
    }
    .cdsfn-table {
        width: max-content;
        border-collapse: collapse;
        font-size: 14px;
        font-family: 'IBM Plex Sans', sans-serif;
    }
    .cdsfn-table th, .cdsfn-table td {
        border: 1px solid #e5e5e5;
        padding: 8px 10px;
        text-align: right;
        vertical-align: top;
        white-space: nowrap;
    }
    .cdsfn-table thead tr:first-child th {
        background: #111111;
        color: #ffffff;
        text-align: center;
        font-weight: 700;
    }
    .cdsfn-table td:first-child, .cdsfn-table th:first-child {
        text-align: left;
        white-space: nowrap;
        width: auto;
    }
    .cdsfn-row-parent td {
        background: #f6f6f6;
        font-weight: 700;
    }
    .cdsfn-row-leaf td:first-child {
        font-weight: 500;
    }
    .cdsfn-negative {
        color: #7a1e2b;
        font-weight: 600;
    }
    .cdsfn-level-tag {
        color: #6b7280;
        font-size: 11px;
        margin-right: 6px;
    }
    </style>
    """
    html += "<div class='cdsfn-table-wrap'><table class='cdsfn-table'><thead><tr><th>Conta</th>"
    for col in value_columns:
        header = column_labels.get(col, col) if column_labels else col
        html += f"<th>{_html_mod.escape(str(header))}</th>"
    html += "</tr></thead><tbody>"
    for _, row in df_view.iterrows():
        depth = int(row.get("depth", 0) or 0)
        has_children = bool(row.get("has_children"))
        row_class = "cdsfn-row-parent" if has_children or depth == 0 else "cdsfn-row-leaf"
        descricao = _html_mod.escape(str(row.get("descricao") or ""))
        nivel = _html_mod.escape(str(row.get("nivel") or ""))
        padding = 14 + (depth * 18)
        conta_html = (
            f"<span class='cdsfn-level-tag'>{nivel}</span>"
            f"<span style='padding-left:{padding}px; display:inline-block;'>{descricao}</span>"
        )
        html += f"<tr class='{row_class}'><td>{conta_html}</td>"
        for col in value_columns:
            valor = pd.to_numeric(row.get(col), errors="coerce")
            valor_fmt = _formatar_valor_cdsfn(valor)
            if pd.notna(valor) and float(valor) < 0:
                html += f"<td><span class='cdsfn-negative'>{valor_fmt}</span></td>"
            else:
                html += f"<td>{valor_fmt}</td>"
        html += "</tr>"

    html += "</tbody></table></div>"
    st.markdown(html, unsafe_allow_html=True)


