def _ordenar_opcoes_cache_atualizacao(cache_keys: list[str], caches_info: dict) -> list[str]:
    """Ordena caches da aba de atualização por relatório e nome de exibição."""
    ordenacao_manual = {
        "principal": 1,
        "principal_individual": 2,
        "ativo": 3,
        "passivo": 4,
        "dre": 5,
        "dre_individual": 6,
        "capital": 7,
        "carteira_pf": 8,
        "carteira_pj": 9,
        "carteira_instrumentos": 10,
        "taxas_juros": 11,
        "bloprudencial": 12,
    }

    def _sort_key(cache_key: str):
        info = caches_info.get(cache_key, {})
        relatorio = info.get("relatorio")
        nome = info.get("nome_exibicao", cache_key)
        return (
            ordenacao_manual.get(cache_key, 999),
            relatorio if relatorio is not None else 999,
            nome,
        )

    return sorted(cache_keys, key=_sort_key)


def _status_cache_atualizacao(info_local: dict, info_github: dict) -> str:
    """Resume o status operacional do cache sem depender de emojis."""
    existe_local = info_local.get("existe", False)
    existe_github = info_github.get("existe", False)
    if existe_github:
        return "Publicado"
    if existe_local:
        return "Somente local"
    return "Ausente"

def _periodo_exibicao_para_api_local(periodo_exib: str) -> str:
    """Converte período T/YYYY para YYYYMM (local, sem depender do extrator)."""
    if not periodo_exib or "/" not in str(periodo_exib):
        return ""
    try:
        tri, ano = str(periodo_exib).split("/")
        tri = tri.strip()
        mes_map = {"1": "03", "2": "06", "3": "09", "4": "12"}
        mes = mes_map.get(tri, "03")
        return f"{ano.strip()}{mes}"
    except Exception:
        return ""


def _normalizar_periodo_cache(periodo_raw) -> str:
    """Normaliza período do metadata para formato YYYYMM."""
    if periodo_raw is None:
        return ""
    texto = str(periodo_raw).strip()
    if not texto:
        return ""

    if len(texto) == 6 and texto.isdigit():
        return texto

    if "/" in texto:
        parte1, parte2 = texto.split("/", 1)
        parte1 = parte1.strip()
        parte2 = parte2.strip()

        if len(parte1) == 4 and parte1.isdigit() and len(parte2) == 2 and parte2.isdigit():
            return f"{parte1}{parte2}"

        if len(parte2) == 4 and parte2.isdigit():
            mes_map = {"1": "03", "2": "06", "3": "09", "4": "12"}
            mes = mes_map.get(parte1, "")
            if mes:
                return f"{parte2}{mes}"

    return ""


def _periodo_yyyymm_para_exibicao(periodo_yyyymm: str) -> str:
    """Converte YYYYMM para MM/YYYY."""
    if not periodo_yyyymm or len(periodo_yyyymm) != 6 or not periodo_yyyymm.isdigit():
        return "-"
    return f"{periodo_yyyymm[4:6]}/{periodo_yyyymm[:4]}"


def _intervalo_periodos_cache(info_local: dict) -> tuple[str, str]:
    """Retorna período inicial/final disponível no cache local."""
    periodos = info_local.get("periodos") or []
    periodos_norm = sorted({p for p in (_normalizar_periodo_cache(x) for x in periodos) if p})
    if not periodos_norm:
        return "-", "-"
    return (
        _periodo_yyyymm_para_exibicao(periodos_norm[0]),
        _periodo_yyyymm_para_exibicao(periodos_norm[-1]),
    )


def _versao_local_cache(info_local: dict) -> str:
    """Retorna carimbo de versão local (timestamp do metadata)."""
    ts = info_local.get("timestamp_salvamento")
    if not ts:
        return "-"
    try:
        dt = datetime.fromisoformat(str(ts))
        return dt.strftime("%d/%m/%Y %H:%M")
    except Exception:
        return str(ts)


def _inferir_periodo_api_padrao() -> str:
    """Infere um período YYYYMM padrão a partir do metadata do cache principal."""
    try:
        meta_path = Path("data/cache/principal/metadata.json")
        if not meta_path.exists():
            return "202503"
        meta = json.loads(meta_path.read_text())
        periodos = meta.get("periodos") or []
        if not periodos:
            return "202503"
        ultimo = sorted(periodos, key=lambda p: (int(p.split("/")[1]), int(p.split("/")[0])))[-1]
        return _periodo_exibicao_para_api_local(ultimo) or "202503"
    except Exception:
        return "202503"

@st.cache_data(ttl=900, show_spinner=False)
def _diagnosticar_ifdata_resumo(periodo_api: str, termo_busca: str):
    """Diagnóstico objetivo da presença de IF no Relatório 1 (Resumo) do IFData."""
    from utils.ifdata_cache.extractor import (
        extrair_cadastro,
        extrair_valores,
        _normalizar_nome_coluna,
        VARIAVEIS_RESUMO_API,
    )

    termo = (termo_busca or "").strip()
    if not periodo_api or not termo:
        return {"erro": "período e termo são obrigatórios"}

    df_cad = extrair_cadastro(periodo_api)
    df_val = extrair_valores(periodo_api, relatorio=1)

    col_nome = None
    for candidato in ["NomeInstituicao", "NomeInstituição", "NomeInstituicaoCompleto"]:
        if candidato in df_cad.columns:
            col_nome = candidato
            break

    resultado = {
        "periodo": periodo_api,
        "termo": termo,
        "cadastro_total": len(df_cad),
        "valores_total": len(df_val),
        "cadastro_match": [],
        "codinst_match": [],
        "vars_resumo_match": [],
        "erro": None,
    }

    if df_cad.empty or not col_nome:
        resultado["erro"] = "cadastro vazio ou coluna de nome não encontrada"
        return resultado

    mask = df_cad[col_nome].astype(str).str.contains(termo, case=False, na=False)
    df_match = df_cad.loc[mask, ["CodInst", col_nome]].drop_duplicates()
    resultado["cadastro_match"] = df_match[col_nome].astype(str).head(10).tolist()
    codinsts = df_match["CodInst"].dropna().astype(str).unique().tolist()
    resultado["codinst_match"] = codinsts

    if not codinsts or df_val.empty:
        return resultado

    df_val = df_val.copy()
    if "NomeColuna" in df_val.columns:
        df_val["NomeColuna"] = df_val["NomeColuna"].apply(_normalizar_nome_coluna)
    variaveis_norm = set(_normalizar_nome_coluna(v) for v in VARIAVEIS_RESUMO_API)

    df_val = df_val[df_val["CodInst"].astype(str).isin(codinsts)]
    df_val_vars = df_val[df_val["NomeColuna"].isin(variaveis_norm)]
    resultado["vars_resumo_match"] = sorted(df_val_vars["NomeColuna"].dropna().unique().tolist())

    return resultado


def ordenar_bancos_com_alias(bancos: list, dict_aliases: dict = None) -> list:
    """Ordena instituições por nome oficial."""
    _ = dict_aliases

    def sort_key(nome):
        nome = str(nome)
        primeiro_char = nome[0].lower() if nome else "z"
        if primeiro_char.isdigit():
            return (1, nome.lower())
        return (0, nome.lower())

    bancos_validos = {str(banco) for banco in bancos if pd.notna(banco)}
    return sorted(bancos_validos, key=sort_key)


# --- Defaults helpers ---

ITAU_UNIBANCO_CODINST_DEFAULT = "1000080099"
ITAU_UNIBANCO_CONGLOMERADO_DEFAULT = "80099 - ITAU"
ITAU_UNIBANCO_LABEL_DEFAULT = "ITAU - PRUDENCIAL"


def _normalizar_codigo_institucional(valor) -> str:
    """Normaliza CodInst/idBacen para comparação determinística de defaults."""
    if valor is None or pd.isna(valor):
        return ""
    digitos = re.sub(r"\D", "", str(valor))
    return digitos.lstrip("0") or digitos


def _score_label_itau_unibanco(label) -> Optional[int]:
    """Prioriza Itaú Unibanco sem matching por substring (ex.: Itaúna)."""
    if label is None or pd.isna(label):
        return None
    txt = _normalizar_texto_sem_acento(str(label))
    txt_simplificado = re.sub(r"[^A-Z0-9]+", " ", txt).strip()
    tokens = set(txt_simplificado.split())

    if txt in {ITAU_UNIBANCO_LABEL_DEFAULT, "ITAU PRUDENCIAL"}:
        return 0
    if {"ITAU", "PRUDENCIAL"}.issubset(tokens):
        return 1
    if {"ITAU", "UNIBANCO"}.issubset(tokens):
        return 2
    if "ITAU" in tokens and "BANCO" in tokens:
        return 3
    if "ITAU" in tokens and not tokens.intersection({"COOPERATIVA", "FUNCIONARIOS", "CREDITO", "ITAUNA"}):
        return 10
    return None


def _indice_default_itau_unibanco(
    opcoes: list,
    *,
    labels: Optional[list] = None,
    codigos: Optional[list] = None,
    fallback_index: int = 0,
) -> int:
    """Índice default do Itaú Unibanco usando CodInst/idBacen quando disponível."""
    if not opcoes:
        return 0

    alvo_codigo = _normalizar_codigo_institucional(ITAU_UNIBANCO_CODINST_DEFAULT)
    if codigos is not None:
        for idx, codigo in enumerate(codigos[: len(opcoes)]):
            if _normalizar_codigo_institucional(codigo) == alvo_codigo:
                return idx

    labels_busca = labels if labels is not None else opcoes
    candidatos = []
    for idx, label in enumerate(labels_busca[: len(opcoes)]):
        score = _score_label_itau_unibanco(label)
        if score is not None:
            candidatos.append((score, idx))
    if candidatos:
        return min(candidatos, key=lambda item: (item[0], item[1]))[1]

    if 0 <= fallback_index < len(opcoes):
        return fallback_index
    return 0

# Nomes-alvo para defaults (slug normalizado → possíveis matches)
_BANCOS_DEFAULT_SLUGS = [
    ("itau", "itaú"),
    ("santander",),
    ("banco do brasil", "bb"),
    ("btg", "btg pactual"),
    ("bradesco",),
]


def _encontrar_bancos_default(bancos_disponiveis: list, slugs=None) -> list:
    """Encontra bancos nos disponíveis por matching fuzzy de substrings."""
    if slugs is None:
        slugs = _BANCOS_DEFAULT_SLUGS
    resultado = []
    for grupo in slugs:
        encontrado = None
        for slug in grupo:
            for banco in bancos_disponiveis:
                if slug == banco.lower() or slug in banco.lower():
                    encontrado = banco
                    break
            if encontrado:
                break
        if encontrado and encontrado not in resultado:
            resultado.append(encontrado)
    return resultado


def _encontrar_periodo(periodos: list, trimestre: int, ano: int) -> Optional[str]:
    """Encontra um período na lista pelo trimestre e ano."""
    for p in periodos:
        if f"{trimestre}/{ano}" == p or f"{trimestre}/{str(ano)[-2:]}" == p:
            return p
    return None


def _obter_top_instituicoes_por_ativo(df_periodo: pd.DataFrame, top_n: int) -> list[str]:
    """Retorna instituições Top N por Ativo Total para o período de referência."""
    if df_periodo is None or df_periodo.empty or top_n <= 0:
        return []
    if "Instituição" not in df_periodo.columns or "Ativo Total" not in df_periodo.columns:
        return []

    df_top = df_periodo[["Instituição", "Ativo Total"]].copy()
    df_top["Ativo Total"] = pd.to_numeric(df_top["Ativo Total"], errors="coerce")
    df_top = df_top.dropna(subset=["Instituição", "Ativo Total"])
    if df_top.empty:
        return []

    df_top = (
        df_top.sort_values(["Ativo Total", "Instituição"], ascending=[False, True])
        .drop_duplicates(subset=["Instituição"], keep="first")
        .head(int(top_n))
    )
    return df_top["Instituição"].tolist()


def _is_variavel_percentual(variavel: str) -> bool:
    if not variavel:
        return False
    if variavel in VARS_PERCENTUAL:
        return True
    return "Basileia" in variavel


def _to_ptbr_decimal(texto: str) -> str:
    if texto is None:
        return ""
    return str(texto).replace(",", "X").replace(".", ",").replace("X", ".")


def _formatar_numero_ptbr(valor, decimais: int = 2) -> str:
    if valor is None or pd.isna(valor):
        return "N/A"
    try:
        valor_float = float(valor)
    except Exception:
        return "N/A"
    return _to_ptbr_decimal(f"{valor_float:.{decimais}f}")


def _formatar_percentual(valor, decimais: int = 2) -> str:
    if valor is None or pd.isna(valor):
        return "N/A"
    try:
        valor_float = float(valor)
    except Exception:
        return "N/A"
    # Normalização estrutural de escala:
    # - base decimal (0-1)  -> converte para 0-100
    # - base percentual 0-100 -> preserva
    if abs(valor_float) <= 1:
        valor_float *= 100
    return f"{_formatar_numero_ptbr(valor_float, decimais)}%"


def _write_excel_number_or_blank(worksheet, row_idx: int, col_idx: int, valor, cell_format) -> None:
    valor_num = pd.to_numeric(pd.Series([valor]), errors="coerce").iloc[0]
    if pd.isna(valor_num):
        worksheet.write_blank(row_idx, col_idx, None, cell_format)
        return
    worksheet.write_number(row_idx, col_idx, float(valor_num), cell_format)


def _formatar_monetario_br_inteligente(valor, decimais: int = 1, usar_sufixo_mm_maiusculo: bool = False) -> str:
    """Formata valor monetário em pt-BR com unidade automática (MM/bi/tri)."""
    if valor is None or pd.isna(valor):
        return "N/D"
    try:
        valor_float = float(valor)
    except Exception:
        return "N/D"

    abs_v = abs(valor_float)
    sinal = "-" if valor_float < 0 else ""
    sufixo_mm = "MM" if usar_sufixo_mm_maiusculo else "mm"

    if abs_v >= 1_000_000_000_000:
        base = _to_ptbr_decimal(f"{abs_v / 1_000_000_000_000:,.{decimais}f}")
        return f"{sinal}R$ {base} tri"
    if abs_v >= 1_000_000_000:
        base = _to_ptbr_decimal(f"{abs_v / 1_000_000_000:,.{decimais}f}")
        return f"{sinal}R$ {base} bi"
    if abs_v >= 1_000_000:
        base = _to_ptbr_decimal(f"{abs_v / 1_000_000:,.{decimais}f}")
        return f"{sinal}R$ {base} {sufixo_mm}"
    base = _to_ptbr_decimal(f"{abs_v:,.2f}")
    return f"{sinal}R$ {base}"


def formatar_valor(valor, variavel):
    if pd.isna(valor) or valor == 0:
        return "N/A"

    if _is_variavel_percentual(variavel):
        return _formatar_percentual(valor)
    elif variavel in VARS_RAZAO:
        return f"{_formatar_numero_ptbr(valor)}x"
    elif variavel in VARS_MOEDAS:
        return _formatar_monetario_br_inteligente(valor, decimais=1, usar_sufixo_mm_maiusculo=True)
    elif variavel in VARS_CONTAGEM:
        return f"{valor:,.0f}".replace(",", ".")
    else:
        return _formatar_numero_ptbr(valor)

def get_axis_format(variavel, serie: Optional[pd.Series] = None):
    if variavel in {'Carteira de Crédito / PL', 'Carteira de Crédito Bruta / PL', 'Crédito/PL (%)', 'Crédito/PL', 'Ativo/PL'}:
        return {'tickformat': '.1f', 'ticksuffix': 'x', 'multiplicador': 1}
    if _is_variavel_percentual(variavel):
        return {'tickformat': '.2f', 'ticksuffix': '%', 'multiplicador': 100}
    elif variavel in VARS_MOEDAS:
        return {'tickformat': ',.0f', 'tickprefix': 'R$ ', 'ticksuffix': ' MM', 'multiplicador': 1/1e6}
    elif variavel in VARS_CONTAGEM:
        return {'tickformat': ',.0f', 'ticksuffix': '', 'multiplicador': 1}
    else:
        return {'tickformat': '.2f', 'ticksuffix': '', 'multiplicador': 1}


def _normalizar_percentual_display(serie: pd.Series, variavel: Optional[str] = None) -> pd.Series:
    serie_num = pd.to_numeric(serie, errors="coerce")
    if serie_num.empty:
        return serie_num

    # Regra de display robusta: valores em base decimal (0-1) viram 0-100.
    # Valores já em 0-100 permanecem sem nova multiplicação.
    mask_decimal = serie_num.abs() <= 1
    serie_display = serie_num.copy()
    serie_display.loc[mask_decimal] = serie_display.loc[mask_decimal] * 100
    return serie_display


def _normalizar_basileia_display(serie: pd.Series) -> pd.Series:
    """Converte Basileia de base decimal (0-1) para display (0-100).

    Os dados de Basileia em dados_periodos são normalizados para base
    decimal (0-1) por _normalizar_indice_para_decimal / recalcular_metricas_derivadas.
    Para display, usa a mediana da série para detectar a escala de forma
    robusta (evitando o heurístico per-value ``abs <= 1`` que falha em
    corner cases como dupla divisão residual).

    - mediana < 1  → série em base decimal  → multiplicar por 100
    - mediana >= 1 → série já em base 0-100 → manter sem multiplicar
    """
    serie_num = pd.to_numeric(serie, errors="coerce")
    if serie_num.empty:
        return serie_num

    serie_valid = serie_num.dropna().abs()
    if serie_valid.empty:
        return serie_num

    med = float(serie_valid.median())

    if med < 1:
        # Base decimal (0-1) → converter para 0-100
        return serie_num * 100
    else:
        # Já em 0-100 → manter
        return serie_num


def _normalizar_capital_principal_display(serie: pd.Series) -> pd.Series:
    """Converte CET1/Capital Principal para display percentual (0-100) de forma robusta.

    Resolve o cenário recorrente de alternância 0.15% vs 15.00% quando há
    dupla divisão residual por 100 em alguma etapa do pipeline.

    Regras (para séries de capital regulatório):
    - q95 < 0.03 e med < 0.02  -> provável dupla divisão -> multiplicar por 10.000
    - med < 1                   -> base decimal normal -> multiplicar por 100
    - med >= 1                  -> já em 0-100         -> manter
    """
    serie_num = pd.to_numeric(serie, errors="coerce")
    if serie_num.empty:
        return serie_num

    serie_valid = serie_num.dropna().abs()
    if serie_valid.empty:
        return serie_num

    q95 = float(serie_valid.quantile(0.95))
    med = float(serie_valid.median())

    if q95 < 0.03 and med < 0.02:
        print(f"[DIAG][PCT][CET1] Reescala 10.000 aplicada: med={med:.6f}, q95={q95:.6f}")
        return serie_num * 10000
    if med < 1:
        return serie_num * 100
    return serie_num


def _normalizar_valor_indicador(valor, variavel: Optional[str]):
    """Normaliza valor bruto para escala interna consistente antes do display.

    Para variáveis percentuais, converte escala 0-100 para decimal (0-1),
    preservando valores já em decimal.
    """
    if valor is None or pd.isna(valor):
        return np.nan

    try:
        valor_num = float(valor)
    except Exception:
        return np.nan

    if _is_variavel_percentual(variavel) and abs(valor_num) > 1:
        return valor_num / 100
    return valor_num


def _selecionar_valor_delta(df_periodo: pd.DataFrame, instituicao: str, coluna_variavel: str):
    """Seleciona valor robusto para cálculo de delta em caso de duplicidades."""
    if df_periodo is None or df_periodo.empty or coluna_variavel not in df_periodo.columns:
        return np.nan

    serie = pd.to_numeric(
        df_periodo.loc[df_periodo['Instituição'] == instituicao, coluna_variavel],
        errors='coerce'
    ).dropna()
    if serie.empty:
        return np.nan

    # Em períodos com linhas duplicadas para a instituição, prioriza maior |valor|,
    # reduzindo chance de capturar registro parcial/stale.
    idx = serie.abs().idxmax()
    return _normalizar_valor_indicador(serie.loc[idx], coluna_variavel)


def _delta_percentual_em_bps(variavel: Optional[str]) -> bool:
    """Indica se o delta percentual deve ser exibido em bps para a variável."""
    if not variavel:
        return False
    return variavel in {
        "Índice de Basileia",
        "Índice de Capital Principal",
        "Índice de Capital Principal (CET1)",
        "Índice de Capital T1 (%)",
        "Índice de Capital T1",
        "Índice de Capital Nível I",
        "Índice de Capital Nivel I",
        "Índice Capital Nível I",
        "Índice Capital Nivel I",
        "Índice Capital T1",
    }


def _classificar_par_periodos(p1: str, p2: str) -> str:
    """Classifica par de períodos para lógica de comparação delta.

    Retorna:
        'coincidente' — mesmo trimestre, anos diferentes (ex: 3/2025 vs 3/2024)
        'consecutivo' — trimestres consecutivos, exatamente 3 meses de distância
        'nao_consecutivo' — trimestres não-consecutivos (> 3 meses, trimestres diferentes)
    """
    t1, a1 = int(p1.split('/')[0]), int(p1.split('/')[1])
    t2, a2 = int(p2.split('/')[0]), int(p2.split('/')[1])

    if t1 == t2 and a1 != a2:
        return 'coincidente'

    meses_map = {1: 3, 2: 6, 3: 9, 4: 12}
    m1 = a1 * 12 + meses_map[t1]
    m2 = a2 * 12 + meses_map[t2]
    dist = abs(m1 - m2)

    if dist == 3:
        return 'consecutivo'
    return 'nao_consecutivo'


# Indicadores que variam conforme modo tri/acumulado
_INDICADORES_SOMENTE_TRI = {'Lucro Líquido Trimestral', 'ROE Trim. Anualizado (%)'}
_INDICADORES_SOMENTE_ACUM = {'Lucro Líquido Acumulado YTD', 'ROE Ac. Anualizado (%)'}


def _is_indice_capital_display(variavel: Optional[str]) -> bool:
    if not variavel:
        return False
    return any(
        token in variavel
        for token in ("Capital Principal", "CET1")
    )


def _calcular_valores_display(serie: pd.Series, variavel: str, format_info: dict) -> pd.Series:
    if variavel and "Basileia" in variavel:
        return _normalizar_basileia_display(serie)
    if _is_indice_capital_display(variavel):
        return _normalizar_capital_principal_display(serie)
    if variavel in {'Carteira de Crédito / PL', 'Carteira de Crédito Bruta / PL', 'Crédito/PL (%)', 'Crédito/PL', 'Ativo/PL'}:
        return serie * format_info['multiplicador']
    if _is_variavel_percentual(variavel):
        return _normalizar_percentual_display(serie, variavel)
    return serie * format_info['multiplicador']


def _inferir_escala_percentual(valor) -> str:
    try:
        valor_num = float(valor)
    except Exception:
        return "indefinida"
    if pd.isna(valor_num):
        return "indefinida"
    return "0-1" if abs(valor_num) <= 1 else "0-100"


def _normalizar_indice_para_decimal(serie: pd.Series) -> pd.Series:
    """Normaliza índices percentuais (Basileia, CET1, etc.) para base decimal (0-1).

    Detecta valores na escala 0-100 (ex.: 15.55 para 15.55%) e converte para 0-1
    (ex.: 0.1555). Valores já em 0-1 são mantidos. Usa limiar > 1 para detecção
    (índices de capital regulatório típicos ficam entre 5% e 30%, ou 0.05–0.30).
    """
    serie_num = pd.to_numeric(serie, errors="coerce")
    mask_percentual = serie_num.abs() > 1
    if mask_percentual.any():
        serie_num = serie_num.copy()
        serie_num.loc[mask_percentual] = serie_num.loc[mask_percentual] / 100
    return serie_num




def _ajustar_basileia_para_scatter(df: pd.DataFrame) -> pd.DataFrame:
    """Ajuste específico da aba Scatter para evitar dupla divisão por 100.

    Regras:
    - Se vier em 0-100, converte para decimal (0-1).
    - Se aparentar já ter sido dividido duas vezes (ex.: 0.00165 para 16.5%),
      reescala para decimal correto multiplicando por 100.

    Observação: ajuste aplicado apenas para o uso da coluna canônica
    ``Índice de Basileia`` no Scatter.
    """
    if df is None or df.empty or "Índice de Basileia" not in df.columns:
        return df

    df_out = df.copy()
    serie = pd.to_numeric(df_out["Índice de Basileia"], errors="coerce")

    # 1) Normalização padrão para decimal (0-1)
    mask_0_100 = serie.abs() > 1
    if mask_0_100.any():
        serie = serie.copy()
        serie.loc[mask_0_100] = serie.loc[mask_0_100] / 100

    # 2) Correção excepcional: provável dupla divisão por 100
    #    Cenário típico do bug: 0.00165 (deveria 0.165)
    serie_valid = serie.dropna().abs()
    if not serie_valid.empty:
        q95 = float(serie_valid.quantile(0.95))
        med = float(serie_valid.median())
        # Se praticamente toda a distribuição está abaixo de 3%,
        # assume erro de dupla divisão e corrige para base decimal correta.
        if q95 < 0.03 and med < 0.02:
            serie = serie * 100
            print(f"[DIAG][SCATTER][BASILEIA] Reescala aplicada (dupla divisão detectada): med={med:.6f}, q95={q95:.6f}")

    # mantém somente valores positivos plausíveis (sem truncar extremos altos)
    df_out["Índice de Basileia"] = serie
    return df_out

def _log_diagnostico_basileia_scatter(
    df_base: pd.DataFrame,
    eixo_variavel: str,
    eixo_display: str,
    periodo: str,
    contexto: str,
) -> None:
    if eixo_variavel != "Índice de Basileia" or df_base is None or df_base.empty:
        return

    bancos_alvo = [
        "Banco do Brasil",
        "Itaú Unibanco",
    ]
    bancos_registrados = []

    for banco in bancos_alvo:
        mask = df_base["Instituição"].astype(str).str.contains(banco, case=False, na=False)
        if not mask.any():
            print(f"[DIAG][SCATTER][{contexto}] banco não encontrado: {banco} | período={periodo}")
            continue

        row = df_base.loc[mask].iloc[0]
        valor_bruto = row.get(eixo_variavel)
        valor_display = row.get(eixo_display)
        escala = _inferir_escala_percentual(valor_bruto)
        if escala == "0-1":
            transformacao = "display = valor_bruto * 100"
        elif escala == "0-100":
            transformacao = "display = valor_bruto (já em percentual)"
        else:
            transformacao = "display indefinido (valor nulo/não numérico)"

        print(
            f"[DIAG][SCATTER][{contexto}] período={periodo} | banco={row.get('Instituição')} | "
            f"valor_bruto={valor_bruto} | tipo={type(valor_bruto).__name__} | "
            f"escala_inferida={escala} | transformação={transformacao} | "
            f"valor_display={valor_display}"
        )
        bancos_registrados.append(str(row.get("Instituição")))

    # Banco de controle (primeiro disponível fora BB/Itaú)
    mask_controle = ~df_base["Instituição"].astype(str).isin(bancos_registrados)
    if mask_controle.any():
        row = df_base.loc[mask_controle].iloc[0]
        valor_bruto = row.get(eixo_variavel)
        valor_display = row.get(eixo_display)
        escala = _inferir_escala_percentual(valor_bruto)
        if escala == "0-1":
            transformacao = "display = valor_bruto * 100"
        elif escala == "0-100":
            transformacao = "display = valor_bruto (já em percentual)"
        else:
            transformacao = "display indefinido (valor nulo/não numérico)"

        print(
            f"[DIAG][SCATTER][{contexto}] período={periodo} | banco_controle={row.get('Instituição')} | "
            f"valor_bruto={valor_bruto} | tipo={type(valor_bruto).__name__} | "
            f"escala_inferida={escala} | transformação={transformacao} | "
            f"valor_display={valor_display}"
        )

def _garantir_indice_basileia_coluna(df: pd.DataFrame) -> pd.DataFrame:
    """Garante coluna canônica 'Índice de Basileia' para uso no Scatter Plot.

    Usa fallback de colunas equivalentes quando a coluna padrão estiver ausente
    ou com lacunas (ex.: caches legados de capital).
    Normaliza valores para base decimal (0-1) independentemente da fonte.
    """
    if df is None or df.empty:
        return df

    alternativas = [
        'Índice de Basileia Capital',
        'Índice de Basileia (n) = (e) / (j)',
    ]

    df_out = df.copy()

    if 'Índice de Basileia' not in df_out.columns:
        alt_col = next((c for c in alternativas if c in df_out.columns), None)
        if alt_col:
            df_out['Índice de Basileia'] = _normalizar_indice_para_decimal(df_out[alt_col])
        return df_out

    # Preencher lacunas da coluna canônica com alternativas, quando houver
    df_out['Índice de Basileia'] = _normalizar_indice_para_decimal(df_out['Índice de Basileia'])
    for alt_col in alternativas:
        if alt_col in df_out.columns:
            alt_vals = _normalizar_indice_para_decimal(df_out[alt_col])
            df_out['Índice de Basileia'] = df_out['Índice de Basileia'].fillna(alt_vals)

    return df_out


def _normalizar_label_peers(texto: str) -> str:
    if texto is None:
        return ""
    return (
        str(texto)
        .replace("\n", " ")
        .replace("\r", " ")
        .strip()
        .lower()
        .replace(".", "")
        .replace("á", "a")
        .replace("à", "a")
        .replace("ã", "a")
        .replace("â", "a")
        .replace("é", "e")
        .replace("ê", "e")
        .replace("í", "i")
        .replace("ó", "o")
        .replace("ô", "o")
        .replace("õ", "o")
        .replace("ú", "u")
        .replace("ç", "c")
    )


def _resolver_coluna_peers(df: pd.DataFrame, candidatos: list) -> Optional[str]:
    if df is None or df.empty:
        return None
    for candidato in candidatos:
        if candidato in df.columns:
            return candidato
    candidatos_norm = [_normalizar_label_peers(c) for c in candidatos]
    for col in df.columns:
        col_norm = _normalizar_label_peers(col)
        if col_norm in candidatos_norm:
            return col
    for col in df.columns:
        col_norm = _normalizar_label_peers(col)
        if any(cand in col_norm for cand in candidatos_norm):
            return col
    return None


def _resolver_colunas_peers(df: pd.DataFrame, candidatos: list) -> list[str]:
    if df is None or df.empty:
        return []
    resolved: list[str] = []
    seen: set[str] = set()
    for candidato in candidatos:
        coluna = _resolver_coluna_peers(df, [candidato])
        if coluna and coluna not in seen:
            resolved.append(coluna)
            seen.add(coluna)
    return resolved


def _formatar_valor_peers(valor, format_key: str, coluna_origem: Optional[str] = None) -> str:
    if valor is None or pd.isna(valor):
        return "N/D"
    if format_key in PEERS_PERCENT_DECIMALS:
        try:
            return _formatar_percentual(float(valor), decimais=PEERS_PERCENT_DECIMALS[format_key])
        except Exception:
            return "N/D"
    if format_key == "Ativo/PL":
        try:
            return f"{_formatar_numero_ptbr(float(valor), 2)}x"
        except Exception:
            return "N/D"
    if format_key in ("Crédito/PL (%)", "Carteira de Crédito Bruta / PL"):
        try:
            return f"{_formatar_numero_ptbr(float(valor), 2)}x"
        except Exception:
            return "N/D"
    if coluna_origem and "(%)" in coluna_origem:
        try:
            valor_display = _calcular_valores_display(
                pd.Series([float(valor)]),
                coluna_origem,
                get_axis_format(coluna_origem),
            ).iloc[0]
            return _formatar_numero_ptbr(valor_display, 2) + "%"
        except Exception:
            return "N/D"
    return formatar_valor(valor, format_key)


def _fmt_tooltip_mm(valor) -> str:
    """Formata valor numérico em pt-BR com escala monetária automática para tooltip."""
    if valor is None:
        return "N/A"
    try:
        v = float(valor)
        if pd.isna(v):
            return "N/A"
        return _formatar_monetario_br_inteligente(v, decimais=2, usar_sufixo_mm_maiusculo=True)
    except Exception:
        return "N/A"


def _tooltip_ll_peers(df, banco, periodo, coluna, valor):
    """Tooltip para Lucro Líquido (BCB Rel. 1 já publica YTD acumulado)."""
    fmt = _fmt_tooltip_mm
    return f"LL YTD: {fmt(valor)}"


def _tooltip_ratio_peers(label, valor_num, valor_den, valor_ratio):
    """Tooltip para métricas do tipo razão (Ativo/PL, Carteira Bruta/PL, ratios %)."""
    fmt = _fmt_tooltip_mm
    _NOMES_COMPONENTES = {
        "Ativo Total / PL": ("Ativo Total", "PL"),
        "Carteira de Crédito* / PL": ("Carteira de Crédito Bruta", "PL"),
        "Perda Esperada / Carteira de Crédito*": ("Perda Esperada", "Carteira de Crédito Bruta"),
        "Perda Esperada / Est2+3": ("Perda Esperada", "Estágio 2 + Estágio 3"),
        "Carteira de Créd. Class. C4+C5 / Carteira Classificada": ("C4+C5", "Carteira de Crédito Classificada"),
        "Perda Esperada / (Carteira C4 + C5)": ("Perda Esperada", "C4+C5"),
    }
    lines = []
    if label in _NOMES_COMPONENTES:
        n_name, d_name = _NOMES_COMPONENTES[label]
        lines.append(f"{n_name}: {fmt(valor_num)}")
        lines.append(f"{d_name}: {fmt(valor_den)}")
    else:
        lines.append(f"Numerador: {fmt(valor_num)}")
        lines.append(f"Denominador: {fmt(valor_den)}")
    if valor_ratio is not None and not pd.isna(valor_ratio):
        # Leverage ratios (x/PL) show as Nx; other ratios as %
        if "/ PL" in label or "/PL" in label:
            lines.append(f"= {_formatar_numero_ptbr(float(valor_ratio), decimais=2)}x")
        else:
            lines.append(f"= {_formatar_percentual(float(valor_ratio), decimais=PEERS_PERCENT_DECIMALS.get(label, 2))}")
    else:
        lines.append("= N/A")
    return "\n".join(lines)


def _parse_periodo(periodo: str) -> Optional[Tuple[str, int, int]]:
    if not periodo or "/" not in str(periodo):
        return None
    partes = str(periodo).split("/")
    if len(partes) != 2:
        return None
    parte, ano_str = partes
    try:
        ano = int(ano_str)
    except ValueError:
        return None
    return parte, ano, len(ano_str)


def _periodo_ano_anterior(periodo: str) -> Optional[str]:
    parsed = _parse_periodo(periodo)
    if not parsed:
        return None
    parte, ano, ano_len = parsed
    ano_anterior = ano - 1
    if ano_len == 2:
        return f"{parte}/{str(ano_anterior)[-2:]}"
    return f"{parte}/{ano_anterior}"


def _periodo_mesma_estrutura(periodo: str, novo_parte: int) -> Optional[str]:
    parsed = _parse_periodo(periodo)
    if not parsed:
        return None
    parte, ano, ano_len = parsed
    nova_parte = str(novo_parte).zfill(len(str(parte)))
    if ano_len == 2:
        return f"{nova_parte}/{str(ano)[-2:]}"
    return f"{nova_parte}/{ano}"


def _validar_yyyymm_str(valor: str) -> Optional[str]:
    txt = str(valor or "").strip()
    if not re.fullmatch(r"\d{6}", txt):
        return None
    ano = int(txt[:4])
    mes = int(txt[4:6])
    if ano < 1900 or mes < 1 or mes > 12:
        return None
    return txt


def _yyyymm_para_periodo_exibicao(valor: str) -> str:
    yyyymm = _validar_yyyymm_str(valor)
    if not yyyymm:
        return str(valor)
    return f"{yyyymm[4:6]}/{yyyymm[:4]}"


def _bloprud_pick_col(df_src: Optional[pd.DataFrame], candidates: list[str]) -> Optional[str]:
    if df_src is None or df_src.empty:
        return None
    cols = list(df_src.columns)
    lower_map = {str(c).strip().lower(): c for c in cols}
    for cand in candidates:
        key = str(cand).strip().lower()
        if key in lower_map:
            return lower_map[key]
    for cand in candidates:
        key = str(cand).strip().lower()
        for col in cols:
            col_l = str(col).strip().lower()
            if key in col_l or col_l in key:
                return col
    return None


@st.cache_data(ttl=3600, show_spinner=False)
def _listar_periodos_bloprudencial_disponiveis(_cache_token_bloprud: str) -> list[str]:
    """Lista competências YYYYMM disponíveis para BLOPRUDENCIAL.

    Prioriza o parquet do cache manager (coluna DATA_BASE); fallback em arquivos
    locais *BLOPRUDENCIAL*.CSV no cache bruto do app.
    """
    _ = _cache_token_bloprud
    periodos: set[str] = set()

    try:
        manager = get_cache_manager()
        cache = manager.get_cache("bloprudencial") if manager else None
        if cache and cache.arquivo_dados.exists():
            import pyarrow.dataset as ds

            dataset = ds.dataset(cache.arquivo_dados)
            tabela = dataset.to_table(columns=["DATA_BASE"])
            serie = tabela.to_pandas()["DATA_BASE"].astype(str).str.replace(r"\D", "", regex=True).str[:6]
            periodos.update({v for v in serie.dropna().unique().tolist() if _validar_yyyymm_str(v)})
    except Exception:
        pass

    if not periodos:
        try:
            cache_dirs = [
                APP_DIR / "data" / "cache" / "bcb_bloprudencial" / "csv",
                APP_DIR / "data" / "cache" / "bcb_bloprudencial" / "zips",
                APP_DIR,
            ]
            for cache_dir in cache_dirs:
                if not cache_dir.exists():
                    continue
                for path in cache_dir.glob("*BLOPRUDENCIAL*"):
                    match = re.match(r"(\d{6})BLOPRUDENCIAL", path.name.upper())
                    if match:
                        ym = _validar_yyyymm_str(match.group(1))
                        if ym:
                            periodos.add(ym)
        except Exception:
            pass

    return sorted(periodos)


@st.cache_data(ttl=3600, show_spinner=False)
def _carregar_bloprud_conta_por_periodos(
    periodos_yyyymm: tuple[str, ...],
    conta_cosif: Optional[str] = None,
    loader_version: str = "v2",
) -> pd.DataFrame:
    """Carrega/normaliza conta BLOPRUDENCIAL por competência e instituição."""
    _ = loader_version
    conta_norm = re.sub(r"\D", "", str(conta_cosif or ""))
    if not periodos_yyyymm:
        return pd.DataFrame(columns=["DATA_BASE", "Instituição", "CONTA", "NOME_CONTA", "VALOR_CONTA"])

    def _normalizar_bloprud_frame(df_ym: pd.DataFrame, *, yyyymm_fallback: str = "") -> pd.DataFrame:
        if df_ym is None or df_ym.empty:
            return pd.DataFrame(columns=["DATA_BASE", "Instituição", "CONTA", "NOME_CONTA", "VALOR_CONTA"])

        col_conta = _bloprud_pick_col(df_ym, ["CONTA", "Conta", "codigo_conta", "COD_CONTA"])
        col_nome_conta = _bloprud_pick_col(df_ym, ["NOME_CONTA", "Nome_Conta", "nome_conta"])
        col_saldo = _bloprud_pick_col(df_ym, ["SALDO", "Saldo", "VALOR", "Valor"])
        col_data_base = _bloprud_pick_col(df_ym, ["DATA_BASE", "Data_Base", "data_base"])
        col_inst = _bloprud_pick_col(df_ym, ["NOME_INSTITUICAO", "Instituição", "Instituicao"])
        col_congl = _bloprud_pick_col(df_ym, ["NOME_CONGL", "Nome_Congl", "nome_congl"])

        if not col_conta or not col_saldo or (not col_inst and not col_congl):
            return pd.DataFrame(columns=["DATA_BASE", "Instituição", "CONTA", "NOME_CONTA", "VALOR_CONTA"])

        tmp = df_ym.copy()
        tmp["_conta"] = tmp[col_conta].astype(str).str.replace(r"\D", "", regex=True)
        if conta_norm:
            tmp = tmp[tmp["_conta"] == conta_norm].copy()
        if tmp.empty:
            return pd.DataFrame(columns=["DATA_BASE", "Instituição", "CONTA", "NOME_CONTA", "VALOR_CONTA"])

        tmp["VALOR_CONTA"] = pd.to_numeric(tmp[col_saldo], errors="coerce")

        if col_data_base:
            tmp["DATA_BASE"] = tmp[col_data_base].astype(str).str.replace(r"\D", "", regex=True).str[:6]
        else:
            tmp["DATA_BASE"] = str(yyyymm_fallback)

        if col_inst:
            inst_series = tmp[col_inst].astype(str).str.strip()
        else:
            inst_series = pd.Series([""] * len(tmp), index=tmp.index)
        if col_congl:
            congl_series = tmp[col_congl].astype(str).str.strip()
        else:
            congl_series = pd.Series([""] * len(tmp), index=tmp.index)

        tmp["Instituição"] = inst_series.where(inst_series.ne(""), congl_series)
        if col_nome_conta:
            tmp["NOME_CONTA"] = tmp[col_nome_conta].astype(str).str.strip()
        else:
            tmp["NOME_CONTA"] = ""
        tmp["CONTA"] = tmp["_conta"]
        return tmp[["DATA_BASE", "Instituição", "CONTA", "NOME_CONTA", "VALOR_CONTA"]].dropna(
            subset=["DATA_BASE", "Instituição", "CONTA"]
        )

    manager = get_cache_manager()
    cache_bloprud = manager.get_cache("bloprudencial") if manager else None
    if cache_bloprud is not None and cache_bloprud.existe():
        resultado_cache = cache_bloprud.carregar_local()
        if resultado_cache.sucesso and resultado_cache.dados is not None and not resultado_cache.dados.empty:
            df_cache = resultado_cache.dados.copy()
            periodos_validos = {p for p in (_validar_yyyymm_str(ym) for ym in sorted(set(periodos_yyyymm))) if p}
            if "DATA_BASE" in df_cache.columns:
                df_cache["DATA_BASE"] = df_cache["DATA_BASE"].astype(str).str.replace(r"\D", "", regex=True).str[:6]
                if periodos_validos:
                    df_cache = df_cache[df_cache["DATA_BASE"].isin(periodos_validos)].copy()
            elif "Período" in df_cache.columns:
                df_cache["DATA_BASE"] = df_cache["Período"].astype(str).str.replace(r"\D", "", regex=True).str[:6]
                if periodos_validos:
                    df_cache = df_cache[df_cache["DATA_BASE"].isin(periodos_validos)].copy()
            df_cache_norm = _normalizar_bloprud_frame(df_cache)
            if not df_cache_norm.empty:
                base = df_cache_norm.copy()
                base["DATA_BASE"] = base["DATA_BASE"].astype(str).str.replace(r"\D", "", regex=True).str[:6]
                base = base[base["DATA_BASE"].map(_validar_yyyymm_str).notna()].copy()
                base["NOME_CONTA"] = base["NOME_CONTA"].fillna("").astype(str).str.strip()
                nome_map = (
                    base.groupby("CONTA", dropna=False)["NOME_CONTA"]
                    .agg(lambda s: next((nome for nome in s if nome), ""))
                    .to_dict()
                )
                ag = (
                    base.groupby(["DATA_BASE", "Instituição", "CONTA"], dropna=False)["VALOR_CONTA"]
                    .sum(min_count=1)
                    .reset_index()
                )
                ag["NOME_CONTA"] = ag["CONTA"].map(nome_map).fillna("")
                return ag

    from utils.ifdata_cache import load_bloprudencial_df_cached

    dfs = []
    for ym in sorted(set(periodos_yyyymm)):
        yyyymm = _validar_yyyymm_str(ym)
        if not yyyymm:
            continue
        df_ym = load_bloprudencial_df_cached(
            yyyymm=yyyymm,
            cache_dir="data/cache/bcb_bloprudencial",
            force_refresh=False,
        )
        tmp = _normalizar_bloprud_frame(df_ym, yyyymm_fallback=yyyymm)
        if tmp.empty:
            continue
        dfs.append(tmp)

    if not dfs:
        return pd.DataFrame(columns=["DATA_BASE", "Instituição", "CONTA", "NOME_CONTA", "VALOR_CONTA"])

    base = pd.concat(dfs, ignore_index=True)
    base["DATA_BASE"] = base["DATA_BASE"].astype(str).str.replace(r"\D", "", regex=True).str[:6]
    base = base[base["DATA_BASE"].map(_validar_yyyymm_str).notna()].copy()
    base["NOME_CONTA"] = base["NOME_CONTA"].fillna("").astype(str).str.strip()
    nome_map = (
        base.groupby("CONTA", dropna=False)["NOME_CONTA"]
        .agg(lambda s: next((nome for nome in s if nome), ""))
        .to_dict()
    )
    ag = (
        base.groupby(["DATA_BASE", "Instituição", "CONTA"], dropna=False)["VALOR_CONTA"]
        .sum(min_count=1)
        .reset_index()
    )
    ag["NOME_CONTA"] = ag["CONTA"].map(nome_map).fillna("")
    return ag


@st.cache_data(ttl=3600, show_spinner=False)
def _catalogo_contas_bloprudencial(
    periodos_yyyymm: tuple[str, ...],
    loader_version: str = "v1",
) -> pd.DataFrame:
    df = _carregar_bloprud_conta_por_periodos(periodos_yyyymm, conta_cosif=None, loader_version=f"catalog_{loader_version}")
    if df.empty:
        return pd.DataFrame(columns=["CONTA", "NOME_CONTA", "LABEL", "VARIANTES_NOME"])

    def _nomes_variantes(series: pd.Series) -> list[str]:
        nomes = [str(v).strip() for v in series.fillna("").tolist() if str(v).strip()]
        return sorted(set(nomes))

    grouped = (
        df.groupby("CONTA", dropna=False)["NOME_CONTA"]
        .agg(_nomes_variantes)
        .reset_index(name="VARIANTES_NOME")
    )
    grouped["NOME_CONTA"] = grouped["VARIANTES_NOME"].apply(lambda nomes: nomes[0] if nomes else "")
    grouped["LABEL"] = grouped.apply(
        lambda row: f"{row['CONTA']} | {row['NOME_CONTA']}" if row["NOME_CONTA"] else f"{row['CONTA']} | (sem nome da conta)",
        axis=1,
    )
    return grouped.sort_values(["CONTA", "NOME_CONTA"]).reset_index(drop=True)


def _conta_bloprudencial_suporta_acumulacao(conta_cosif: Optional[str]) -> bool:
    conta_norm = re.sub(r"\D", "", str(conta_cosif or ""))
    return bool(conta_norm) and conta_norm[:1] in {"7", "8", "9"}


def _modos_disponiveis_conta_bloprudencial(conta_cosif: Optional[str], periodo_referencia: str) -> list[tuple[str, str]]:
    conta_norm = re.sub(r"\D", "", str(conta_cosif or ""))
    ym_ref = _validar_yyyymm_str(periodo_referencia)
    if not conta_norm or not ym_ref:
        return []

    mes = int(ym_ref[4:6])
    if conta_norm[:1] in {"7", "8", "9"}:
        modos = [("acumulado semestral", "acumulado_semestral")]
        if mes in {3, 6, 9, 12}:
            modos.append(("valor do trimestre", "trimestre"))
        return modos
    return [("saldo do período", "saldo_periodo")]


def _periodos_requeridos_fgc(periodo_referencia: str, modo_calculo: str) -> tuple[list[str], str, Optional[str]]:
    ym_ref = _validar_yyyymm_str(periodo_referencia)
    if not ym_ref:
        return [], "", "período de referência inválido."

    ano = ym_ref[:4]
    mes = int(ym_ref[4:6])
    if modo_calculo == "saldo_periodo":
        return [ym_ref], f"Saldo do período = {ym_ref}", None
    if modo_calculo == "acumulado_semestral":
        if mes <= 6:
            return [ym_ref], f"Acumulado semestral = {ym_ref}", None
        ym_jun = f"{ano}06"
        return [ym_jun, ym_ref], f"Acumulado semestral = {ym_ref} + {ym_jun}", None

    if modo_calculo == "trimestre":
        if mes not in {3, 6, 9, 12}:
            return [], "", "modo trimestral exige período de referência em março, junho, setembro ou dezembro."
        if mes == 3:
            return [ym_ref], f"Trimestre = {ym_ref}", None
        if mes == 6:
            ym_base = f"{ano}03"
            return [ym_base, ym_ref], f"Trimestre = {ym_ref} - {ym_base}", None
        if mes == 9:
            return [ym_ref], f"Trimestre = {ym_ref}", None
        ym_base = f"{ano}09"
        return [ym_base, ym_ref], f"Trimestre = {ym_ref} - {ym_base}", None

    return [], "", f"modo de cálculo inválido: {modo_calculo}"


def _calcular_valor_conta_bloprudencial(
    periodo_referencia: str,
    valores_por_mes: dict[str, float],
    modo_calculo: str,
) -> tuple[Optional[float], dict[str, Optional[float] | str], Optional[str]]:
    """Reconstrói conta acumulada por semestre ou trimestre a partir do mês final."""
    ym_ref = _validar_yyyymm_str(periodo_referencia)
    if not ym_ref:
        return None, {"referencia": None, "base": None, "periodo_base": ""}, "período de referência inválido."

    def _valor_mes(ym: str) -> Optional[float]:
        v = valores_por_mes.get(ym)
        if v is None or pd.isna(v):
            return None
        try:
            return float(v)
        except Exception:
            return None

    val_ref = _valor_mes(ym_ref)
    if val_ref is None:
        return None, {"referencia": None, "base": None, "periodo_base": ""}, f"sem valor para o período de referência {ym_ref}."

    ano = ym_ref[:4]
    mes = int(ym_ref[4:6])
    if modo_calculo == "saldo_periodo":
        return val_ref, {"referencia": val_ref, "base": None, "periodo_base": ""}, None
    if modo_calculo == "acumulado_semestral":
        if mes <= 6:
            return val_ref, {"referencia": val_ref, "base": None, "periodo_base": ""}, None
        ym_base = f"{ano}06"
        val_base = _valor_mes(ym_base)
        if val_base is None:
            return None, {"referencia": val_ref, "base": None, "periodo_base": ym_base}, f"sem valor de junho ({ym_base}) para recompor o 2º semestre."
        return val_ref + val_base, {"referencia": val_ref, "base": val_base, "periodo_base": ym_base}, None

    if modo_calculo == "trimestre":
        if mes not in {3, 6, 9, 12}:
            return None, {"referencia": val_ref, "base": None, "periodo_base": ""}, "modo trimestral exige referência em março, junho, setembro ou dezembro."
        if mes in {3, 9}:
            return val_ref, {"referencia": val_ref, "base": None, "periodo_base": ""}, None
        ym_base = f"{ano}{'03' if mes == 6 else '09'}"
        val_base = _valor_mes(ym_base)
        if val_base is None:
            return None, {"referencia": val_ref, "base": None, "periodo_base": ym_base}, f"sem valor base {ym_base} para isolar o trimestre."
        return val_ref - val_base, {"referencia": val_ref, "base": val_base, "periodo_base": ym_base}, None

    return None, {"referencia": val_ref, "base": None, "periodo_base": ""}, f"modo de cálculo inválido: {modo_calculo}"


@st.cache_data(ttl=3600, show_spinner=False)
def _carregar_fgc_8118500009_por_periodos(periodos_yyyymm: tuple[str, ...], loader_version: str = "v1") -> pd.DataFrame:
    """Compat: mantém a carga da conta COSIF 8118500009 por competência e instituição."""
    df = _carregar_bloprud_conta_por_periodos(
        periodos_yyyymm=periodos_yyyymm,
        conta_cosif="8118500009",
        loader_version=f"compat_{loader_version}",
    )
    if df.empty:
        return pd.DataFrame(columns=["DATA_BASE", "Instituição", "FGC_8118500009"])
    out = df.rename(columns={"VALOR_CONTA": "FGC_8118500009"})[["DATA_BASE", "Instituição", "FGC_8118500009"]].copy()
    return out


def _parte_periodo_para_trimestre_idx(valor) -> Optional[int]:
    """Normaliza parte do período para índice trimestral (1..4).

    Aceita formatos com trimestre (1/2/3/4) e mensal trimestral (03/06/09/12).
    """
    parte_txt = str(valor).strip()

    # Primeiro resolve formatos mensais trimestrais com zero à esquerda.
    if parte_txt == "03":
        return 1
    if parte_txt == "06":
        return 2
    if parte_txt == "09":
        return 3
    if parte_txt == "12":
        return 4

    try:
        parte = int(parte_txt)
    except Exception:
        return None

    if parte in (1, 2, 3, 4):
        return parte
    if parte == 6:
        return 2
    if parte == 9:
        return 3
    if parte == 12:
        return 4
    return None


def _periodo_dez_ano_anterior(periodo: str) -> Optional[str]:
    """Retorna período de dezembro do ano anterior respeitando formato da parte.

    Exemplos:
    - 3/2025  -> 4/2024
    - 03/2025 -> 12/2024
    - 09/25   -> 12/24
    """
    parsed = _parse_periodo(periodo)
    if not parsed:
        return None

    parte, ano, ano_len = parsed
    try:
        parte_int = int(str(parte).strip())
    except Exception:
        return None

    parte_txt = str(parte).strip()
    if parte_txt in ("03", "06", "09", "12"):
        parte_dez = "12"
    elif parte_int in (1, 2, 3, 4):
        parte_dez = "4"
    elif parte_int in (6, 9, 12):
        parte_dez = "12"
    else:
        # fallback conservador para formato trimestral
        parte_dez = "4"

    ano_ant = ano - 1
    ano_txt = str(ano_ant)[-2:] if ano_len == 2 else str(ano_ant)
    return f"{parte_dez}/{ano_txt}"


def _aplicar_base_trimestral_dre(df: pd.DataFrame, df_valores_raw: pd.DataFrame) -> pd.DataFrame:
    """Converte linhas da DRE para base trimestral usando valores brutos (pré-YTD).

    Regras (base semestral do IFData):
      - 03: valor cru 03
      - 06: valor cru 06 - valor cru 03
      - 09: valor cru 09 (reset do 2º semestre)
      - 12: valor cru 12 - valor cru 09
    """
    if df is None or df.empty or "Label" not in df.columns or "ytd" not in df.columns:
        return df
    if df_valores_raw is None or df_valores_raw.empty:
        return df

    out = df.copy()
    raw = df_valores_raw.copy()

    if "Periodo" not in raw.columns or "Label" not in raw.columns or "valor" not in raw.columns:
        return out

    raw["valor"] = pd.to_numeric(raw["valor"], errors="coerce")
    if "ano" not in raw.columns or "mes" not in raw.columns:
        raw[["ano", "mes"]] = extrair_ano_mes_periodo(raw["Periodo"])

    key_cols = [c for c in ["Instituicao", "Label", "ano"] if c in raw.columns and c in out.columns]
    if not key_cols:
        return out

    raw = raw.dropna(subset=["mes"]).copy()
    raw["mes"] = pd.to_numeric(raw["mes"], errors="coerce")
    raw = raw[raw["mes"].isin([3, 6, 9, 12])]
    if raw.empty:
        return out

    piv = raw.pivot_table(index=key_cols, columns="mes", values="valor", aggfunc="last")

    def _serie_mes_ou_nan(mes_ref: int) -> pd.Series:
        if mes_ref in piv.columns:
            return pd.to_numeric(piv[mes_ref], errors="coerce")
        return pd.Series(np.nan, index=piv.index, dtype="float64")

    v3 = _serie_mes_ou_nan(3)
    v6 = _serie_mes_ou_nan(6)
    v9 = _serie_mes_ou_nan(9)
    v12 = _serie_mes_ou_nan(12)

    tri = pd.DataFrame(index=piv.index)
    tri[3] = v3
    tri[6] = v6 - v3
    tri[9] = v9
    tri[12] = v12 - v9

    mes_out = out.get("mes")
    if mes_out is None:
        return out

    for mes_ref in [3, 6, 9, 12]:
        mask_mes = mes_out.eq(mes_ref)
        if not mask_mes.any():
            continue
        idx = pd.MultiIndex.from_frame(out.loc[mask_mes, key_cols])
        novos = pd.to_numeric(tri[mes_ref].reindex(idx).to_numpy(), errors="coerce")
        out.loc[mask_mes, "ytd"] = novos

    return out


def _normalizar_lucro_liquido(df: pd.DataFrame) -> pd.DataFrame:
    """Normaliza LL para YTD consistente e calcula LL Trimestral.

    Regras (IF.data com acumulação semestral):
      - Q1 (Mar): LL_trimestral = LL(03)
      - Q2 (Jun): LL_trimestral = LL(06) - LL(03)
      - Q3 (Set): LL_trimestral = LL(09)
      - Q4 (Dez): LL_trimestral = LL(12) - LL(09)
    """
    def _calcular_ll_ytd(raw_map: dict[int, float], tri_idx: int) -> float:
        ll_db = raw_map.get(tri_idx)
        if pd.isna(ll_db):
            return np.nan
        if tri_idx in (1, 2):
            return ll_db
        if tri_idx in (3, 4):
            ll_jun = raw_map.get(2)
            return ll_jun + ll_db if pd.notna(ll_jun) else np.nan
        return np.nan

    def _calcular_ll_trimestral(raw_map: dict[int, float], tri_idx: int) -> float:
        ll_db = raw_map.get(tri_idx)
        if pd.isna(ll_db):
            return np.nan
        if tri_idx in (1, 3):
            return ll_db
        if tri_idx == 2:
            ll_mar = raw_map.get(1)
            return ll_db - ll_mar if pd.notna(ll_mar) else np.nan
        if tri_idx == 4:
            ll_set = raw_map.get(3)
            return ll_db - ll_set if pd.notna(ll_set) else np.nan
        return np.nan

    col_ll = "Lucro Líquido Acumulado YTD"
    if df is None or df.empty or col_ll not in df.columns:
        return df

    out = df.copy()
    out["Lucro Líquido Trimestral"] = np.nan
    ll_ytd_ajustado = pd.Series(np.nan, index=out.index, dtype="float64")

    periodo_split = out["Período"].astype(str).str.split("/", expand=True)
    out["_tri_tmp"] = pd.to_numeric(periodo_split[0], errors="coerce")
    out["_tri_idx_tmp"] = out["_tri_tmp"].map(_parte_periodo_para_trimestre_idx)
    out["_ano_tmp"] = pd.to_numeric(periodo_split[1], errors="coerce")

    for (_, _), idx in out.groupby(["Instituição", "_ano_tmp"], dropna=False, observed=False).groups.items():
        g = out.loc[idx].copy().sort_values("_tri_idx_tmp")
        raw_map = g.set_index("_tri_idx_tmp")[col_ll].to_dict()

        for row_idx, tri in zip(g.index, g["_tri_idx_tmp"]):
            tri_int = int(tri) if pd.notna(tri) else None
            if tri_int is None:
                out.at[row_idx, "Lucro Líquido Trimestral"] = np.nan
                ll_ytd_ajustado.at[row_idx] = out.at[row_idx, col_ll]
                continue

            out.at[row_idx, "Lucro Líquido Trimestral"] = _calcular_ll_trimestral(raw_map, tri_int)
            ll_ytd_ajustado.at[row_idx] = _calcular_ll_ytd(raw_map, tri_int)

    out[col_ll] = ll_ytd_ajustado.where(out["_tri_idx_tmp"].notna(), out[col_ll])
    out = out.drop(columns=["_tri_tmp", "_tri_idx_tmp", "_ano_tmp"], errors="ignore")
    return out


def _recalcular_roe_anualizado_df(df: pd.DataFrame) -> pd.DataFrame:
    """Recalcula ROE anualizado no dataframe consolidado (multi-períodos).

    Pré-condição recomendada: LL já normalizado para YTD consistente
    via ``_normalizar_lucro_liquido``.
    """
    if df is None or df.empty:
        return df
    if not {"Instituição", "Período", "Lucro Líquido Acumulado YTD", "Patrimônio Líquido"}.issubset(df.columns):
        return df

    out = df.copy()
    periodo_split = out["Período"].astype(str).str.split("/", expand=True)
    tri = pd.to_numeric(periodo_split[0], errors="coerce")
    ano = pd.to_numeric(periodo_split[1], errors="coerce")

    out["_tri_tmp"] = tri
    out["_tri_idx_tmp"] = out["_tri_tmp"].map(_parte_periodo_para_trimestre_idx)
    out["_ano_tmp"] = ano
    out["_mes_tmp"] = out["_tri_idx_tmp"].map({1: 3, 2: 6, 3: 9, 4: 12}).fillna(12)

    pl_num = pd.to_numeric(out["Patrimônio Líquido"], errors="coerce")
    ll_num = pd.to_numeric(out["Lucro Líquido Acumulado YTD"], errors="coerce")

    # PL de dezembro do ano anterior por instituição/ano.
    pl_dez = (
        out[out["_tri_idx_tmp"] == 4]
        .dropna(subset=["_ano_tmp"])
        .sort_values(["Instituição", "_ano_tmp", "Período"])
        .drop_duplicates(subset=["Instituição", "_ano_tmp"], keep="last")
        .set_index(["Instituição", "_ano_tmp"])["Patrimônio Líquido"]
    )

    idx_prev = pd.MultiIndex.from_arrays(
        [out["Instituição"].values, (out["_ano_tmp"] - 1).values],
        names=["Instituição", "_ano_tmp"],
    )
    pl_dez_prev = pd.to_numeric(pl_dez.reindex(idx_prev).to_numpy(), errors="coerce")

    roe = _calcular_roe_anualizado(ll_num, pl_num, pl_dez_prev, out["_mes_tmp"])
    out["ROE Ac. Anualizado (%)"] = roe
    out["ROE Ac. YTD an. (%)"] = roe

    return out.drop(columns=["_tri_tmp", "_tri_idx_tmp", "_ano_tmp", "_mes_tmp"], errors="ignore")


def _recalcular_roe_trimestral_df(df: pd.DataFrame) -> pd.DataFrame:
    """Calcula ROE trimestral anualizado com PL médio (Dez ano anterior vs período)."""
    if df is None or df.empty:
        return df
    cols_obrig = {"Instituição", "Período", "Lucro Líquido Trimestral", "Patrimônio Líquido"}
    if not cols_obrig.issubset(df.columns):
        return df

    out = df.copy()
    periodo_split = out["Período"].astype(str).str.split("/", expand=True)
    out["_tri_tmp"] = pd.to_numeric(periodo_split[0], errors="coerce")
    out["_tri_idx_tmp"] = out["_tri_tmp"].map(_parte_periodo_para_trimestre_idx)
    out["_ano_tmp"] = pd.to_numeric(periodo_split[1], errors="coerce")

    out["ROE trimestral anualizado (%)"] = np.nan

    for instituicao, idx in out.groupby("Instituição", dropna=False, observed=False).groups.items():
        _ = instituicao
        g = out.loc[idx].copy().sort_values(["_ano_tmp", "_tri_idx_tmp", "Período"])
        pl_atual = pd.to_numeric(g["Patrimônio Líquido"], errors="coerce")

        pl_dez_por_ano = (
            g[g["_tri_idx_tmp"] == 4]
            .dropna(subset=["_ano_tmp"])
            .sort_values(["_ano_tmp", "Período"])
            .drop_duplicates(subset=["_ano_tmp"], keep="last")
            .set_index("_ano_tmp")["Patrimônio Líquido"]
        )
        idx_prev_ano = (g["_ano_tmp"] - 1).values
        pl_dez_anterior = pd.to_numeric(pl_dez_por_ano.reindex(idx_prev_ano).to_numpy(), errors="coerce")

        ll_trimestral = pd.to_numeric(g["Lucro Líquido Trimestral"], errors="coerce")
        pl_medio = (pl_atual + pl_dez_anterior) / 2
        ll_anualizado = ll_trimestral * 4
        roe_tri = ll_anualizado / pl_medio.where(pl_medio > 0, np.nan) * 100
        out.loc[g.index, "ROE trimestral anualizado (%)"] = roe_tri.to_numpy()

    return out.drop(columns=["_tri_tmp", "_tri_idx_tmp", "_ano_tmp"], errors="ignore")


def _formatar_ptbr_memoria_roe(valor, tipo: str = "monetario") -> str:
    """Formata valores da memória de cálculo em padrão pt-BR."""
    if valor is None or pd.isna(valor):
        return "—"
    try:
        valor_f = float(valor)
    except Exception:
        return "—"

    if tipo == "percentual":
        base = f"{valor_f:,.2f}%"
        return base.replace(",", "X").replace(".", ",").replace("X", ".")

    return _formatar_monetario_br_inteligente(valor_f, decimais=2, usar_sufixo_mm_maiusculo=True)


def _build_memoria_calculo_roe_rankings(df_base: pd.DataFrame, instituicoes: list[str], periodos: list[str]) -> pd.DataFrame:
    """Monta memória de cálculo do ROE trimestral por IF e período."""
    if df_base is None or df_base.empty:
        return pd.DataFrame()

    cols_req = {"Instituição", "Período", "Lucro Líquido Acumulado YTD", "Patrimônio Líquido"}
    if not cols_req.issubset(df_base.columns):
        return pd.DataFrame()

    recorte = df_base[
        (df_base["Instituição"].isin(instituicoes))
        & (df_base["Período"].isin(periodos))
    ].copy()
    if recorte.empty:
        return pd.DataFrame()

    periodo_split = recorte["Período"].astype(str).str.split("/", expand=True)
    recorte["_tri_idx"] = pd.to_numeric(periodo_split[0], errors="coerce").map(_parte_periodo_para_trimestre_idx)
    recorte["_ano"] = pd.to_numeric(periodo_split[1], errors="coerce")
    recorte = recorte.dropna(subset=["_tri_idx", "_ano"]).copy()
    if recorte.empty:
        return pd.DataFrame()

    recorte["_tri_idx"] = recorte["_tri_idx"].astype(int)
    recorte["_ano"] = recorte["_ano"].astype(int)
    recorte["ll_reportado"] = pd.to_numeric(recorte["Lucro Líquido Acumulado YTD"], errors="coerce")
    recorte["ll_trimestral"] = pd.to_numeric(recorte.get("Lucro Líquido Trimestral"), errors="coerce") if "Lucro Líquido Trimestral" in recorte.columns else np.nan
    recorte["pl_db"] = pd.to_numeric(recorte["Patrimônio Líquido"], errors="coerce")

    idx_last = recorte.groupby(["Instituição", "_ano", "_tri_idx"], observed=False).tail(1).index
    recorte = recorte.loc[idx_last].copy()

    lookup = recorte.set_index(["Instituição", "_ano", "_tri_idx"])

    # --- Lookup auxiliar: incluir períodos de dezembro do ano anterior, buscando de
    # df_base (sem filtro de período) para que pl_dez_ant não fique NaN.
    periodos_auxiliares: set[str] = set()
    for _per in periodos:
        per_dez = _periodo_dez_ano_anterior(_per)
        if per_dez:
            periodos_auxiliares.add(per_dez)
    periodos_auxiliares -= set(periodos)

    if periodos_auxiliares:
        _aux = df_base[
            df_base["Instituição"].isin(instituicoes)
            & df_base["Período"].isin(periodos_auxiliares)
        ].copy()
        if not _aux.empty:
            _ps = _aux["Período"].astype(str).str.split("/", expand=True)
            _aux["_tri_idx"] = pd.to_numeric(_ps[0], errors="coerce").map(_parte_periodo_para_trimestre_idx)
            _aux["_ano"] = pd.to_numeric(_ps[1], errors="coerce")
            _aux = _aux.dropna(subset=["_tri_idx", "_ano"]).copy()
            _aux["_tri_idx"] = _aux["_tri_idx"].astype(int)
            _aux["_ano"] = _aux["_ano"].astype(int)
            _aux["ll_reportado"] = pd.to_numeric(_aux.get("Lucro Líquido Acumulado YTD"), errors="coerce")
            _aux["ll_trimestral"] = pd.to_numeric(_aux.get("Lucro Líquido Trimestral"), errors="coerce") if "Lucro Líquido Trimestral" in _aux.columns else np.nan
            _aux["pl_db"] = pd.to_numeric(_aux["Patrimônio Líquido"], errors="coerce")
            _idx_last_aux = _aux.groupby(["Instituição", "_ano", "_tri_idx"], observed=False).tail(1).index
            _aux = _aux.loc[_idx_last_aux].copy()
            _lookup_aux = _aux.set_index(["Instituição", "_ano", "_tri_idx"])
            lookup = pd.concat([_lookup_aux, lookup])
            lookup = lookup[~lookup.index.duplicated(keep="last")]

    componentes_ordem = [
        "LL acumulado YTD (R$)",
        "LL trimestral (R$)",
        "LL trimestral × 4 (R$)",
        "PL data-base (R$)",
        "PL dez/anterior (R$)",
        "PL médio (R$)",
        "= (LL trim × 4) / PL médio",
    ]
    rows = []
    for instituicao in instituicoes:
        for periodo in periodos:
            partes = str(periodo).split("/")
            if len(partes) != 2:
                continue
            tri = _parte_periodo_para_trimestre_idx(partes[0])
            ano = pd.to_numeric(partes[1], errors="coerce")
            if tri is None or pd.isna(ano):
                continue
            ano = int(ano)

            if (instituicao, ano, tri) in lookup.index:
                base = lookup.loc[(instituicao, ano, tri)]
                ll_reportado = pd.to_numeric(base.get("ll_reportado"), errors="coerce")
                ll_tri = pd.to_numeric(base.get("ll_trimestral"), errors="coerce") if "ll_trimestral" in lookup.columns else np.nan
                pl_db = pd.to_numeric(base.get("pl_db"), errors="coerce")
            else:
                ll_reportado = np.nan
                ll_tri = np.nan
                pl_db = np.nan

            ll_x4 = ll_tri * 4 if pd.notna(ll_tri) else np.nan
            pl_dez_ant = pd.to_numeric(lookup["pl_db"].get((instituicao, ano - 1, 4), np.nan), errors="coerce")
            pl_medio = (pl_dez_ant + pl_db) / 2 if pd.notna(pl_dez_ant) and pd.notna(pl_db) else np.nan
            roe_formula = np.nan
            if pd.notna(pl_medio) and pl_medio > 0 and pd.notna(ll_x4):
                roe_formula = (ll_x4 / pl_medio) * 100

            valores = [
                ll_reportado,
                ll_tri,
                ll_x4,
                pl_db,
                pl_dez_ant,
                pl_medio,
                roe_formula,
            ]
            for ordem, (comp, valor) in enumerate(zip(componentes_ordem, valores), start=1):
                rows.append(
                    {
                        "Instituição": instituicao,
                        "Período": periodo,
                        "componente": comp,
                        "valor": valor,
                        "ordem": ordem,
                    }
                )

    return pd.DataFrame(rows)


def _build_memoria_calculo_cet1_rankings(
    df_base: pd.DataFrame, instituicoes: list[str], periodos: list[str]
) -> pd.DataFrame:
    """Monta memória de cálculo do CET1 (Capital Principal / RWA Total) por IF e período."""
    if df_base is None or df_base.empty:
        return pd.DataFrame()
    cols_req = {"Instituição", "Período", "Capital Principal", "RWA Total"}
    if not cols_req.issubset(df_base.columns):
        return pd.DataFrame()

    recorte = df_base[
        (df_base["Instituição"].isin(instituicoes)) & (df_base["Período"].isin(periodos))
    ].drop_duplicates(subset=["Instituição", "Período"], keep="last").copy()
    if recorte.empty:
        return pd.DataFrame()

    componentes_ordem = [
        "Capital Principal (R$ MM)",
        "RWA Total (R$ MM)",
        "= Capital Principal ÷ RWA Total",
    ]
    rows = []
    for _, row in recorte.iterrows():
        inst = row["Instituição"]
        per = row["Período"]
        cp = pd.to_numeric(row.get("Capital Principal"), errors="coerce")
        rwa = pd.to_numeric(row.get("RWA Total"), errors="coerce")
        cet1 = (cp / rwa * 100) if pd.notna(cp) and pd.notna(rwa) and rwa > 0 else np.nan
        valores = [cp, rwa, cet1]
        for ordem, (comp, val) in enumerate(zip(componentes_ordem, valores), start=1):
            rows.append({"Instituição": inst, "Período": per, "componente": comp, "valor": val, "ordem": ordem})
    return pd.DataFrame(rows)


def _build_memoria_calculo_basileia_rankings(
    df_base: pd.DataFrame, instituicoes: list[str], periodos: list[str]
) -> pd.DataFrame:
    """Monta memória de cálculo do Índice de Basileia por IF e período."""
    if df_base is None or df_base.empty:
        return pd.DataFrame()
    if "Instituição" not in df_base.columns or "Período" not in df_base.columns:
        return pd.DataFrame()
    cols_capital = {"Capital Principal", "RWA Total"}
    if not cols_capital.issubset(df_base.columns):
        return pd.DataFrame()

    recorte = df_base[
        (df_base["Instituição"].isin(instituicoes)) & (df_base["Período"].isin(periodos))
    ].drop_duplicates(subset=["Instituição", "Período"], keep="last").copy()
    if recorte.empty:
        return pd.DataFrame()

    componentes_ordem = [
        "Capital Principal (R$ MM)",
        "Capital Complementar (R$ MM)",
        "Capital Nível II (R$ MM)",
        "PR = CP + CC + N2 (R$ MM)",
        "RWA Total (R$ MM)",
        "= PR ÷ RWA Total",
    ]
    rows = []
    for _, row in recorte.iterrows():
        inst = row["Instituição"]
        per = row["Período"]
        cp = pd.to_numeric(row.get("Capital Principal"), errors="coerce")
        cc = pd.to_numeric(row.get("Capital Complementar", 0), errors="coerce")
        n2 = pd.to_numeric(row.get("Capital Nível II", 0), errors="coerce")
        rwa = pd.to_numeric(row.get("RWA Total"), errors="coerce")
        if pd.isna(cc):
            cc = 0.0
        if pd.isna(n2):
            n2 = 0.0
        pr = (cp + cc + n2) if pd.notna(cp) else np.nan
        basileia = (pr / rwa * 100) if pd.notna(pr) and pd.notna(rwa) and rwa > 0 else np.nan
        valores = [cp, cc, n2, pr, rwa, basileia]
        for ordem, (comp, val) in enumerate(zip(componentes_ordem, valores), start=1):
            rows.append({"Instituição": inst, "Período": per, "componente": comp, "valor": val, "ordem": ordem})
    return pd.DataFrame(rows)


def _build_memoria_calculo_roe_ac_rankings(
    df_base: pd.DataFrame, instituicoes: list[str], periodos: list[str]
) -> pd.DataFrame:
    """Monta memória de cálculo do ROE Ac. Anualizado por IF e período."""
    if df_base is None or df_base.empty:
        return pd.DataFrame()
    cols_req = {"Instituição", "Período", "Lucro Líquido Acumulado YTD", "Patrimônio Líquido"}
    if not cols_req.issubset(df_base.columns):
        return pd.DataFrame()

    recorte = df_base[
        (df_base["Instituição"].isin(instituicoes)) & (df_base["Período"].isin(periodos))
    ].copy()
    if recorte.empty:
        return pd.DataFrame()

    periodo_split = recorte["Período"].astype(str).str.split("/", expand=True)
    recorte["_tri_idx"] = pd.to_numeric(periodo_split[0], errors="coerce").map(_parte_periodo_para_trimestre_idx)
    recorte["_ano"] = pd.to_numeric(periodo_split[1], errors="coerce")
    recorte = recorte.dropna(subset=["_tri_idx", "_ano"]).copy()
    if recorte.empty:
        return pd.DataFrame()

    recorte["_tri_idx"] = recorte["_tri_idx"].astype(int)
    recorte["_ano"] = recorte["_ano"].astype(int)
    recorte["ll_ytd"] = pd.to_numeric(recorte["Lucro Líquido Acumulado YTD"], errors="coerce")
    recorte["pl_db"] = pd.to_numeric(recorte["Patrimônio Líquido"], errors="coerce")

    idx_last = recorte.groupby(["Instituição", "_ano", "_tri_idx"], observed=False).tail(1).index
    recorte = recorte.loc[idx_last].copy()
    lookup = recorte.set_index(["Instituição", "_ano", "_tri_idx"])

    # Lookup auxiliar: incluir dezembro do ano anterior
    periodos_auxiliares: set[str] = set()
    for _per in periodos:
        per_dez = _periodo_dez_ano_anterior(_per)
        if per_dez:
            periodos_auxiliares.add(per_dez)
    periodos_auxiliares -= set(periodos)

    if periodos_auxiliares:
        _aux = df_base[
            df_base["Instituição"].isin(instituicoes) & df_base["Período"].isin(periodos_auxiliares)
        ].copy()
        if not _aux.empty:
            _ps = _aux["Período"].astype(str).str.split("/", expand=True)
            _aux["_tri_idx"] = pd.to_numeric(_ps[0], errors="coerce").map(_parte_periodo_para_trimestre_idx)
            _aux["_ano"] = pd.to_numeric(_ps[1], errors="coerce")
            _aux = _aux.dropna(subset=["_tri_idx", "_ano"]).copy()
            _aux["_tri_idx"] = _aux["_tri_idx"].astype(int)
            _aux["_ano"] = _aux["_ano"].astype(int)
            _aux["ll_ytd"] = pd.to_numeric(_aux.get("Lucro Líquido Acumulado YTD"), errors="coerce")
            _aux["pl_db"] = pd.to_numeric(_aux["Patrimônio Líquido"], errors="coerce")
            _idx_last_aux = _aux.groupby(["Instituição", "_ano", "_tri_idx"], observed=False).tail(1).index
            _aux = _aux.loc[_idx_last_aux].copy()
            _lookup_aux = _aux.set_index(["Instituição", "_ano", "_tri_idx"])
            lookup = pd.concat([_lookup_aux, lookup])
            lookup = lookup[~lookup.index.duplicated(keep="last")]

    _mes_map = {1: 3, 2: 6, 3: 9, 4: 12}
    componentes_ordem = [
        "LL acumulado YTD (R$)",
        "Fator de anualização",
        "LL YTD × fator (R$)",
        "PL data-base (R$)",
        "PL dez/anterior (R$)",
        "PL médio (R$)",
        "= (LL YTD × fator) / PL médio",
    ]
    rows = []
    for instituicao in instituicoes:
        for periodo in periodos:
            partes = str(periodo).split("/")
            if len(partes) != 2:
                continue
            tri = _parte_periodo_para_trimestre_idx(partes[0])
            ano = pd.to_numeric(partes[1], errors="coerce")
            if tri is None or pd.isna(ano):
                continue
            ano = int(ano)
            mes = _mes_map.get(tri, 12)

            if (instituicao, ano, tri) in lookup.index:
                base = lookup.loc[(instituicao, ano, tri)]
                ll_ytd = pd.to_numeric(base.get("ll_ytd"), errors="coerce")
                pl_db = pd.to_numeric(base.get("pl_db"), errors="coerce")
            else:
                ll_ytd = np.nan
                pl_db = np.nan

            fator = _fator_anualizacao(mes)
            ll_anualizado = ll_ytd * fator if pd.notna(ll_ytd) else np.nan
            pl_dez_ant = pd.to_numeric(lookup["pl_db"].get((instituicao, ano - 1, 4), np.nan), errors="coerce")
            pl_medio = (pl_dez_ant + pl_db) / 2 if pd.notna(pl_dez_ant) and pd.notna(pl_db) else np.nan
            roe_formula = np.nan
            if pd.notna(pl_medio) and pl_medio > 0 and pd.notna(ll_anualizado):
                roe_formula = (ll_anualizado / pl_medio) * 100

            # Fator formatado como texto (e.g. "4× (12/3)")
            fator_val = fator

            valores = [ll_ytd, fator_val, ll_anualizado, pl_db, pl_dez_ant, pl_medio, roe_formula]
            for ordem, (comp, val) in enumerate(zip(componentes_ordem, valores), start=1):
                rows.append({
                    "Instituição": instituicao,
                    "Período": periodo,
                    "componente": comp,
                    "valor": val,
                    "ordem": ordem,
                })
    return pd.DataFrame(rows)


def _calcular_roe_alinhado_peers_para_instituicao(df_base: pd.DataFrame, instituicao: str) -> pd.DataFrame:
    """Retorna ROE (critério Peers) por Ano/Tri para uma instituição."""
    if df_base is None or df_base.empty:
        return pd.DataFrame(columns=["Ano", "Tri", "ROE Ac. Anualizado (%)"])

    cols_obrig = {"Instituição", "Período", "Lucro Líquido Acumulado YTD", "Patrimônio Líquido"}
    if not cols_obrig.issubset(df_base.columns):
        return pd.DataFrame(columns=["Ano", "Tri", "ROE Ac. Anualizado (%)"])

    recorte = df_base[df_base["Instituição"] == instituicao].copy()
    if recorte.empty:
        return pd.DataFrame(columns=["Ano", "Tri", "ROE Ac. Anualizado (%)"])

    periodo_split = recorte["Período"].astype(str).str.split("/", expand=True)
    recorte["Ano"] = pd.to_numeric(periodo_split[1], errors="coerce")
    recorte["Tri"] = pd.to_numeric(periodo_split[0], errors="coerce").map(_parte_periodo_para_trimestre_idx)
    recorte = recorte.dropna(subset=["Ano", "Tri"]).copy()
    if recorte.empty:
        return pd.DataFrame(columns=["Ano", "Tri", "ROE Ac. Anualizado (%)"])

    recorte["Ano"] = recorte["Ano"].astype(int)
    recorte["Tri"] = recorte["Tri"].astype(int)

    idx_ult = recorte.groupby(["Ano", "Tri"], observed=False).tail(1).index
    recorte = recorte.loc[idx_ult].sort_values(["Ano", "Tri"]).copy()

    ll = pd.to_numeric(recorte["Lucro Líquido Acumulado YTD"], errors="coerce")
    pl_t = pd.to_numeric(recorte["Patrimônio Líquido"], errors="coerce")

    pl_dez_prev = (
        recorte.assign(_pl=pl_t)
        .loc[recorte["Tri"] == 4]
        .groupby("Ano", observed=False)["_pl"]
        .last()
        .shift(1)
        .rename("_pl_dez_prev")
    )
    recorte = recorte.merge(pl_dez_prev, left_on="Ano", right_index=True, how="left")

    mes = pd.to_numeric(recorte["Tri"], errors="coerce").map({1: 3, 2: 6, 3: 9, 4: 12})
    recorte["ROE Ac. Anualizado (%)"] = pd.to_numeric(
        _calcular_roe_anualizado(ll, pl_t, recorte["_pl_dez_prev"], mes),
        errors="coerce",
    )

    return recorte[["Ano", "Tri", "ROE Ac. Anualizado (%)"]]


def _build_peers_lookup(df: Optional[pd.DataFrame]) -> dict:
    """Cria índice rápido (Instituição, Período) -> linha para lookups repetidos.

    Esta função evita filtros booleanos O(n) em cada célula da tabela de peers.
    O lookup é armazenado em ``df.attrs`` e reutilizado enquanto o DataFrame
    não muda (mesmo shape e mesmas colunas).
    """
    if df is None or df.empty:
        return {}
    if "Instituição" not in df.columns or "Período" not in df.columns:
        return {}

    meta_nova = (len(df), tuple(df.columns))
    meta_existente = df.attrs.get("_peers_lookup_meta")
    lookup_existente = df.attrs.get("_peers_lookup")
    if meta_existente == meta_nova and isinstance(lookup_existente, dict):
        return lookup_existente

    lookup = {}
    lookup_por_codigo = {}
    instituicao_para_codigos = {}
    col_codigo_congl = next(
        (
            c for c in df.columns
            if str(c).strip().lower() in {
                "codigo_conglomerado",
                "código_conglomerado",
                "cod_conglomerado",
                "codigoconglomerado",
                "cod_congl",
            }
        ),
        None,
    )
    # Evita iterrows(): converte para registros e preserva 1ª ocorrência por chave.
    inst_vals = df["Instituição"].tolist()
    per_vals = df["Período"].tolist()
    registros = df.to_dict("records")

    for inst, per, row in zip(inst_vals, per_vals, registros):
        chave = (inst, per)
        if chave not in lookup:
            lookup[chave] = row

        if col_codigo_congl:
            cod = row.get(col_codigo_congl)
            if pd.notna(cod):
                cod_norm = str(cod).strip()
                if cod_norm:
                    chave_cod = (cod_norm, per)
                    if chave_cod not in lookup_por_codigo:
                        lookup_por_codigo[chave_cod] = row
                    inst_norm = normalizar_nome_instituicao(inst)
                    if inst_norm:
                        instituicao_para_codigos.setdefault(inst_norm, set()).add(cod_norm)

    df.attrs["_peers_lookup"] = lookup
    df.attrs["_peers_lookup_por_codigo"] = lookup_por_codigo
    df.attrs["_peers_inst_to_codigos"] = instituicao_para_codigos
    df.attrs["_peers_lookup_meta"] = meta_nova
    return lookup


def _obter_valor_peers(df: pd.DataFrame, banco: str, periodo: str, coluna: Optional[str]):
    if coluna is None or df is None or df.empty:
        return None
    lookup = _build_peers_lookup(df)
    if not lookup:
        return None
    row = lookup.get((banco, periodo))
    if row is None:
        codigos_por_inst = df.attrs.get("_peers_inst_to_codigos", {})
        lookup_por_codigo = df.attrs.get("_peers_lookup_por_codigo", {})
        banco_norm = normalizar_nome_instituicao(banco)
        codigos = codigos_por_inst.get(banco_norm, set()) if banco_norm else set()
        for cod in codigos:
            row = lookup_por_codigo.get((str(cod).strip(), periodo))
            if row is not None:
                break
    if row is None:
        return None
    return row.get(coluna)


def _perf_peers_stage(perf: dict, stage: str, start: float):
    """Registra duração de uma etapa da aba Peers."""
    perf[stage] = perf.get(stage, 0.0) + (time.perf_counter() - start)


def _log_roe_trace(
    df: Optional[pd.DataFrame],
    contexto: str,
    banco_hint: str = "itau",
    periodo_hint: Optional[str] = None,
):
    """Loga insumos do ROE para diagnóstico de consistência entre abas."""
    if df is None or df.empty or not {"Instituição", "Período"}.issubset(df.columns):
        return

    periodos_disponiveis = set(df["Período"].dropna().astype(str).tolist())
    periodo_candidato = str(periodo_hint) if periodo_hint else None
    if periodo_candidato not in periodos_disponiveis:
        periodo_candidato = _periodo_mais_recente(periodos_disponiveis)
    if not periodo_candidato:
        return

    df_periodo = df[df["Período"].astype(str) == str(periodo_candidato)]
    if df_periodo.empty:
        return

    bancos = df_periodo["Instituição"].dropna().astype(str).tolist()
    banco_sel = next((b for b in bancos if banco_hint in normalizar_nome_instituicao(b)), None)
    if not banco_sel:
        return

    linha = df_periodo[df_periodo["Instituição"] == banco_sel].head(1)
    if linha.empty:
        return

    ll = pd.to_numeric(linha.get("Lucro Líquido Acumulado YTD"), errors="coerce").iloc[0] if "Lucro Líquido Acumulado YTD" in linha.columns else np.nan
    pl_t = pd.to_numeric(linha.get("Patrimônio Líquido"), errors="coerce").iloc[0] if "Patrimônio Líquido" in linha.columns else np.nan
    per_dez = _periodo_dez_ano_anterior(periodo_candidato)
    pl_dez_prev = np.nan
    if per_dez:
        df_dez = df[(df["Período"].astype(str) == str(per_dez)) & (df["Instituição"] == banco_sel)]
        if not df_dez.empty and "Patrimônio Líquido" in df_dez.columns:
            pl_dez_prev = pd.to_numeric(df_dez["Patrimônio Líquido"], errors="coerce").iloc[0]

    mes = _extrair_mes_periodo(periodo_candidato, periodo_candidato) or 12
    fator = _fator_anualizacao(mes)
    roe_calc = _calcular_roe_anualizado(ll, pl_t, pl_dez_prev, mes)
    roe_col = np.nan
    if "ROE Ac. Anualizado (%)" in linha.columns:
        roe_col = pd.to_numeric(linha["ROE Ac. Anualizado (%)"], errors="coerce").iloc[0]

    print(
        "[ROE_TRACE]",
        {
            "contexto": contexto,
            "instituicao": banco_sel,
            "periodo": periodo_candidato,
            "ll_ytd": None if pd.isna(ll) else float(ll),
            "pl_t": None if pd.isna(pl_t) else float(pl_t),
            "pl_dez_prev": None if pd.isna(pl_dez_prev) else float(pl_dez_prev),
            "fator_anualizacao": fator,
            "roe_coluna": None if pd.isna(roe_col) else float(roe_col),
            "roe_recalculado": None if roe_calc is None or pd.isna(roe_calc) else float(roe_calc),
        },
    )


def _coerce_numeric_value(valor):
    if valor is None or pd.isna(valor):
        return None
    if isinstance(valor, str):
        cleaned = valor.replace(".", "").replace(",", ".")
        valor = cleaned
    return pd.to_numeric(valor, errors="coerce")


def _somar_valores(valores: list) -> Optional[float]:
    numeros = []
    for valor in valores:
        val_num = _coerce_numeric_value(valor)
        if val_num is not None and not pd.isna(val_num):
            numeros.append(float(val_num))
    if not numeros:
        return None
    return float(sum(numeros))


def _somar_valores_requeridos(valores: list) -> Optional[float]:
    numeros = []
    for valor in valores:
        val_num = _coerce_numeric_value(valor)
        if val_num is None or pd.isna(val_num):
            return None
        numeros.append(float(val_num))
    if not numeros:
        return None
    return float(sum(numeros))


def _periodo_ano_int(periodo_txt: str) -> Optional[int]:
    parsed = _parse_periodo(periodo_txt)
    if not parsed:
        return None
    _, ano, _ = parsed
    return int(ano)


def _calcular_core_funding(
    cache_passivo: Optional[pd.DataFrame],
    instituicao: str,
    periodo: str,
    col_capt: Optional[str],
    col_instr: Optional[str],
    lk_passivo: Optional[dict] = None,
) -> Optional[float]:
    """Core Funding por período: até 2024 usa Captações (e); 2025+ exige Captações (e) + Instrumentos de Dívida Elegíveis a Capital (h)."""
    if cache_passivo is None or cache_passivo.empty:
        return None
    ano_ref = _periodo_ano_int(periodo)
    if lk_passivo is not None:
        row = lk_passivo.get((instituicao, str(periodo)))
        cap_val = row.get(col_capt) if (row is not None and col_capt) else None
    else:
        cap_val = _obter_valor_peers(cache_passivo, instituicao, periodo, col_capt) if col_capt else None
    if ano_ref is None or ano_ref <= 2024:
        return _coerce_numeric_value(cap_val)
    if lk_passivo is not None:
        row = lk_passivo.get((instituicao, str(periodo)))
        instr_val = row.get(col_instr) if (row is not None and col_instr) else None
    else:
        instr_val = _obter_valor_peers(cache_passivo, instituicao, periodo, col_instr) if col_instr else None
    return _coerce_numeric_value(
        resolve_core_funding_value(
            year_ref=ano_ref,
            captacoes_value=cap_val,
            instrumentos_value=instr_val,
        ).get("value")
    )


def _prefer_carteira_bruta(colunas: list) -> str:
    if "Carteira de Crédito" in colunas:
        return "Carteira de Crédito"
    if "Carteira de Crédito Bruta" in colunas:
        return "Carteira de Crédito Bruta"
    return "Carteira de Crédito"


def _ajustar_colunas_core_funding(colunas: list) -> list:
    """Remove Captações quando Core Funding estiver disponível na lista de seleção."""
    if "Core Funding" in colunas and "Captações" in colunas:
        return [c for c in colunas if c != "Captações"]
    return colunas


def _build_scatter_var_options(colunas: list) -> Tuple[list, Dict[str, str]]:
    """Monta opções de variáveis do Scatter com aliases de UI e exclusões."""
    excluidas = {
        "Desp Captação / Captação",
        "Índice de Imobilização",
        "Títulos e Valores Mobiliários",
        "Desp PDD / Resultado Intermediação Fin. Bruto",
        "Crédito/Ativo (%)",
        "Crédito/PL (%)",
        "Crédito/PL",
        "Passivo Exigível",
        "Crédito/Captações (%)",
        "Patrimônio de Referência para Comparação com o RWA (e)",
        "Patrimônio de Referência para Comparação com RWA",
    }
    opcoes_base = [c for c in colunas if c not in excluidas]
    if "Lucro Líquido Trimestral" not in opcoes_base and "Lucro Líquido" in opcoes_base:
        opcoes_base.append("Lucro Líquido Trimestral")
    display_to_internal = {c: c for c in opcoes_base}

    aliases_ui = {
        "Carteira de Crédito": [
            "Carteira de Crédito",
            "Carteira de Crédito*",
            "Carteira de Crédito Bruta",
            "Carteira de Crédito Classificada",
        ],
        "Core Funding": ["Core Funding", "Core Funding*", "Captações"],
        "ROE YTD Ac. Anualizado (%)": ["ROE Ac. Anualizado (%)", "ROE Ac. YTD an. (%)"],
        "Lucro Líquido Trimestral": ["Lucro Líquido Trimestral", "Lucro Líquido"],
        "Carteira de Crédito / PL": ["Carteira de Crédito / PL", "Carteira de Crédito Bruta / PL"],
    }

    for label_ui, candidatos in aliases_ui.items():
        interno = next((c for c in candidatos if c in opcoes_base), None)
        if label_ui == "Lucro Líquido Trimestral" and "Lucro Líquido Trimestral" in opcoes_base:
            interno = "Lucro Líquido Trimestral"
        if not interno:
            continue
        display_to_internal[label_ui] = interno
        if interno in opcoes_base and interno != label_ui:
            opcoes_base = [c for c in opcoes_base if c != interno]
        if label_ui not in opcoes_base:
            opcoes_base.append(label_ui)

    remover_pos_alias = {
        "Carteira de Crédito Classificada",
        "Carteira de Crédito Bruta",
        "Carteira de Crédito*",
        "ROE Ac. YTD an. (%)",
    }
    opcoes_base = [c for c in opcoes_base if c not in remover_pos_alias]

    # Deduplicação automática (Opção 2): se duas labels apontarem para a mesma série interna,
    # mantém apenas a label canônica quando houver (aliases_ui) ou a primeira em ordem alfabética.
    labels_canonicas = set(aliases_ui.keys())
    labels_por_interno = {}
    for label in opcoes_base:
        interno = display_to_internal.get(label, label)
        labels_por_interno.setdefault(interno, []).append(label)

    opcoes_dedup = []
    for interno, labels in labels_por_interno.items():
        labels_ordenadas = sorted(labels, key=lambda x: str(x).lower())
        preferida = next((l for l in labels_ordenadas if l in labels_canonicas), labels_ordenadas[0])
        opcoes_dedup.append(preferida)
        display_to_internal[preferida] = interno

    opcoes_base = sorted(opcoes_dedup, key=lambda x: str(x).lower())
    display_to_internal = {label: display_to_internal[label] for label in opcoes_base}
    return opcoes_base, display_to_internal


def _format_scatter_label_value(valor, format_info: dict, usar_mm_numeral: bool = False) -> str:
    if valor is None or pd.isna(valor):
        return "N/A"
    tickformat = format_info.get('tickformat', '.2f')
    tickprefix = format_info.get('tickprefix', '')
    ticksuffix = format_info.get('ticksuffix', '')
    if usar_mm_numeral and ticksuffix.strip() == 'M':
        ticksuffix = f" {ticksuffix}" if not ticksuffix.startswith(' ') else ticksuffix
    if usar_mm_numeral and ticksuffix.strip() == 'MM' and not ticksuffix.startswith(' '):
        ticksuffix = f" {ticksuffix}"
    try:
        valor_fmt = f"{valor:{tickformat}}"
        if any(ch in tickformat for ch in [",", "f", "g", "%"]):
            valor_fmt = _to_ptbr_decimal(valor_fmt)
        return f"{tickprefix}{valor_fmt}{ticksuffix}"
    except Exception:
        return str(valor)


def _scatter_compor_texto_label(
    instituicao: str,
    x_label: str,
    x_valor,
    format_x: dict,
    y_label: str,
    y_valor,
    format_y: dict,
    size_label: Optional[str] = None,
    size_valor=None,
    format_size: Optional[dict] = None,
) -> str:
    incluir_nome = instituicao is not None and str(instituicao).strip() != ""
    linhas = [instituicao] if incluir_nome else []
    _ = (x_label, y_label)
    linhas.append(f"X: {_format_scatter_label_value(x_valor, format_x, usar_mm_numeral=True)}")
    linhas.append(f"Y: {_format_scatter_label_value(y_valor, format_y, usar_mm_numeral=True)}")
    if size_label and format_size is not None:
        linhas.append(f"Tamanho: {_format_scatter_label_value(size_valor, format_size, usar_mm_numeral=True)}")
    return "<br>".join(linhas)


def _scatter_metric_criteria(label_exibicao: str) -> str:
    criterios = {
        "Core Funding": "Captações (e) no Relatório de Passivo; a partir de 2025, exige-se Captações (e) + Instrumentos de Dívida Elegíveis a Capital (h).",
        "Carteira de Crédito Classificada": "Prioriza Carteira de Crédito Classificada/Carteira de Crédito*; fallback para Carteira de Crédito Bruta/Carteira de Crédito, conforme disponibilidade da base.",
        "ROE YTD Ac. Anualizado (%)": "(LL YTD × fator de anualização) ÷ PL Médio.",
        "Crédito/Ativo (%)": "Carteira de Crédito ÷ Ativo Total.",
        "Carteira de Crédito / PL": "Carteira de Crédito ÷ Patrimônio Líquido.",
        "Carteira de Crédito/Core Funding (%)": "Carteira de Crédito ÷ Core Funding.",
        "Lucro Líquido Trimestral": "Lucro líquido do trimestre de referência (não acumulado YTD).",
    }
    return criterios.get(label_exibicao, "Definição específica não cadastrada; usa série da base principal conforme nome da variável.")


def _scatter_preferred_ui_option(opcoes_ui: list, display_to_internal: Dict[str, str], prefer_internal: str) -> Optional[str]:
    """Retorna a opção de UI preferida para o Top N considerando aliases UI→interno."""
    if prefer_internal in opcoes_ui:
        return prefer_internal
    for opcao in opcoes_ui:
        if display_to_internal.get(opcao, opcao) == prefer_internal:
            return opcao
    return opcoes_ui[0] if opcoes_ui else None


def _scatter_variable_health(df_periodo: pd.DataFrame, opcoes_ui: list, display_to_internal: Dict[str, str]) -> pd.DataFrame:
    linhas = []
    for var_ui in opcoes_ui:
        interno = display_to_internal.get(var_ui, var_ui)
        status = "ausente"
        preenchimento = 0.0
        if interno in df_periodo.columns:
            serie = pd.to_numeric(df_periodo[interno], errors="coerce")
            validos = int(serie.notna().sum())
            total = int(len(serie))
            preenchimento = (validos / total * 100.0) if total > 0 else 0.0
            status = "ok" if validos > 0 else "sem dados"
        linhas.append({
            "Variável (UI)": var_ui,
            "Série interna": interno,
            "Status": status,
            "% preenchimento": preenchimento,
        })
    df_health = pd.DataFrame(linhas)
    if not df_health.empty:
        df_health["% preenchimento"] = df_health["% preenchimento"].round(1)
    return df_health


def _anexar_carteira_credito_bruta(dados_periodos: dict) -> dict:
    """Anexa Carteira de Crédito Bruta (Rel. 2) e uniformiza Carteira de Crédito."""
    if not dados_periodos:
        return dados_periodos
    cache_manager = get_cache_manager()
    if cache_manager is None:
        return dados_periodos
    resultado = cache_manager.carregar("ativo")
    if not resultado or not resultado.sucesso or resultado.dados is None:
        return dados_periodos

    df_ativo = resultado.dados
    if df_ativo is None or df_ativo.empty:
        return dados_periodos

    col_e1 = _resolver_coluna_peers(df_ativo, ["Valor Contábil Bruto (e1)", "Valor Contabil Bruto (e1)"])
    col_f1 = _resolver_coluna_peers(df_ativo, ["Valor Contábil Bruto (f1)", "Valor Contabil Bruto (f1)"])
    col_g1 = _resolver_coluna_peers(df_ativo, ["Valor Contábil Bruto (g1)", "Valor Contabil Bruto (g1)"])
    col_h1 = _resolver_coluna_peers(df_ativo, ["Valor Contábil Bruto (h1)", "Valor Contabil Bruto (h1)"])
    col_d1 = _resolver_coluna_peers(df_ativo, ["Operações de Crédito (d1)", "Operacoes de Credito (d1)"])
    col_e1_alt = _resolver_coluna_peers(df_ativo, ["Arrendamento Mercantil a Receber (e1)", "Arrendamento Mercantil a Receber"])
    col_f_old = _resolver_coluna_peers(
        df_ativo,
        ["Outros Créditos - Líquido de Provisão (f)", "Outros Creditos - Liquido de Provisao (f)", "Outros Créditos - Líquido de Provisão"],
    )
    col_e = _resolver_coluna_peers(df_ativo, ["Operações de Crédito (e)", "Operacoes de Credito (e)"])
    col_f = _resolver_coluna_peers(df_ativo, ["Operações de Arrendamento Financeiro (f)", "Operacoes de Arrendamento Financeiro (f)"])
    col_g = _resolver_coluna_peers(
        df_ativo,
        ["Outras Operações com Características de Concessão de Crédito (g)", "Outras Operacoes com Caracteristicas de Concessao de Credito (g)"],
    )
    col_h = _resolver_coluna_peers(
        df_ativo,
        ["Valores a Receber de Transações de Pagamentos - Usuários Finais (Pós-pago) (h)", "Valores a Receber de Transacoes de Pagamentos - Usuarios Finais (Pos-pago) (h)"],
    )

    cols_relevantes = [
        "Instituição",
        "Período",
        *[col for col in [col_e1, col_f1, col_g1, col_h1, col_d1, col_e1_alt, col_f_old, col_e, col_f, col_g, col_h] if col],
    ]
    if len(cols_relevantes) <= 2:
        return dados_periodos

    df_bruta = df_ativo[cols_relevantes].copy()
    valor_cols = [col for col in cols_relevantes if col not in {"Instituição", "Período"}]
    for col in valor_cols:
        df_bruta[col] = pd.to_numeric(df_bruta[col], errors="coerce")

    def _resolve_row(row: pd.Series) -> object:
        return resolve_carteira_credito_bruta_value(
            year_ref=_periodo_ano_int(row.get("Período")),
            legacy_credito_value=row.get(col_d1) if col_d1 else None,
            legacy_arrendamento_value=row.get(col_e1_alt) if col_e1_alt else None,
            legacy_outros_value=row.get(col_f_old) if col_f_old else None,
            vcb_credito_value=row.get(col_e1) if col_e1 else None,
            vcb_arrendamento_value=row.get(col_f1) if col_f1 else None,
            vcb_outras_ops_value=row.get(col_g1) if col_g1 else None,
            vcb_pagamentos_value=row.get(col_h1) if col_h1 else None,
            net_credito_value=row.get(col_e) if col_e else None,
            net_arrendamento_value=row.get(col_f) if col_f else None,
            net_outras_ops_value=row.get(col_g) if col_g else None,
            net_pagamentos_value=row.get(col_h) if col_h else None,
        ).get("value")

    df_bruta["Carteira de Crédito Bruta"] = df_bruta.apply(_resolve_row, axis=1)
    df_bruta = df_bruta[["Instituição", "Período", "Carteira de Crédito Bruta"]]
    # Garante unicidade por período/instituição para evitar InvalidIndexError no map
    df_bruta = (
        df_bruta.groupby(["Período", "Instituição"], as_index=False)["Carteira de Crédito Bruta"]
        .sum(min_count=1)
    )

    dados_out = {}
    for periodo, df in dados_periodos.items():
        if df is None or df.empty or "Instituição" not in df.columns:
            dados_out[periodo] = df
            continue
        df_out = df.copy()
        sub = df_bruta[df_bruta["Período"].astype(str) == str(periodo)][["Instituição", "Carteira de Crédito Bruta"]]
        if sub.empty:
            dados_out[periodo] = df_out
            continue
        if "Período" in df_out.columns:
            sub = sub.copy()
            sub["Período"] = periodo
            left_df = df_out.set_index(["Período", "Instituição"])
            right_df = sub.set_index(["Período", "Instituição"])
            df_out = left_df.join(right_df, how="left", rsuffix="_bruta").reset_index()
        else:
            df_out = df_out.merge(sub, on="Instituição", how="left", suffixes=("", "_bruta"))
        if "Carteira de Crédito Bruta_bruta" in df_out.columns and "Carteira de Crédito Bruta" in df_out.columns:
            df_out["Carteira de Crédito Bruta"] = df_out["Carteira de Crédito Bruta_bruta"].combine_first(
                df_out["Carteira de Crédito Bruta"]
            )
            df_out = df_out.drop(columns=["Carteira de Crédito Bruta_bruta"])
        # Uniformiza Carteira de Crédito para critério Bruto quando disponível
        if "Carteira de Crédito" in df_out.columns:
            df_out["Carteira de Crédito"] = df_out["Carteira de Crédito Bruta"].combine_first(
                df_out["Carteira de Crédito"]
            )
        dados_out[periodo] = df_out

    return dados_out


def _anexar_core_funding(dados_periodos: dict) -> dict:
    """Anexa Core Funding (Passivo) aos dados por período."""
    if not dados_periodos:
        return dados_periodos
    cache_manager = get_cache_manager()
    if cache_manager is None:
        return dados_periodos
    resultado = cache_manager.carregar("passivo")
    if not resultado or not resultado.sucesso or resultado.dados is None:
        return dados_periodos

    df_passivo = resultado.dados
    if df_passivo is None or df_passivo.empty:
        return dados_periodos

    col_capt = _resolver_coluna_peers(
        df_passivo,
        [
            "Captações (e) = (a) + (b) + (c) + (d)",
            "Captações (e)",
            "Captações",
            "Captacoes (e)",
        ],
    )
    col_instr = _resolver_coluna_peers(
        df_passivo,
        [
            "Instrumentos de Dívida Elegíveis a Capital (h)",
            "Instrumentos de Divida Elegiveis a Capital (h)",
            "Instrumentos de Dívida Elegíveis a Capital",
            "Instrumentos de Divida Elegiveis a Capital",
        ],
    )
    if not col_capt:
        return dados_periodos

    df_tmp = df_passivo[["Instituição", "Período"]].copy()
    df_tmp["_cap"] = pd.to_numeric(df_passivo[col_capt], errors="coerce")
    df_tmp["_instr"] = pd.to_numeric(df_passivo[col_instr], errors="coerce") if col_instr else pd.NA
    df_tmp["_ano"] = df_tmp["Período"].astype(str).map(_periodo_ano_int)
    df_tmp["Core Funding"] = [
        resolve_core_funding_value(
            year_ref=int(ano_ref) if pd.notna(ano_ref) else None,
            captacoes_value=cap_val,
            instrumentos_value=instr_val,
        ).get("value")
        for ano_ref, cap_val, instr_val in zip(df_tmp["_ano"], df_tmp["_cap"], df_tmp["_instr"])
    ]

    df_core = (
        df_tmp.groupby(["Período", "Instituição"], as_index=False)["Core Funding"]
        .sum(min_count=1)
    )

    dados_out = {}
    for periodo, df in dados_periodos.items():
        if df is None or df.empty or "Instituição" not in df.columns:
            dados_out[periodo] = df
            continue
        sub = df_core[df_core["Período"].astype(str) == str(periodo)][["Instituição", "Core Funding"]]
        if sub.empty:
            dados_out[periodo] = df
            continue
        df_out = df.copy()
        if "Período" in df_out.columns:
            sub = sub.copy()
            sub["Período"] = periodo
            left_df = df_out.set_index(["Período", "Instituição"])
            right_df = sub.set_index(["Período", "Instituição"])
            df_out = left_df.join(right_df, how="left", rsuffix="_core").reset_index()
        else:
            df_out = df_out.merge(sub, on="Instituição", how="left", suffixes=("", "_core"))
        if "Core Funding_core" in df_out.columns and "Core Funding" in df_out.columns:
            df_out["Core Funding"] = df_out["Core Funding_core"].combine_first(df_out["Core Funding"])
            df_out = df_out.drop(columns=["Core Funding_core"])
        dados_out[periodo] = df_out

    return dados_out


def _normalizar_nomes_carteira(df: Optional[pd.DataFrame]) -> Optional[pd.DataFrame]:
    if df is None or df.empty:
        return df
    rename_map = {
        "Carteira Bruta": "Carteira Classificada",
        "Perda Esperada / Carteira Bruta": "Perda Esperada / Carteira de Crédito Bruta",
        "Perda Esperada / Carteira Classificada": "Perda Esperada / Carteira de Crédito Bruta",
        "Carteira de Créd. Class. C4+C5 / Carteira Bruta": "Carteira de Créd. Class. C4+C5 / Carteira Classificada",
    }
    rename_cols = {k: v for k, v in rename_map.items() if k in df.columns}
    if not rename_cols:
        return df
    return df.rename(columns=rename_cols)



def _aplicar_aliases_df(df: Optional[pd.DataFrame], dict_aliases: dict) -> Optional[pd.DataFrame]:
    if df is None or df.empty:
        return df
    df_out = _normalizar_nomes_carteira(df.copy())
    if "Instituição" not in df_out.columns:
        return df_out
    _ = dict_aliases
    catalog_map = build_institution_to_conglomerate_map(APP_DIR)
    df_out["Instituição"] = [
        canonicalize_institution_name(nome, catalog_map=catalog_map)
        for nome in df_out["Instituição"].tolist()
    ]
    return df_out


def _instituicoes_filtro_snapshot(banco: str, dict_aliases: dict) -> tuple:
    """Retorna apenas a instituição oficial selecionada."""
    _ = dict_aliases
    if not banco:
        return tuple()
    return (str(banco),)


@st.cache_data(ttl=3600, show_spinner=False)
def _carregar_cache_relatorio(tipo_cache: str) -> Optional[pd.DataFrame]:
    manager = get_cache_manager()
    if manager is None:
        return None
    resultado = manager.carregar(tipo_cache)
    if resultado.sucesso and resultado.dados is not None:
        return _normalizar_nomes_carteira(resultado.dados)
    return None




def _slice_cache_for_peers(
    df: Optional[pd.DataFrame],
    bancos: Optional[list] = None,
    periodos: Optional[list] = None,
) -> Optional[pd.DataFrame]:
    """Compat shim para versões que ainda chamam este helper.

    Mantido para evitar NameError em deployments com código parcialmente atualizado.
    """
    if df is None or df.empty:
        return df
    if "Instituição" not in df.columns or "Período" not in df.columns:
        return df

    mask = pd.Series(True, index=df.index)
    if bancos:
        mask &= df["Instituição"].isin(bancos)
    if periodos:
        mask &= df["Período"].isin(periodos)
    return df.loc[mask].copy()

@st.cache_data(ttl=3600, show_spinner=False)
def _carregar_cache_relatorio_slice(
    tipo_cache: str,
    cache_token: str,
    periodos: tuple = (),
    instituicoes: tuple = (),
) -> Optional[pd.DataFrame]:
    """Carrega recorte de cache por período/instituição para reduzir I/O e RAM."""
    def _periodos_to_yyyymm(periodos_src: tuple) -> tuple[str, ...]:
        out = []
        for p in (periodos_src or ()):
            if not isinstance(p, str) or "/" not in p:
                continue
            mm, yyyy = p.split("/", 1)
            mm = mm.strip().zfill(2)
            yyyy = yyyy.strip()
            if len(yyyy) == 4 and mm.isdigit():
                out.append(f"{yyyy}{mm}")
        return tuple(sorted(set(out)))

    def _periodos_to_data_base_candidates(periodos_src: tuple) -> tuple:
        vals = set()
        for ym in _periodos_to_yyyymm(periodos_src):
            vals.add(ym)
            vals.add(int(ym))
            ano = ym[:4]
            mes = ym[4:6]
            vals.add(f"{ano}-{mes}")
            for dia in range(1, 32):
                dd = f"{dia:02d}"
                vals.add(f"{ym}{dd}")
                vals.add(int(f"{ym}{dd}"))
                vals.add(f"{ano}-{mes}-{dd}")
        return tuple(sorted(vals, key=lambda x: str(x)))

    manager = get_cache_manager()
    if manager is None:
        return None

    cache = manager.get_cache(tipo_cache)
    if cache is None:
        return None

    periodos = tuple(periodos or ())
    instituicoes = tuple(instituicoes or ())
    instituicoes_expandidas = (
        _expandir_instituicoes_canonicas(instituicoes)
        if instituicoes and tipo_cache != "bloprudencial"
        else instituicoes
    )

    if tipo_cache == "critical_screens":
        return load_critical_screens_slice(
            base_dir=APP_DIR,
            periodos=list(periodos) if periodos else None,
            instituicoes=list(instituicoes_expandidas or instituicoes) if (instituicoes_expandidas or instituicoes) else None,
        )

    # Caminho rápido: parquet com filtro no reader
    if cache.arquivo_dados.exists():
        try:
            import pyarrow.dataset as ds
            dataset = ds.dataset(cache.arquivo_dados)
            schema_names = {str(n) for n in dataset.schema.names}
            filtro = None
            if periodos:
                if "Período" in schema_names:
                    f = ds.field("Período").isin(list(periodos))
                    filtro = f if filtro is None else filtro & f
                elif tipo_cache == "bloprudencial":
                    yyyymm_needed = _periodos_to_data_base_candidates(tuple(periodos))
                    if yyyymm_needed and "DATA_BASE" in schema_names:
                        # DATA_BASE pode vir como YYYYMM, YYYYMMDD, int ou data string.
                        f = ds.field("DATA_BASE").isin(list(yyyymm_needed))
                        filtro = f if filtro is None else filtro & f
            if instituicoes_expandidas and "Instituição" in schema_names and tipo_cache != "bloprudencial":
                f = ds.field("Instituição").isin(list(instituicoes_expandidas))
                filtro = f if filtro is None else filtro & f
            if tipo_cache == "bloprudencial":
                cols_blop = [
                    c for c in [
                        "DATA_BASE", "Período", "DOCUMENTO", "CONTA", "SALDO",
                        "NOME_INSTITUICAO", "NOME_CONGL", "COD_CONGL",
                        "Instituição", "Instituicao", "Documento", "Conta", "Saldo",
                        "Nome_Congl", "Cod_Congl",
                    ] if c in schema_names
                ]
                tabela = dataset.to_table(columns=cols_blop or None, filter=filtro) if filtro is not None else dataset.to_table(columns=cols_blop or None)
            else:
                tabela = dataset.to_table(filter=filtro) if filtro is not None else dataset.to_table()
            return _normalizar_nomes_carteira(tabela.to_pandas())
        except Exception:
            pass

    # Fallback: carregar e filtrar em pandas
    resultado = manager.carregar(tipo_cache)
    if not resultado.sucesso or resultado.dados is None:
        return None

    df = _normalizar_nomes_carteira(resultado.dados)
    if periodos:
        if "Período" in df.columns:
            df = df[df["Período"].isin(periodos)]
        elif tipo_cache == "bloprudencial":
            col_data_base = next((c for c in ["DATA_BASE", "Data_Base", "data_base"] if c in df.columns), None)
            if col_data_base:
                periodos_yyyymm = {
                    str(p).split("/")[1] + str(p).split("/")[0].zfill(2)
                    for p in periodos
                    if isinstance(p, str) and "/" in p
                }
                if periodos_yyyymm:
                    base_txt = df[col_data_base].astype(str).str.replace(r"\D", "", regex=True).str[:6]
                    df = df[base_txt.isin(periodos_yyyymm)]
    if instituicoes_expandidas and "Instituição" in df.columns and tipo_cache != "bloprudencial":
        mask = df["Instituição"].isin(instituicoes_expandidas)
        if not mask.any():
            inst_norm = df["Instituição"].apply(normalizar_nome_instituicao)
            filtros_norm = {normalizar_nome_instituicao(i) for i in instituicoes_expandidas}
            filtros_norm.discard("")
            if filtros_norm:
                mask = inst_norm.isin(filtros_norm)
        df = df[mask]
    return df


def _critical_metric_lookup(df: Optional[pd.DataFrame]) -> dict:
    if df is None or df.empty:
        return {}
    required = {"Instituição", "Período"}
    if not required.issubset(df.columns):
        return {}
    base = (
        df.dropna(subset=["Instituição", "Período"])
        .drop_duplicates(subset=["Instituição", "Período"], keep="last")
        .set_index(["Instituição", "Período"])
    )
    return base.to_dict("index")


def _critical_metric_value(metric_lookup: dict, instituicao: str, periodo: str, coluna: str):
    if not metric_lookup or not coluna:
        return None
    row = metric_lookup.get((instituicao, periodo))
    if row is None:
        return None
    return row.get(coluna)


def _critical_metric_map(df: Optional[pd.DataFrame], instituicao: str, periodos: list[str], coluna: str) -> dict[str, Optional[float]]:
    lookup = _critical_metric_lookup(df)
    return {
        periodo: _coerce_numeric_value(_critical_metric_value(lookup, instituicao, periodo, coluna))
        for periodo in periodos
    }


def _garantir_cache_telas_criticas(menu_nome: str) -> bool:
    manager = get_cache_manager()
    status = get_critical_screens_runtime_status(manager=manager)
    cache = status.get("cache")

    if cache is not None and status.get("mode") == "bootstrap_bundle":
        bootstrap_result = cache.bootstrap_local_from_bundle()
        if bootstrap_result.sucesso:
            return True
        st.error(f"critical_screens: {bootstrap_result.mensagem}")
        st.caption("o app não continuará para rematerialização remota automática no boot.")
        return False

    if status.get("local_ready"):
        return True

    if status.get("mode") == "materialize_local":
        st.error("critical_screens indisponível para runtime.")
        st.caption(
            status.get("message")
            or "artefato curado ausente/inválido; a aba não iniciará rematerialização pesada durante a navegação."
        )
        st.caption(
            "a rematerialização automática do cache curado foi desabilitada no runtime para evitar travamentos. "
            "gere/publice o bundle curado ou prepare as fontes localmente via Atualizar Base."
        )
        return False

    if not status.get("can_materialize_from_local_sources"):
        faltantes = status.get("missing_local_source_caches") or []
        st.error("critical_screens indisponível para runtime.")
        st.caption(status.get("message") or "artefato curado ausente e fontes locais incompletas.")
        if faltantes:
            st.caption(f"fontes locais ausentes: {', '.join(faltantes)}")
        st.caption("gere/publice o bundle curado ou prepare as fontes localmente via Atualizar Base.")
        return False

    st.error("critical_screens indisponível para runtime.")
    st.caption(status.get("message") or "artefato curado ausente ou inválido.")
    return False


@st.cache_data(ttl=900, show_spinner=False)
def _carregar_metadata_critical_screens(cache_token: str) -> dict:
    _ = cache_token
    manager = get_cache_manager()
    cache = manager.get_cache("critical_screens") if manager else None
    if cache is None:
        return {}
    caminho = cache.arquivo_metadata
    if not caminho.exists():
        bootstrap = cache.bootstrap_local_from_bundle()
        if not bootstrap.sucesso:
            return {}
    try:
        return json.loads(caminho.read_text(encoding="utf-8"))
    except Exception:
        return {}


def _expandir_instituicoes_canonicas(instituicoes: tuple[str, ...]) -> tuple[str, ...]:
    if not instituicoes:
        return ()
    metadata = _carregar_metadata_critical_screens(_cache_version_token("critical_screens"))
    extra = metadata.get("extra") or {}
    canonical_variants = extra.get("canonical_variants") or {}
    raw_to_canonical = extra.get("raw_to_canonical") or {}

    expandidas = []
    vistos = set()
    for nome in instituicoes:
        nome_txt = str(nome).strip()
        if not nome_txt:
            continue
        canonico = raw_to_canonical.get(nome_txt, nome_txt)
        for candidato in [canonico, *canonical_variants.get(canonico, [])]:
            candidato_txt = str(candidato).strip()
            if not candidato_txt or candidato_txt in vistos:
                continue
            vistos.add(candidato_txt)
            expandidas.append(candidato_txt)
    return tuple(expandidas)




def _get_slice_cache_for_peers_fn():
    """Retorna função de recorte para peers com fallback defensivo."""
    fn = globals().get("_slice_cache_for_peers")
    if callable(fn):
        return fn

    def _fallback(df: Optional[pd.DataFrame], bancos: Optional[list] = None, periodos: Optional[list] = None):
        if df is None or df.empty:
            return df
        if "Instituição" not in df.columns or "Período" not in df.columns:
            return df
        mask = pd.Series(True, index=df.index)
        if bancos:
            mask &= df["Instituição"].isin(bancos)
        if periodos:
            mask &= df["Período"].isin(periodos)
        return df.loc[mask].copy()

    return _fallback


@st.cache_data(ttl=3600, show_spinner=False)
def _carregar_bloprudencial_fallback_periodos(yyyymm_needed: tuple) -> pd.DataFrame:
    """Carrega base prudencial por competências (fallback) com cache para reuso entre reruns."""
    if not yyyymm_needed:
        return pd.DataFrame()
    try:
        from utils.ifdata_cache import load_bloprudencial_df_cached
    except Exception:
        return pd.DataFrame()

    dfs_blop = []
    for ym in yyyymm_needed:
        ym_txt = str(ym)
        if len(ym_txt) != 6:
            continue
        try:
            df_ym = load_bloprudencial_df_cached(
                yyyymm=ym_txt,
                cache_dir="data/cache/bcb_bloprudencial",
                force_refresh=False,
            )
        except Exception:
            continue
        if df_ym is None or df_ym.empty:
            continue
        tmp = df_ym.copy()
        if "DATA_BASE" not in tmp.columns:
            tmp["DATA_BASE"] = ym_txt
        if "Período" not in tmp.columns:
            tmp["Período"] = f"{ym_txt[4:6]}/{ym_txt[:4]}"
        dfs_blop.append(tmp)

    if not dfs_blop:
        return pd.DataFrame()
    return pd.concat(dfs_blop, ignore_index=True)


def _preparar_metricas_extra_peers(
    bancos: list,
    periodos: list,
    cache_ativo: Optional[pd.DataFrame],
    cache_passivo: Optional[pd.DataFrame],
    cache_carteira_pf: Optional[pd.DataFrame],
    cache_carteira_pj: Optional[pd.DataFrame],
    cache_carteira_instr: Optional[pd.DataFrame],
    cache_dre: Optional[pd.DataFrame],
    cache_capital: Optional[pd.DataFrame] = None,
    cache_bloprudencial: Optional[pd.DataFrame] = None,
) -> dict:
    # TODO(V3): eliminar duplicidade estrutural de métricas canônicas vs "*"
    # (ex.: Core Funding/Core Funding* e Carteira de Crédito Bruta/Carteira de Crédito*)
    # mantendo apenas uma chave de dado e aliases apenas de apresentação.
    extra = {
        "Carteira de Crédito Bruta": {},
        "Carteira de Crédito*": {},
        "Carteira de Crédito Classificada": {},
        "Ativos Líquidos": {},
        "Depósitos Totais": {},
        "Core Funding": {},
        "Core Funding*": {},
        "Perda Esperada": {},
        "Perda Esperada / Carteira de Crédito Bruta": {},
        "Perda Esperada / Carteira de Crédito*": {},
        "Carteira de Créd. Class. C4+C5": {},
        "Carteira de Créd. Class. C4+C5 / Carteira Classificada": {},
        "Perda Esperada / (Carteira C4 + C5)": {},
        "Saldo PDD Crédito": {},
        "Saldo PDD Outros Créditos": {},
        "PDD Total 4060": {},
        "Carteira Estágio 1": {},
        "Ativos Estágio 2": {},
        "Ativos Estágio 3": {},
        "PDD / Estágio 3": {},
        "Perda Esperada / Estágio 3": {},
        "Perda Esperada / Est2+3": {},
        "Índice de Capital Principal (CET1)": {},
        "Índice de Basileia Total (%)": {},
    }
    periodos_base = {_periodo_ano_anterior(periodo) for periodo in periodos}
    periodos_ext = [p for p in periodos + sorted(periodos_base) if p]

    def _resolver_coluna_base(df_src: Optional[pd.DataFrame], candidatos: list[str]) -> Optional[str]:
        if df_src is None or df_src.empty:
            return None
        cols = list(df_src.columns)
        lower_map = {str(c).strip().lower(): c for c in cols}
        for cand in candidatos:
            key = str(cand).strip().lower()
            if key in lower_map:
                return lower_map[key]
        return None

    bancos_set = {str(b) for b in bancos if b is not None and str(b).strip() != ""}
    periodos_set = {str(p) for p in periodos_ext if p is not None and str(p).strip() != ""}

    def _build_metric_pivot(df_src: Optional[pd.DataFrame], metric_cols: list[str]) -> dict:
        if df_src is None or df_src.empty:
            return {}
        metric_cols = [c for c in metric_cols if c and c in df_src.columns]
        if not metric_cols:
            return {}
        col_inst = _resolver_coluna_base(df_src, ["Instituição", "instituicao", "banco"])
        col_per = _resolver_coluna_base(df_src, ["Período", "periodo", "competencia", "data"])
        if not col_inst or not col_per:
            return {}

        # PERF: limita base ao recorte de bancos/períodos selecionados antes do groupby.
        df_work = df_src[[col_inst, col_per] + metric_cols].copy()
        if periodos_set:
            per_mask = df_work[col_per].astype(str).isin(periodos_set)
            if per_mask.any():
                df_work = df_work.loc[per_mask]
        if bancos_set:
            inst_mask = df_work[col_inst].astype(str).isin(bancos_set)
            if not inst_mask.any():
                inst_norm_series = df_work[col_inst].map(normalizar_nome_instituicao)
                bancos_norm = {normalizar_nome_instituicao(b) for b in bancos_set}
                bancos_norm.discard("")
                if bancos_norm:
                    inst_mask = inst_norm_series.isin(bancos_norm)
            if inst_mask.any():
                df_work = df_work.loc[inst_mask]

        # PERF: pre-materialized pivot replaces O(N) per-call DataFrame scans
        grouped = (
            df_work
            .assign(**{col_per: lambda d: d[col_per].astype(str)})
            .groupby([col_inst, col_per], dropna=False, sort=False)[metric_cols]
            .first()
            .reset_index()
        )
        pivot = {}
        for row in grouped.itertuples(index=False, name=None):
            inst = row[0]
            per = str(row[1])
            for idx, metric_col in enumerate(metric_cols, start=2):
                pivot[(inst, per, metric_col)] = row[idx]
        return pivot

    def _lk_get(pivot_src: dict, banco: str, periodo: str, coluna: Optional[str]):
        if coluna is None or not pivot_src:
            return None
        return pivot_src.get((banco, str(periodo), coluna))

    def _periodo_to_yyyymm(periodo: str) -> Optional[str]:
        parsed = _parse_periodo(periodo)
        if not parsed:
            return None
        parte, ano, _ = parsed
        tri_idx = _parte_periodo_para_trimestre_idx(parte)
        if tri_idx is None:
            return None
        mes_map = {1: "03", 2: "06", 3: "09", 4: "12"}
        mes = mes_map.get(tri_idx)
        if mes is None:
            return None
        return f"{ano:04d}{mes}"

    def _bloprud_norm_name(valor: str) -> str:
        if valor is None:
            return ""
        txt = str(valor).strip().upper()
        txt = txt.replace("Á", "A").replace("À", "A").replace("Ã", "A").replace("Â", "A")
        txt = txt.replace("É", "E").replace("Ê", "E")
        txt = txt.replace("Í", "I")
        txt = txt.replace("Ó", "O").replace("Õ", "O").replace("Ô", "O")
        txt = txt.replace("Ú", "U").replace("Ç", "C")
        txt = " ".join(txt.split())
        return txt

    def _bloprud_strip_suffixes(valor_norm: str) -> str:
        txt = str(valor_norm or "").strip()
        if not txt:
            return ""
        suffixes = [" - PRUDENCIAL", " PRUDENCIAL", " HOLDING", " S.A.", " S A", " SA"]
        changed = True
        while changed and txt:
            changed = False
            for suffix in suffixes:
                if txt.endswith(suffix):
                    txt = txt[: -len(suffix)].strip()
                    changed = True
                    break
        return " ".join(txt.split())

    def _bloprud_name_variants(valor: str) -> set[str]:
        base = _bloprud_norm_name(valor)
        if not base:
            return set()
        variants = {base}
        stripped = _bloprud_strip_suffixes(base)
        if stripped:
            variants.add(stripped)
        if " - " in base:
            left = base.split(" - ", 1)[0].strip()
            if left:
                variants.add(left)
        for v in list(variants):
            v2 = v.replace("BANCO", "BCO").replace("BCO", "BANCO")
            variants.add(" ".join(v2.split()))
        for v in list(variants):
            if v.startswith("BANCO "):
                variants.add(v[len("BANCO "):].strip())
            if v.startswith("BCO "):
                variants.add(v[len("BCO "):].strip())
        return {v for v in variants if v}

    def _bloprud_pick_col(df_src: Optional[pd.DataFrame], candidates: list[str]) -> Optional[str]:
        if df_src is None or df_src.empty:
            return None
        cols = list(df_src.columns)
        if not cols:
            return None
        lower_map = {str(c).strip().lower(): c for c in cols}
        for cand in candidates:
            key = str(cand).strip().lower()
            if key in lower_map:
                return lower_map[key]
        for cand in candidates:
            key = str(cand).strip().lower()
            for col in cols:
                col_l = str(col).strip().lower()
                if key in col_l or col_l in key:
                    return col
        return None

    # Fallback: quando o cache manager "bloprudencial" estiver vazio/ausente,
    # carregar competências necessárias direto do loader mensal em disco/rede.
    if cache_bloprudencial is None or cache_bloprudencial.empty:
        yyyymm_needed = tuple(sorted({
            ym for ym in (_periodo_to_yyyymm(p) for p in periodos)
            if ym
        }))
        df_blop_fallback = _carregar_bloprudencial_fallback_periodos(yyyymm_needed)
        if df_blop_fallback is not None and not df_blop_fallback.empty:
            cache_bloprudencial = df_blop_fallback

    col_blop_nome_inst = _bloprud_pick_col(cache_bloprudencial, ["NOME_INSTITUICAO", "Instituição", "Instituicao"])
    col_blop_nome_congl = _bloprud_pick_col(cache_bloprudencial, ["NOME_CONGL", "Nome_Congl", "nome_congl"])
    col_blop_conta = _bloprud_pick_col(cache_bloprudencial, ["CONTA", "Conta", "codigo_conta", "COD_CONTA"])
    col_blop_saldo = _bloprud_pick_col(cache_bloprudencial, ["SALDO", "Saldo", "VALOR", "Valor"])
    col_blop_cod_congl = _bloprud_pick_col(cache_bloprudencial, ["COD_CONGL", "Cod_Congl", "codigo_congl", "cod_congl"])
    col_blop_documento = _bloprud_pick_col(cache_bloprudencial, ["DOCUMENTO", "Documento", "doc", "cadoc"])

    blop_lookup: dict[tuple[str, str, str], float] = {}
    blop_lookup_por_mes_conta: dict[tuple[str, str], dict[str, float]] = {}
    blop_lookup_cod: dict[tuple[str, str, str], float] = {}
    blop_nome_para_codigos: dict[str, set[str]] = {}
    blop_cod_para_inst_keys: dict[str, set[str]] = {}
    contas_blop_necessarias = {"1490000004", "1890000006", "3311000002", "3312000001", "3313000000"}
    yyyymm_blop_necessarios = {
        ym for ym in (_periodo_to_yyyymm(p) for p in periodos_ext)
        if ym and len(str(ym)) == 6
    }

    if (
        cache_bloprudencial is not None
        and not cache_bloprudencial.empty
        and (col_blop_nome_inst or col_blop_nome_congl)
        and col_blop_conta
        and col_blop_saldo
    ):
        df_blop = cache_bloprudencial.copy()

        # Em alguns casos o cache vem sem coluna Período e o slice por período retorna vazio.
        # Reidratar Período a partir de DATA_BASE (YYYYMM -> MM/YYYY) para compatibilizar filtros da aba Peers.
        if "Período" not in df_blop.columns:
            col_data_base = _bloprud_pick_col(df_blop, ["DATA_BASE", "Data_Base", "data_base"])
            if col_data_base:
                base_txt = df_blop[col_data_base].astype(str).str.replace(r"\D", "", regex=True).str[:6]
                df_blop["Período"] = base_txt.str[4:6] + "/" + base_txt.str[:4]
        if col_blop_documento:
            docs_num = pd.to_numeric(df_blop[col_blop_documento], errors="coerce")
            mask_4060 = docs_num == 4060
            # Jun/Dez podem vir com 4060 e 4066 no mesmo arquivo mensal; para contas
            # prudenciais usadas em Peers/Snapshot (PDD + estágios) manter apenas Cadoc 4060
            # evita duplicação exata (~2x) ao agregar por instituição/conta.
            if mask_4060.any():
                df_blop = df_blop.loc[mask_4060].copy()
        if col_blop_nome_inst:
            df_blop["_inst_norm"] = df_blop[col_blop_nome_inst].map(_bloprud_norm_name)
        else:
            df_blop["_inst_norm"] = ""
        if col_blop_nome_congl:
            df_blop["_congl_norm"] = df_blop[col_blop_nome_congl].map(_bloprud_norm_name)
        else:
            df_blop["_congl_norm"] = ""
        if col_blop_cod_congl:
            df_blop["_cod_congl"] = (
                df_blop[col_blop_cod_congl]
                .astype(str)
                .str.strip()
                .str.upper()
                .str.replace(r"\s+", "", regex=True)
            )
        else:
            df_blop["_cod_congl"] = ""
        col_data_base = _bloprud_pick_col(df_blop, ["DATA_BASE", "Data_Base", "data_base"])
        if col_data_base:
            df_blop["_yyyymm"] = df_blop[col_data_base].astype(str).str.replace(r"\D", "", regex=True).str[:6]
            if yyyymm_blop_necessarios:
                mask_ym = df_blop["_yyyymm"].isin(yyyymm_blop_necessarios)
                if mask_ym.any():
                    df_blop = df_blop.loc[mask_ym].copy()
        else:
            df_blop["_yyyymm"] = None

        # Mapa de nomes->código usa o conjunto de períodos (não restringir por conta),
        # para preservar cobertura de bancos menores sem reabrir varredura global.
        df_blop_map = df_blop[["_inst_norm", "_congl_norm", "_cod_congl"]].copy()

        if col_blop_conta:
            contas_num = df_blop[col_blop_conta].astype(str).str.replace(r"\D", "", regex=True)
            mask_contas = contas_num.isin(contas_blop_necessarias)
            if mask_contas.any():
                df_blop = df_blop.loc[mask_contas].copy()
                contas_num = contas_num.loc[df_blop.index]
            df_blop["_conta"] = contas_num
        else:
            df_blop["_conta"] = ""

        df_blop["_saldo"] = pd.to_numeric(df_blop[col_blop_saldo], errors="coerce")

        # Pre-compute name variants cache to avoid redundant calls inside loops
        _variants_cache: dict[str, set[str]] = {}
        def _cached_variants(name: str) -> set[str]:
            v = _variants_cache.get(name)
            if v is None:
                v = _bloprud_name_variants(name)
                _variants_cache[name] = v
            return v

        # Pre-warm variants cache with unique names from all 3 columns
        for _col_name in ("_inst_norm", "_congl_norm"):
            if _col_name in df_blop.columns:
                for _uname in df_blop[_col_name].dropna().unique():
                    _uname_s = str(_uname).strip()
                    if _uname_s and _uname_s != "None":
                        _cached_variants(_uname_s)

        ag_inst = (
            df_blop.groupby(["_yyyymm", "_inst_norm", "_conta"], dropna=False)["_saldo"]
            .sum(min_count=1)
            .reset_index()
        )
        for row in ag_inst.itertuples(index=False):
            yyyymm = str(row[0])
            inst_norm = str(row[1])
            conta = str(row[2])
            val = row[3]
            if not yyyymm or yyyymm == "None" or len(yyyymm) != 6:
                continue
            if inst_norm and inst_norm != "None" and pd.notna(val):
                val_f = float(val)
                for inst_variant in _cached_variants(inst_norm):
                    blop_lookup[(yyyymm, inst_variant, conta)] = val_f
                    blop_lookup_por_mes_conta.setdefault((yyyymm, conta), {}).setdefault(inst_variant, val_f)

        ag_congl = (
            df_blop.groupby(["_yyyymm", "_congl_norm", "_conta"], dropna=False)["_saldo"]
            .sum(min_count=1)
            .reset_index()
        )
        for row in ag_congl.itertuples(index=False):
            yyyymm = str(row[0])
            congl_norm = str(row[1])
            conta = str(row[2])
            val = row[3]
            if not yyyymm or yyyymm == "None" or len(yyyymm) != 6:
                continue
            if congl_norm and congl_norm != "None" and pd.notna(val):
                val_f = float(val)
                for congl_variant in _cached_variants(congl_norm):
                    blop_lookup[(yyyymm, congl_variant, conta)] = val_f
                    blop_lookup_por_mes_conta.setdefault((yyyymm, conta), {}).setdefault(congl_variant, val_f)

        if col_blop_cod_congl:
            ag_cod = (
                df_blop.groupby(["_yyyymm", "_cod_congl", "_conta"], dropna=False)["_saldo"]
                .sum(min_count=1)
                .reset_index()
            )
            for row in ag_cod.itertuples(index=False):
                yyyymm = str(row[0])
                cod_congl = str(row[1]).strip().upper()
                conta = str(row[2])
                val = row[3]
                if not yyyymm or yyyymm == "None" or len(yyyymm) != 6:
                    continue
                if cod_congl and cod_congl != "None" and pd.notna(val):
                    blop_lookup_cod[(yyyymm, cod_congl, conta)] = float(val)

            for row in df_blop_map.itertuples(index=False):
                cod = str(row[2]).strip().upper()
                if not cod or cod == "None":
                    continue
                inst_norm = str(row[0]).strip()
                if inst_norm and inst_norm != "None":
                    for inst_variant in _cached_variants(inst_norm):
                        blop_cod_para_inst_keys.setdefault(cod, set()).add(inst_variant)
                for nome in (row[0], row[1]):
                    nome_norm = str(nome).strip()
                    if not nome_norm:
                        continue
                    for nome_variant in _cached_variants(nome_norm):
                        blop_nome_para_codigos.setdefault(nome_variant, set()).add(cod)

    _blop_query_cache: dict[tuple[str, str, str], Optional[float]] = {}
    _blop_banco_variants_cache: dict[str, set[str]] = {}
    _blop_banco_codigos_cache: dict[str, set[str]] = {}

    def _blop_get_sum_periodo_conta(banco: str, periodo: str, conta: str) -> Optional[float]:
        query_key = (str(banco), str(periodo), str(conta))
        if query_key in _blop_query_cache:
            return _blop_query_cache[query_key]
        if not blop_lookup and not blop_lookup_cod:
            _blop_query_cache[query_key] = None
            return None
        yyyymm = _periodo_to_yyyymm(periodo)
        if not yyyymm:
            _blop_query_cache[query_key] = None
            return None
        banco_variants = _blop_banco_variants_cache.get(str(banco))
        if banco_variants is None:
            banco_variants = _bloprud_name_variants(banco)
            _blop_banco_variants_cache[str(banco)] = banco_variants
        diag_alvo = (yyyymm == "202509" and str(conta) == "3313000000")

        # Prioridade: lookup por código estável do conglomerado prudencial.
        codigos = _blop_banco_codigos_cache.get(str(banco))
        if codigos is None:
            codigos = set()
            for variant in banco_variants:
                codigos.update(blop_nome_para_codigos.get(variant, set()))
            _blop_banco_codigos_cache[str(banco)] = codigos
        for cod in codigos:
            val_cod = blop_lookup_cod.get((yyyymm, cod, conta))
            if val_cod is not None and not pd.isna(val_cod):
                if diag_alvo:
                    inst_keys = sorted(blop_cod_para_inst_keys.get(cod, set()))
                    print(
                        "[DIAG][PE_EST3][BLOP_MATCH]",
                        {
                            "banco": banco,
                            "periodo": periodo,
                            "yyyymm": yyyymm,
                            "conta": conta,
                            "caminho": "COD_CONGL",
                            "cod_congl": cod,
                            "inst_key": inst_keys[0] if inst_keys else "",
                            "inst_keys_count": len(inst_keys),
                            "saldo_bruto": float(val_cod),
                        },
                    )
                _blop_query_cache[query_key] = float(val_cod)
                return float(val_cod)

        for variant in banco_variants:
            val = blop_lookup.get((yyyymm, variant, conta))
            if val is not None and not pd.isna(val):
                if diag_alvo:
                    cods_variant = sorted(blop_nome_para_codigos.get(variant, set()))
                    print(
                        "[DIAG][PE_EST3][BLOP_MATCH]",
                        {
                            "banco": banco,
                            "periodo": periodo,
                            "yyyymm": yyyymm,
                            "conta": conta,
                            "caminho": "NOME_EXATO",
                            "cod_congl": cods_variant[0] if cods_variant else "",
                            "inst_key": variant,
                            "inst_keys_count": 1,
                            "saldo_bruto": float(val),
                        },
                    )
                _blop_query_cache[query_key] = float(val)
                return float(val)

        # fallback: compatibilizar por inclusão textual entre variantes e chaves do lookup
        # já indexadas por (yyyymm, conta) para evitar varredura global.
        val_fallback = None
        inst_map = blop_lookup_por_mes_conta.get((yyyymm, str(conta)), {})
        for inst_key, saldo in inst_map.items():
            if any(
                v and (
                    v == inst_key
                    or (len(v) >= 4 and f" {v} " in f" {inst_key} ")
                    or (len(inst_key) >= 4 and f" {inst_key} " in f" {v} ")
                )
                for v in banco_variants
            ):
                if saldo is None or pd.isna(saldo):
                    continue
                val_fallback = float(saldo)
                if diag_alvo:
                    cods_inst = sorted(blop_nome_para_codigos.get(inst_key, set()))
                    print(
                        "[DIAG][PE_EST3][BLOP_MATCH]",
                        {
                            "banco": banco,
                            "periodo": periodo,
                            "yyyymm": yyyymm,
                            "conta": conta,
                            "caminho": "FALLBACK_TEXTUAL",
                            "cod_congl": cods_inst[0] if cods_inst else "",
                            "inst_key": inst_key,
                            "inst_keys_count": 1,
                            "saldo_bruto": float(saldo),
                        },
                    )
                break

        val = val_fallback
        out = None if val is None or pd.isna(val) else float(val)
        if out is None and banco_variants:
            print(
                f"[BLOP_MISS] banco={banco}, periodo={periodo}, conta={conta}, "
                f"variants={sorted(banco_variants)[:5]}, codigos={sorted(codigos)[:3]}, "
                f"lookup_keys_sample={len(blop_lookup)}, cod_keys_sample={len(blop_lookup_cod)}"
            )
        _blop_query_cache[query_key] = out
        return out

    col_pf_total = _resolver_coluna_peers(
        cache_carteira_pf,
        [
            "Total da Carteira de Pessoa Física",
            "Total da Carteira Pessoa Física",
            "Total da Carteira PF",
            "Total da Carteira de Pessoa Fisica",
        ],
    )
    col_pj_total = _resolver_coluna_peers(
        cache_carteira_pj,
        [
            "Total da Carteira de Pessoa Jurídica",
            "Total da Carteira Pessoa Jurídica",
            "Total da Carteira PJ",
            "Total da Carteira de Pessoa Juridica",
        ],
    )

    # Ativos Líquidos: Disponibilidades (a) + Aplicações Interfinanceiras de Liquidez (b)
    # + TVM (c) do relatório de Ativo (Rel. 2)
    col_disp_ativo = _resolver_coluna_peers(
        cache_ativo,
        ["Disponibilidades (a)", "Disponibilidades", "Disponibilidades (a) ="],
    )
    col_aplic_ativo = _resolver_coluna_peers(
        cache_ativo,
        [
            "Aplicações Interfinanceiras de Liquidez (b)",
            "Aplicacoes Interfinanceiras de Liquidez (b)",
            "Aplicações Interfinanceiras de Liquidez",
        ],
    )
    col_tvm_ativo = _resolver_coluna_peers(
        cache_ativo,
        [
            "Títulos e Valores Mobiliários (c)",
            "Titulos e Valores Mobiliarios (c)",
            "Títulos e Valores Mobiliários e Instrumentos Financeiros Derivativos (c)",
            "Títulos e Valores Mobiliários",
        ],
    )

    # Depósitos Totais: prioriza a linha agregada oficial disponível por linha
    # e só cai para soma a1..a6 quando nenhum agregado oficial estiver preenchido.
    cols_depositos_passivo = _resolver_colunas_peers(
        cache_passivo,
        [
            "Depósitos (e)",
            "Depositos (e)",
            "Depósitos (a)",
            "Depósitos Totais (a)",
            "Depósito Total (a)",
            "Depositos (a)",
            "Deposito Total (a)",
            "Depósitos",
            "Depositos",
        ],
    )
    col_dep_a1 = _resolver_coluna_peers(
        cache_passivo,
        ["Depósitos à Vista (a1)", "Depositos a Vista (a1)", "Depósitos à Vista", "Depositos a Vista"],
    )
    col_dep_a2 = _resolver_coluna_peers(
        cache_passivo,
        ["Depósitos de Poupança (a2)", "Depositos de Poupanca (a2)", "Depósitos de Poupança"],
    )
    col_dep_a3 = _resolver_coluna_peers(
        cache_passivo,
        ["Depósitos Interfinanceiros (a3)", "Depositos Interfinanceiros (a3)"],
    )
    col_dep_a4 = _resolver_coluna_peers(
        cache_passivo,
        ["Depósitos a Prazo (a4)", "Depositos a Prazo (a4)"],
    )
    col_dep_a5 = _resolver_coluna_peers(
        cache_passivo,
        [
            "Outros Depósitos (a5)",
            "Outros Depositos (a5)",
            "Conta de Pagamento Pré-Paga (a5)",
            "Conta de Pagamento Pre-Paga (a5)",
            "Conta de Pagamento Pre Paga (a5)",
        ],
    )
    col_dep_a6 = _resolver_coluna_peers(
        cache_passivo,
        ["Depósitos Outros (a6)", "Depositos Outros (a6)"],
    )

    # Core Funding: Captações (e); 2025+ inclui Instrumentos de Dívida Elegíveis a Capital (h)
    col_capt_passivo = _resolver_coluna_peers(
        cache_passivo,
        [
            "Captações (e) = (a) + (b) + (c) + (d)",
            "Captações (e)",
            "Captações",
            "Captacoes (e)",
        ],
    )
    col_instr_passivo = _resolver_coluna_peers(
        cache_passivo,
        [
            "Instrumentos de Dívida Elegíveis a Capital (h)",
            "Instrumentos de Divida Elegiveis a Capital (h)",
            "Instrumentos de Dívida Elegíveis a Capital",
            "Instrumentos de Divida Elegiveis a Capital",
        ],
    )

    # Carteira de Crédito Bruta: Valor Contábil Bruto (e1 + f1 + g1 + h1) do relatório de Ativo (Rel. 2)
    col_credito_bruta_e1 = _resolver_coluna_peers(
        cache_ativo,
        ["Valor Contábil Bruto (e1)", "Valor Contabil Bruto (e1)"],
    )
    col_credito_bruta_f1 = _resolver_coluna_peers(
        cache_ativo,
        ["Valor Contábil Bruto (f1)", "Valor Contabil Bruto (f1)"],
    )
    col_credito_bruta_g1 = _resolver_coluna_peers(
        cache_ativo,
        ["Valor Contábil Bruto (g1)", "Valor Contabil Bruto (g1)"],
    )
    col_credito_bruta_h1 = _resolver_coluna_peers(
        cache_ativo,
        ["Valor Contábil Bruto (h1)", "Valor Contabil Bruto (h1)"],
    )
    col_credito_bruta_d1 = _resolver_coluna_peers(
        cache_ativo,
        ["Operações de Crédito (d1)", "Operacoes de Credito (d1)"],
    )
    col_credito_bruta_e1_alt = _resolver_coluna_peers(
        cache_ativo,
        ["Arrendamento Mercantil a Receber (e1)", "Arrendamento Mercantil a Receber"],
    )
    col_credito_bruta_f = _resolver_coluna_peers(
        cache_ativo,
        ["Outros Créditos - Líquido de Provisão (f)", "Outros Creditos - Liquido de Provisao (f)", "Outros Créditos - Líquido de Provisão"],
    )
    col_credito_net_e = _resolver_coluna_peers(
        cache_ativo,
        ["Operações de Crédito (e)", "Operacoes de Credito (e)"],
    )
    col_credito_net_f = _resolver_coluna_peers(
        cache_ativo,
        ["Operações de Arrendamento Financeiro (f)", "Operacoes de Arrendamento Financeiro (f)"],
    )
    col_credito_net_g = _resolver_coluna_peers(
        cache_ativo,
        ["Outras Operações com Características de Concessão de Crédito (g)", "Outras Operacoes com Caracteristicas de Concessao de Credito (g)"],
    )
    col_credito_net_h = _resolver_coluna_peers(
        cache_ativo,
        ["Valores a Receber de Transações de Pagamentos - Usuários Finais (Pós-pago) (h)",
         "Valores a Receber de Transacoes de Pagamentos - Usuarios Finais (Pos-pago) (h)"],
    )

    perda_colunas_base = [
        "Perda Esperada (e2)",
        "Hedge de Valor Justo (e3)",
        "Ajuste a Valor Justo (e4)",
        "Perda Esperada (f2)",
        "Hedge de Valor Justo (f3)",
        "Perda Esperada (g2)",
        "Hedge de Valor Justo (g3)",
        "Ajuste a Valor Justo (g4)",
        "Perda Esperada (h2)",
    ]
    perda_colunas = []
    for coluna in perda_colunas_base:
        col_resolvida = _resolver_coluna_peers(cache_ativo, [coluna])
        if col_resolvida and col_resolvida not in perda_colunas:
            perda_colunas.append(col_resolvida)

    col_c4 = _resolver_coluna_peers(cache_carteira_instr, ["C4"])
    col_c5 = _resolver_coluna_peers(cache_carteira_instr, ["C5"])

    # Capital: colunas para Índice de Capital Principal e Índice de Basileia Total
    col_cap_principal = _resolver_coluna_peers(
        cache_capital,
        ["Capital Principal", "Capital Principal para Comparação com RWA (a)"],
    )
    col_cap_complementar = _resolver_coluna_peers(
        cache_capital,
        ["Capital Complementar", "Capital Complementar (b)"],
    )
    col_cap_nivel2 = _resolver_coluna_peers(
        cache_capital,
        ["Capital Nível II", "Capital Nível II (d)", "Capital Nivel II"],
    )
    col_rwa_total = _resolver_coluna_peers(
        cache_capital,
        [
            "RWA Total",
            "Ativos Ponderados pelo Risco (RWA) (j) = (f) + (g) + (h) + (i)",
            "Ativos Ponderados pelo Risco (RWA) (j)",
            "Ativos Ponderados pelo Risco (RWA) (i) = (f) + (g) + (h)",
            "Ativos Ponderados pelo Risco (RWA) (i)",
            "RWA",
        ],
    )
    col_indice_cap_principal = _resolver_coluna_peers(
        cache_capital,
        [
            "Índice de Capital Principal",
            "Índice de Capital Principal (l) = (a) / (j)",
            "Índice de Capital Principal (k) = (a) / (i)",
        ],
    )
    col_indice_basileia_precalc = _resolver_coluna_peers(
        cache_capital,
        [
            "Índice de Basileia",
            "Índice de Basileia Capital",
            "Índice de Basileia (n) = (e) / (j)",
            "Índice de Basileia (m) = (e) / (i)",
        ],
    )

    cols_ativo_pivot = [
        col_credito_bruta_e1, col_credito_bruta_f1, col_credito_bruta_g1, col_credito_bruta_h1,
        col_credito_bruta_d1, col_credito_bruta_e1_alt, col_credito_bruta_f,
        col_credito_net_e, col_credito_net_f, col_credito_net_g, col_credito_net_h,
        col_disp_ativo, col_aplic_ativo, col_tvm_ativo,
    ] + perda_colunas
    cols_passivo_pivot = [
        *cols_depositos_passivo, col_dep_a1, col_dep_a2, col_dep_a3, col_dep_a4, col_dep_a5, col_dep_a6,
        col_capt_passivo, col_instr_passivo,
    ]
    cols_capital_pivot = [
        col_cap_principal, col_cap_complementar, col_cap_nivel2, col_rwa_total,
        col_indice_cap_principal, col_indice_basileia_precalc,
    ]
    cols_pf_pivot = [col_pf_total]
    cols_pj_pivot = [col_pj_total]
    cols_instr_pivot = [col_c4, col_c5]

    lk_ativo = _build_metric_pivot(cache_ativo, cols_ativo_pivot)
    lk_passivo = _build_metric_pivot(cache_passivo, cols_passivo_pivot)
    lk_capital = _build_metric_pivot(cache_capital, cols_capital_pivot)
    lk_pf = _build_metric_pivot(cache_carteira_pf, cols_pf_pivot)
    lk_pj = _build_metric_pivot(cache_carteira_pj, cols_pj_pivot)
    lk_instr = _build_metric_pivot(cache_carteira_instr, cols_instr_pivot)

    for banco in bancos:
        for periodo in periodos_ext:
            chave = (banco, periodo)
            valor_pf = _lk_get(lk_pf, banco, periodo, col_pf_total)
            valor_pj = _lk_get(lk_pj, banco, periodo, col_pj_total)
            carteira_classificada = _somar_valores([valor_pf, valor_pj])
            extra["Carteira de Crédito Classificada"][chave] = carteira_classificada

            ano_ref = _periodo_ano_int(periodo)
            carteira_bruta = resolve_carteira_credito_bruta_value(
                year_ref=ano_ref,
                legacy_credito_value=_lk_get(lk_ativo, banco, periodo, col_credito_bruta_d1),
                legacy_arrendamento_value=_lk_get(lk_ativo, banco, periodo, col_credito_bruta_e1_alt),
                legacy_outros_value=_lk_get(lk_ativo, banco, periodo, col_credito_bruta_f),
                vcb_credito_value=_lk_get(lk_ativo, banco, periodo, col_credito_bruta_e1),
                vcb_arrendamento_value=_lk_get(lk_ativo, banco, periodo, col_credito_bruta_f1),
                vcb_outras_ops_value=_lk_get(lk_ativo, banco, periodo, col_credito_bruta_g1),
                vcb_pagamentos_value=_lk_get(lk_ativo, banco, periodo, col_credito_bruta_h1),
                net_credito_value=_lk_get(lk_ativo, banco, periodo, col_credito_net_e),
                net_arrendamento_value=_lk_get(lk_ativo, banco, periodo, col_credito_net_f),
                net_outras_ops_value=_lk_get(lk_ativo, banco, periodo, col_credito_net_g),
                net_pagamentos_value=_lk_get(lk_ativo, banco, periodo, col_credito_net_h),
            ).get("value")
            extra["Carteira de Crédito Bruta"][chave] = carteira_bruta
            extra["Carteira de Crédito*"][chave] = carteira_bruta

            # Ativos Líquidos = Disponibilidades (a) + Aplicações Interfinanceiras (b) + TVM (c)
            # do relatório de Ativo (Rel. 2)
            ativos_liquidos = _somar_valores([
                _lk_get(lk_ativo, banco, periodo, col_disp_ativo),
                _lk_get(lk_ativo, banco, periodo, col_aplic_ativo),
                _lk_get(lk_ativo, banco, periodo, col_tvm_ativo),
            ])
            extra["Ativos Líquidos"][chave] = ativos_liquidos

            depositos_totais = resolve_depositos_totais_value(
                aggregate_candidates=[
                    (col_name, _lk_get(lk_passivo, banco, periodo, col_name))
                    for col_name in cols_depositos_passivo
                ],
                component_values={
                    "Depósitos à Vista (a1)": _lk_get(lk_passivo, banco, periodo, col_dep_a1),
                    "Depósitos de Poupança (a2)": _lk_get(lk_passivo, banco, periodo, col_dep_a2),
                    "Depósitos Interfinanceiros (a3)": _lk_get(lk_passivo, banco, periodo, col_dep_a3),
                    "Depósitos a Prazo (a4)": _lk_get(lk_passivo, banco, periodo, col_dep_a4),
                    "Outros Depósitos (a5)": _lk_get(lk_passivo, banco, periodo, col_dep_a5),
                    "Depósitos Outros (a6)": _lk_get(lk_passivo, banco, periodo, col_dep_a6),
                },
            )
            extra["Depósitos Totais"][chave] = _coerce_numeric_value(depositos_totais.get("value"))

            # Core Funding (até 2024 = Captações; 2025+ exige Captações + dívida subordinada h)
            cap_val = _lk_get(lk_passivo, banco, periodo, col_capt_passivo)
            instr_val = _lk_get(lk_passivo, banco, periodo, col_instr_passivo)
            core_funding = resolve_core_funding_value(
                year_ref=ano_ref,
                captacoes_value=cap_val,
                instrumentos_value=instr_val,
            ).get("value")
            extra["Core Funding"][chave] = _coerce_numeric_value(core_funding)
            extra["Core Funding*"][chave] = _coerce_numeric_value(core_funding)

            perda_vals = [
                _lk_get(lk_ativo, banco, periodo, col)
                for col in perda_colunas
            ]
            perda_esperada = _somar_valores(perda_vals)
            extra["Perda Esperada"][chave] = perda_esperada
            perda_ratio = _calcular_ratio_peers(
                perda_esperada,
                carteira_bruta,
            )
            extra["Perda Esperada / Carteira de Crédito Bruta"][chave] = perda_ratio
            extra["Perda Esperada / Carteira de Crédito*"][chave] = perda_ratio

            valor_c4 = _lk_get(lk_instr, banco, periodo, col_c4)
            valor_c5 = _lk_get(lk_instr, banco, periodo, col_c5)
            carteira_c4_c5 = _somar_valores([valor_c4, valor_c5])
            extra["Carteira de Créd. Class. C4+C5"][chave] = carteira_c4_c5
            extra["Carteira de Créd. Class. C4+C5 / Carteira Classificada"][chave] = _calcular_ratio_peers(
                carteira_c4_c5,
                carteira_classificada,
            )
            extra["Perda Esperada / (Carteira C4 + C5)"][chave] = _calcular_ratio_peers(
                perda_esperada,
                carteira_c4_c5,
            )

            pdd_credito = _blop_get_sum_periodo_conta(banco, periodo, "1490000004")
            pdd_outros = _blop_get_sum_periodo_conta(banco, periodo, "1890000006")
            pdd_total_4060 = _somar_valores([pdd_credito, pdd_outros])
            estagio1_mes = _blop_get_sum_periodo_conta(banco, periodo, "3311000002")
            estagio2_mes = _blop_get_sum_periodo_conta(banco, periodo, "3312000001")
            estagio3_mes = _blop_get_sum_periodo_conta(banco, periodo, "3313000000")

            extra["Saldo PDD Crédito"][chave] = pdd_credito
            extra["Saldo PDD Outros Créditos"][chave] = pdd_outros
            extra["PDD Total 4060"][chave] = pdd_total_4060
            extra["Carteira Estágio 1"][chave] = estagio1_mes
            extra["Ativos Estágio 2"][chave] = estagio2_mes
            extra["Ativos Estágio 3"][chave] = estagio3_mes
            extra["PDD / Estágio 3"][chave] = _calcular_ratio_peers(pdd_total_4060, estagio3_mes)
            extra["Perda Esperada / Estágio 3"][chave] = _calcular_ratio_peers(perda_esperada, estagio3_mes)
            extra["Perda Esperada / Est2+3"][chave] = _calcular_ratio_peers(
                perda_esperada,
                _somar_estagios_2_3_peers(estagio2_mes, estagio3_mes),
            )

            # Capital: Índice de Capital Principal e Índice de Basileia Total
            # Prioridade: calcular da composição (Capital Principal / RWA);
            # fallback: usar valor pré-calculado do cache de capital.
            indice_cap_principal = None
            if col_cap_principal and col_rwa_total:
                val_cp = _coerce_numeric_value(
                    _lk_get(lk_capital, banco, periodo, col_cap_principal)
                )
                val_rwa = _coerce_numeric_value(
                    _lk_get(lk_capital, banco, periodo, col_rwa_total)
                )
                if val_cp is not None and val_rwa is not None and not pd.isna(val_cp) and not pd.isna(val_rwa) and float(val_rwa) != 0:
                    indice_cap_principal = float(val_cp) / float(val_rwa)
            if indice_cap_principal is None and col_indice_cap_principal:
                val_precalc = _coerce_numeric_value(
                    _lk_get(lk_capital, banco, periodo, col_indice_cap_principal)
                )
                if val_precalc is not None and not pd.isna(val_precalc):
                    v = float(val_precalc)
                    # Normalizar para decimal (0-1): cache pode ter 0-100
                    indice_cap_principal = v / 100 if abs(v) > 1 else v
            extra["Índice de Capital Principal (CET1)"][chave] = indice_cap_principal

            indice_basileia = None
            if col_cap_principal and col_cap_complementar and col_cap_nivel2 and col_rwa_total:
                val_cp = _coerce_numeric_value(
                    _lk_get(lk_capital, banco, periodo, col_cap_principal)
                )
                val_cc = _coerce_numeric_value(
                    _lk_get(lk_capital, banco, periodo, col_cap_complementar)
                )
                val_n2 = _coerce_numeric_value(
                    _lk_get(lk_capital, banco, periodo, col_cap_nivel2)
                )
                val_rwa = _coerce_numeric_value(
                    _lk_get(lk_capital, banco, periodo, col_rwa_total)
                )
                if (
                    val_cp is not None and val_cc is not None and val_n2 is not None and val_rwa is not None
                    and not pd.isna(val_cp) and not pd.isna(val_cc) and not pd.isna(val_n2) and not pd.isna(val_rwa)
                    and float(val_rwa) != 0
                ):
                    indice_basileia = (float(val_cp) + float(val_cc) + float(val_n2)) / float(val_rwa)
            if indice_basileia is None and col_indice_basileia_precalc:
                val_precalc = _coerce_numeric_value(
                    _lk_get(lk_capital, banco, periodo, col_indice_basileia_precalc)
                )
                if val_precalc is not None and not pd.isna(val_precalc):
                    v = float(val_precalc)
                    # Normalizar para decimal (0-1): cache pode ter 0-100
                    indice_basileia = v / 100 if abs(v) > 1 else v
            extra["Índice de Basileia Total (%)"][chave] = indice_basileia

    return extra


def _calcular_ratio_peers(valor_num, valor_den) -> Optional[float]:
    if valor_num is None or valor_den is None:
        return None
    if pd.isna(valor_num) or pd.isna(valor_den):
        return None
    try:
        valor_den_float = float(valor_den)
        if valor_den_float == 0:
            return None
        return float(valor_num) / valor_den_float
    except Exception:
        return None


def _somar_estagios_2_3_peers(estagio2, estagio3) -> Optional[float]:
    valor_est2 = _coerce_numeric_value(estagio2)
    valor_est3 = _coerce_numeric_value(estagio3)
    if valor_est2 is None or valor_est3 is None:
        return None
    if pd.isna(valor_est2) or pd.isna(valor_est3):
        return None
    return float(valor_est2) + float(valor_est3)


def _acumular_dre_ytd_peers(
    cache_dre: Optional[pd.DataFrame],
    banco: str,
    periodo: str,
    coluna: Optional[str],
) -> Optional[float]:
    """Converte valor DRE bruto para YTD acumulado.

    O BCB (Relatório 4) publica dados DRE de forma semestral:
      - Mar (parte=1): Jan-Mar → já é YTD (3 meses)
      - Jun (parte=2): Jan-Jun → já é YTD (6 meses)
      - Set (parte=3): Jul-Set → precisa somar Jun (Jan-Jun) para YTD (9 meses)
      - Dez (parte=4): Jul-Dez → precisa somar Jun (Jan-Jun) para YTD (12 meses)

    Retorna valor numérico YTD ou None se dados insuficientes.
    """
    valor_raw = _obter_valor_peers(cache_dre, banco, periodo, coluna)
    if valor_raw is None or pd.isna(valor_raw):
        return None
    valor_num = _coerce_numeric_value(valor_raw)
    if valor_num is None or pd.isna(valor_num):
        return None
    parsed = _parse_periodo(periodo)
    if not parsed:
        return float(valor_num)
    parte, _, _ = parsed
    try:
        parte_int = int(parte)
    except ValueError:
        return float(valor_num)
    # Determinar se precisa acumular (Set e Dez precisam de Jun)
    if 1 <= parte_int <= 4:
        precisa_jun = parte_int in (3, 4)
        parte_jun = 2
    elif 1 <= parte_int <= 12:
        precisa_jun = parte_int in (9, 12)
        parte_jun = 6
    else:
        return float(valor_num)
    if not precisa_jun:
        return float(valor_num)
    periodo_jun = _periodo_mesma_estrutura(periodo, parte_jun)
    if not periodo_jun:
        return None
    valor_jun = _obter_valor_peers(cache_dre, banco, periodo_jun, coluna)
    if valor_jun is None or pd.isna(valor_jun):
        return None
    valor_jun_num = _coerce_numeric_value(valor_jun)
    if valor_jun_num is None or pd.isna(valor_jun_num):
        return None
    return float(valor_num) + float(valor_jun_num)


def _compute_ytd_irregular_ifdata_frame(df: pd.DataFrame) -> pd.DataFrame:
    """Reconstrói YTD semestral do Rel. 4 sem imputar junho ausente como zero."""
    if df.empty:
        return df.copy()

    out = df.copy()
    parsed = out["Periodo"].apply(_parse_periodo)
    out["ano"] = parsed.apply(lambda x: x[1] if x else pd.NA).astype("Int64")
    out["mes"] = parsed.apply(
        lambda x: ({1: 3, 2: 6, 3: 9, 4: 12}.get(_parte_periodo_para_trimestre_idx(x[0]), int(x[0])) if x else pd.NA)
    ).astype("Int64")
    out["valor"] = pd.to_numeric(out["valor"], errors="coerce")
    out = out.sort_values(["Instituicao", "Label", "ano", "mes", "Periodo"], na_position="last").reset_index(drop=True)
    out["ytd"] = out["valor"]

    keys = ["Instituicao", "Label", "ano"]
    jun = (
        out[out["mes"] == 6][keys + ["valor"]]
        .rename(columns={"valor": "valor_jun"})
        .drop_duplicates(subset=keys, keep="last")
    )
    out = out.merge(jun, on=keys, how="left")
    mask_set_dez = out["mes"].isin([9, 12])
    if mask_set_dez.any():
        out.loc[mask_set_dez, "ytd"] = out.loc[mask_set_dez, "valor"] + out.loc[mask_set_dez, "valor_jun"]
        out.loc[mask_set_dez & out["valor_jun"].isna(), "ytd"] = np.nan
    out = out.drop(columns=["valor_jun"])

    return out


