_DRE_CONSOLIDATED_CHILD_LABELS = {
    "Rec. Aplicações Interfinanceiras Liquidez",
    "Rec. TVMs",
    "Rec. Crédito",
    "Rec. Arrendamento Financeiro",
    "Rec. Outras Operações c/ Características de Crédito",
}

_DRE_CONSOLIDATED_ALIAS_LOOKUP = {
    "Lucro Líquido Período Acumulado": "Lucro Líquido Período",
}


def _normalize_dre_sources(value) -> list[str]:
    if value is None:
        return []
    if isinstance(value, list):
        return [str(v).strip() for v in value if str(v).strip()]
    if isinstance(value, str):
        parts = [p.strip() for p in value.replace("|", ";").split(";")]
        return [p for p in parts if p]
    return []


def _normalize_dre_source_name(value: str) -> str:
    return re.sub(r"\s+", "", str(value or "").strip()).lower()


def _find_dre_source_column(df: pd.DataFrame, source_name: str) -> Optional[str]:
    target = _normalize_dre_source_name(source_name)
    if not target:
        return None
    for col in df.columns:
        if _normalize_dre_source_name(col) == target:
            return col
    return None


@st.cache_data(ttl=3600, show_spinner=False)
def _load_dre_mapping_payload():
    caminho = Path("data/dre_mapping.json")
    if not caminho.exists():
        return []
    try:
        payload = json.loads(caminho.read_text(encoding="utf-8"))
    except Exception:
        return []
    return payload if isinstance(payload, list) else []


def _build_dre_consolidated_mapping_entries() -> list[dict]:
    payload = _load_dre_mapping_payload()
    payload_map = {
        str(item.get("label") or "").strip(): item
        for item in payload
        if isinstance(item, dict) and str(item.get("label") or "").strip()
    }
    entries = []
    for label in _DRE_CONSOLIDATED_ORDER:
        lookup = _DRE_CONSOLIDATED_ALIAS_LOOKUP.get(label, label)
        base_item = payload_map.get(lookup, {})
        sources_old = _normalize_dre_sources(base_item.get("sources_old"))
        sources_new = _normalize_dre_sources(base_item.get("sources_new"))
        sources_new_q4 = _normalize_dre_sources(base_item.get("sources_new_q4"))

        current_sources = sources_new_q4 or sources_new or sources_old
        all_sources = []
        for group in (sources_old, sources_new, sources_new_q4):
            for source in group:
                if source not in all_sources:
                    all_sources.append(source)

        entries.append(
            {
                "label": label,
                "sources": current_sources,
                "sources_old": sources_old,
                "sources_new": sources_new,
                "sources_new_q4": sources_new_q4,
                "has_sources_new_q4": "sources_new_q4" in base_item,
                "concept": str(base_item.get("concept") or "").strip(),
                "original_label": " / ".join(all_sources) if all_sources else lookup,
                "is_child": label in _DRE_CONSOLIDATED_CHILD_LABELS,
            }
        )

    entries.extend(
        [
            {
                "label": "Desp PDD / Resultado Intermediação Fin. Bruto",
                "derived_metric": "Desp PDD / Resultado Intermediação Fin. Bruto",
                "format": "pct",
                "concept": "Desp. PDD dividido pelo Resultado de Intermediação Financeira Bruto.",
            },
            {
                "label": "Desp Captação / Captação",
                "derived_metric": "Desp Captação / Captação",
                "format": "pct",
                "concept": "Desp. Captação anualizada dividida por Captações.",
            },
        ]
    )
    return entries


def _resolve_dre_entry_values_period_aware(
    df: pd.DataFrame,
    entry: Mapping[str, Any],
    numericas: Mapping[str, pd.Series],
    source_to_column: Mapping[str, str],
) -> pd.Series:
    valores = pd.Series(np.nan, index=df.index, dtype="float64")

    def _family_values(sources) -> Optional[pd.Series]:
        cols = [source_to_column[s] for s in _normalize_dre_sources(sources) if s in source_to_column]
        if not cols:
            return None
        return pd.concat([numericas[col] for col in cols], axis=1).sum(axis=1, min_count=1)

    old_values = _family_values(entry.get("sources_old"))
    new_values = _family_values(entry.get("sources_new"))
    q4_values = _family_values(entry.get("sources_new_q4"))

    old_mask = df["ano"].fillna(0) <= 2024
    new_mask = df["ano"].fillna(0) >= 2025
    q4_2025_mask = df["ano"].eq(2025) & df["mes"].eq(12)

    if old_values is not None:
        valores.loc[old_mask] = old_values.loc[old_mask]

    if new_values is not None:
        mask_new_effective = new_mask & ~q4_2025_mask if entry.get("has_sources_new_q4") else new_mask
        valores.loc[mask_new_effective] = new_values.loc[mask_new_effective]

    if entry.get("has_sources_new_q4"):
        if q4_values is not None:
            valores.loc[q4_2025_mask] = q4_values.loc[q4_2025_mask]
        else:
            valores.loc[q4_2025_mask] = np.nan

    return valores


def _anualizar_valor_dre(valor, periodo: str) -> Optional[float]:
    """Anualiza valor DRE já acumulado YTD: valor_ytd / meses * 12."""
    if valor is None or pd.isna(valor):
        return None
    valor_num = _coerce_numeric_value(valor)
    if valor_num is None or pd.isna(valor_num):
        return None
    parsed = _parse_periodo(periodo)
    if not parsed:
        return float(valor_num)
    parte, _, _ = parsed
    try:
        parte_int = int(parte)
    except ValueError:
        return float(valor_num)
    if 1 <= parte_int <= 4:
        meses = parte_int * 3
    elif 1 <= parte_int <= 12:
        meses = parte_int
    else:
        meses = None
    if not meses:
        return float(valor_num)
    if meses == 0:
        return None
    return float(valor_num) / meses * 12


def _ajustar_lucro_acumulado_peers(
    df: pd.DataFrame,
    banco: str,
    periodo: str,
    coluna: Optional[str],
):
    """Retorna LL YTD do período.

    A acumulação Set (Q3 + Jun) já foi feita em recalcular_metricas_derivadas(),
    que sobrescreve a coluna 'Lucro Líquido Acumulado YTD' com o valor YTD.
    Aqui apenas lemos o valor já acumulado — NÃO somar Jun novamente.
    """
    return _obter_valor_peers(df, banco, periodo, coluna)


@st.cache_data(ttl=900, show_spinner=False)
def _preparar_metricas_extra_peers_cached(
    bancos_tuple: tuple,
    periodos_tuple: tuple,
    periodos_ext_tuple: tuple,
    instituicoes_slice_tuple: tuple,
    alias_sig: tuple,
    slice_tokens: tuple,
) -> dict:
    """Wrapper cacheado: lê apenas o parquet curado de Snapshot/Peers."""
    import time as _time

    _ = alias_sig
    _t0_wrapper = _time.perf_counter()
    slice_tokens_dict = dict(slice_tokens)
    token = slice_tokens_dict.get("critical_screens")
    df_slice = _carregar_cache_relatorio_slice(
        "critical_screens",
        token or _cache_version_token("critical_screens"),
        periodos_ext_tuple,
        instituicoes_slice_tuple,
    )
    lookup = _critical_metric_lookup(df_slice)
    result = {metric: {} for metric in CRITICAL_EXTRA_METRICS}
    for banco in bancos_tuple:
        for periodo in periodos_ext_tuple:
            row = lookup.get((banco, periodo), {})
            for metric in CRITICAL_EXTRA_METRICS:
                result[metric][(banco, periodo)] = _coerce_numeric_value(row.get(metric))

    _elapsed_total = _time.perf_counter() - _t0_wrapper
    print(f"[PEERS_TIMING] critical_screens_slice_total: {_elapsed_total:.3f}s")
    return result


def _preparar_metricas_extra_peers_from_slice(
    df_slice: Optional[pd.DataFrame],
    bancos: list[str],
    periodos: Sequence[str],
) -> dict:
    """Extrai métricas extras diretamente do slice já carregado do cache curado."""
    lookup = _critical_metric_lookup(df_slice)
    result = {metric: {} for metric in CRITICAL_EXTRA_METRICS}
    for banco in bancos:
        for periodo in periodos:
            row = lookup.get((banco, periodo), {})
            for metric in CRITICAL_EXTRA_METRICS:
                valor = _coerce_numeric_value(row.get(metric))
                if metric == "Perda Esperada / Est2+3" and (valor is None or pd.isna(valor)):
                    valor = _calcular_ratio_peers(
                        row.get("Perda Esperada"),
                        _somar_estagios_2_3_peers(
                            row.get("Ativos Estágio 2"),
                            row.get("Ativos Estágio 3"),
                        ),
                    )
                result[metric][(banco, periodo)] = valor
    return result


def _montar_tabela_peers(
    df: pd.DataFrame,
    bancos: list,
    periodos: list,
    caches_extras: Optional[dict] = None,
    perf: Optional[dict] = None,
    extra_values_precomputed: Optional[dict] = None,
    allow_capital_fallback: bool = True,
):
    """Monta estrutura da tabela peers com valores por banco/período."""
    valores = {}
    colunas_usadas = {}
    faltas = set()
    delta_flags = {}
    delta_context = {}
    tooltips = {}
    coluna_ativo = _resolver_coluna_peers(df, ["Ativo Total"])
    coluna_pl = _resolver_coluna_peers(df, ["Patrimônio Líquido"])
    coluna_lucro = _resolver_coluna_peers(df, ["Lucro Líquido Acumulado YTD", "Lucro Líquido"])
    if perf is None:
        perf = {}

    # FIX-2: evita reconstruções/lazy builds por célula.
    main_lookup = _build_peers_lookup(df)
    def _lk_main_get(banco: str, periodo: str, coluna: Optional[str]):
        if coluna is None or not main_lookup:
            return None
        row = main_lookup.get((banco, periodo))
        if row is None:
            return None
        return row.get(coluna)
    t_extra = time.perf_counter()
    if extra_values_precomputed is not None:
        extra_values = extra_values_precomputed
    else:
        extra_values = _preparar_metricas_extra_peers(
            bancos,
            periodos,
            (caches_extras or {}).get("ativo"),
            (caches_extras or {}).get("passivo"),
            (caches_extras or {}).get("carteira_pf"),
            (caches_extras or {}).get("carteira_pj"),
            (caches_extras or {}).get("carteira_instrumentos"),
            (caches_extras or {}).get("dre"),
            (caches_extras or {}).get("capital"),
            (caches_extras or {}).get("bloprudencial"),
        )
    _perf_peers_stage(perf, "c_joins_mapeamentos_metricas_extra", t_extra)

    # Fonte canônica de capital compartilhada com Rankings:
    # evita divergência de CET1/Basileia entre abas.
    # PERF: só consulta base canônica quando houver lacunas no recorte já calculado.
    precisa_capital_canonico = False
    for banco in bancos:
        for periodo in periodos:
            chave_cap = (banco, periodo)
            cet1_v = extra_values.get("Índice de Capital Principal (CET1)", {}).get(chave_cap)
            bas_v = extra_values.get("Índice de Basileia Total (%)", {}).get(chave_cap)
            if cet1_v is None or bas_v is None or pd.isna(cet1_v) or pd.isna(bas_v):
                precisa_capital_canonico = True
                break
        if precisa_capital_canonico:
            break

    if precisa_capital_canonico and allow_capital_fallback:
        t_capital_unificado = time.perf_counter()
        df_capital_idx = _construir_indices_capital_unificados(
            _cache_version_token("capital"),
            _alias_signature(),
        )
        _perf_peers_stage(perf, "c_capital_unificado_fallback", t_capital_unificado)
        if df_capital_idx is not None and not df_capital_idx.empty:
            df_capital_idx = df_capital_idx.copy()
            if "Instituição" in df_capital_idx.columns and "Período" in df_capital_idx.columns:
                df_capital_idx["inst_key"] = df_capital_idx["Instituição"].apply(normalizar_nome_instituicao)
                df_capital_idx["per_key"] = df_capital_idx["Período"].apply(normalizar_periodo_chave)
                capital_dict = (
                    df_capital_idx
                    .dropna(subset=["inst_key", "per_key"])
                    .set_index(["inst_key", "per_key"])
                    .to_dict("index")
                )
                for banco in bancos:
                    for periodo in periodos:
                        chave_saida = (banco, periodo)
                        chave_peers = (normalizar_nome_instituicao(banco), normalizar_periodo_chave(periodo))
                        row_cap = capital_dict.get(chave_peers) or {}
                        cet1_atual = extra_values["Índice de Capital Principal (CET1)"].get(chave_saida)
                        bas_atual = extra_values["Índice de Basileia Total (%)"].get(chave_saida)
                        if cet1_atual is None or pd.isna(cet1_atual):
                            extra_values["Índice de Capital Principal (CET1)"][chave_saida] = _coerce_numeric_value(
                                row_cap.get("Índice de Capital Principal (CET1)")
                            )
                        if bas_atual is None or pd.isna(bas_atual):
                            extra_values["Índice de Basileia Total (%)"][chave_saida] = _coerce_numeric_value(
                                row_cap.get("Índice de Basileia Total (%)")
                            )

    coluna_credito = _resolver_coluna_peers(df, ["Carteira de Crédito Bruta", "Carteira de Crédito"])

    t_calc = time.perf_counter()
    for section in PEERS_TABELA_LAYOUT:
        for row in section["rows"]:
            label = row["label"]
            candidatos = row.get("data_keys", [])
            coluna = _resolver_coluna_peers(df, candidatos) if candidatos else None
            if label == "Ativo Total / PL":
                coluna = None
            colunas_usadas[label] = coluna
            if coluna is None and row.get("todo"):
                faltas.add(label)

            for banco in bancos:
                for periodo in periodos:
                    chave = (label, banco, periodo)
                    valor = None
                    tip = ""
                    # Mapeamento de ratios → (chave numerador, chave denominador)
                    _RATIO_COMPONENTS = {
                        "Perda Esperada / Carteira de Crédito*": ("Perda Esperada", "Carteira de Crédito Bruta"),
                        "Carteira de Créd. Class. C4+C5 / Carteira Classificada": ("Carteira de Créd. Class. C4+C5", "Carteira de Crédito Classificada"),
                        "Perda Esperada / (Carteira C4 + C5)": ("Perda Esperada", "Carteira de Créd. Class. C4+C5"),
                        "PDD / Estágio 3": ("PDD Total 4060", "Ativos Estágio 3"),
                        "Perda Esperada / Estágio 3": ("Perda Esperada", "Ativos Estágio 3"),
                    }
                    if label == "Perda Esperada / Est2+3" and label in extra_values:
                        valor = extra_values[label].get((banco, periodo))
                        valor_num = extra_values.get("Perda Esperada", {}).get((banco, periodo))
                        valor_den = _somar_estagios_2_3_peers(
                            extra_values.get("Ativos Estágio 2", {}).get((banco, periodo)),
                            extra_values.get("Ativos Estágio 3", {}).get((banco, periodo)),
                        )
                        tip = _tooltip_ratio_peers(label, valor_num, valor_den, valor)
                    elif label in extra_values and label in _RATIO_COMPONENTS:
                        valor = extra_values[label].get((banco, periodo))
                        num_key, den_key = _RATIO_COMPONENTS[label]
                        valor_num = extra_values.get(num_key, {}).get((banco, periodo))
                        valor_den = extra_values.get(den_key, {}).get((banco, periodo))
                        tip = _tooltip_ratio_peers(label, valor_num, valor_den, valor)
                    elif label in extra_values:
                        valor = extra_values[label].get((banco, periodo))
                        if label in ("Índice de Capital Principal (CET1)", "Índice de Basileia Total (%)"):
                            if valor is not None and not pd.isna(valor):
                                tip = f"{label}: {_formatar_percentual(float(valor), decimais=2)}"
                            else:
                                tip = f"{label}: N/A"
                        else:
                            tip = f"{label}: {_fmt_tooltip_mm(valor)}" if valor is not None else ""
                    elif label == "Ativo Total / PL":
                        valor_ativo = _lk_main_get(banco, periodo, coluna_ativo)
                        valor_pl = _lk_main_get(banco, periodo, coluna_pl)
                        valor = _calcular_ratio_peers(valor_ativo, valor_pl)
                        tip = _tooltip_ratio_peers(label, valor_ativo, valor_pl, valor)
                    elif label == "Carteira de Crédito* / PL":
                        valor_credito = extra_values.get("Carteira de Crédito Bruta", {}).get((banco, periodo))
                        if valor_credito is None or pd.isna(valor_credito):
                            valor_credito = _lk_main_get(banco, periodo, coluna_credito)
                        valor_pl_v = _lk_main_get(banco, periodo, coluna_pl)
                        valor = _calcular_ratio_peers(valor_credito, valor_pl_v)
                        tip = _tooltip_ratio_peers(label, valor_credito, valor_pl_v, valor)
                    elif coluna:
                        if label == "Lucro Líquido Acumulado":
                            valor = _ajustar_lucro_acumulado_peers(df, banco, periodo, coluna)
                            tip = _tooltip_ll_peers(df, banco, periodo, coluna, valor)
                        else:
                            valor = _lk_main_get(banco, periodo, coluna)
                            if coluna and "(%)" in coluna and valor is not None and not pd.isna(valor):
                                try:
                                    tip = f"{label}: {_formatar_percentual(float(valor), decimais=2)}"
                                except Exception:
                                    tip = ""
                            else:
                                tip = f"{coluna}: {_fmt_tooltip_mm(valor)}" if valor is not None else ""
                    valores[chave] = valor
                    tooltips[chave] = tip

                    delta_flag = None
                    periodo_base = _periodo_ano_anterior(periodo)
                    if periodo_base and label in extra_values:
                        valor_base = extra_values[label].get((banco, periodo_base))
                    elif periodo_base and coluna:
                        if label == "Lucro Líquido Acumulado":
                            valor_base = _ajustar_lucro_acumulado_peers(df, banco, periodo_base, coluna)
                        else:
                            valor_base = _lk_main_get(banco, periodo_base, coluna)
                    elif periodo_base and label == "Ativo Total / PL":
                        valor_ativo_base = _lk_main_get(banco, periodo_base, coluna_ativo)
                        valor_pl_base = _lk_main_get(banco, periodo_base, coluna_pl)
                        valor_base = _calcular_ratio_peers(valor_ativo_base, valor_pl_base)
                    elif periodo_base and label == "Carteira de Crédito* / PL":
                        valor_credito_b = extra_values.get("Carteira de Crédito Bruta", {}).get((banco, periodo_base))
                        if valor_credito_b is None or pd.isna(valor_credito_b):
                            valor_credito_b = _lk_main_get(banco, periodo_base, coluna_credito)
                        valor_pl_b = _lk_main_get(banco, periodo_base, coluna_pl)
                        valor_base = _calcular_ratio_peers(valor_credito_b, valor_pl_b)
                    else:
                        valor_base = None
                    if valor_base is not None and valor is not None and not pd.isna(valor) and not pd.isna(valor_base):
                        delta = valor - valor_base
                        if delta > 0:
                            delta_flag = "up"
                        elif delta < 0:
                            delta_flag = "down"
                        if delta_flag in ("up", "down"):
                            valor_atual_fmt = _formatar_valor_peers(valor, row["format_key"], coluna_origem=coluna)
                            valor_base_fmt = _formatar_valor_peers(valor_base, row["format_key"], coluna_origem=coluna)
                            delta_context[chave] = (
                                f"Comparação Δ: {periodo_para_exibicao(periodo)} vs {periodo_para_exibicao(periodo_base)}"
                                f"\nAtual: {valor_atual_fmt}"
                                f"\nBase: {valor_base_fmt}"
                            )
                    delta_flags[chave] = delta_flag

    _perf_peers_stage(perf, "d_calculo_metricas_colunas_derivadas", t_calc)
    return valores, colunas_usadas, faltas, delta_flags, delta_context, tooltips


