@st.cache_data(ttl=900, show_spinner=False)
def _get_evolucao_filters_context(principal_token: str, alias_sig: tuple) -> dict:
    # [CHANGE] Data: 2026-04-05 | Aba: Evolução | Prioridade: P1
    # Motivo: a aba concatenava a base analítica inteira antes mesmo de montar os filtros.
    # Solução: contexto leve com apenas instituições e períodos válidos.
    # Impacto: reduz tempo até o menu ficar utilizável; sem alterar cálculos financeiros.
    # Testado em: py_compile e medição direta do contexto leve.
    """Retorna instituições e períodos válidos da aba Evolução sem concatenar a base inteira."""
    dados_periodos = _carregar_dados_periodos_preparados(principal_token, alias_sig)
    if not dados_periodos:
        return {"instituicoes": (), "periodos_validos": ()}

    instituicoes = set()
    periodos_validos = []
    for periodo, df_periodo in dados_periodos.items():
        parsed = _parse_periodo(str(periodo))
        if parsed:
            parte, ano, _ = parsed
            tri = _parte_periodo_para_trimestre_idx(parte)
            if tri is not None:
                periodos_validos.append((str(periodo), int(ano), int(tri)))

        if df_periodo is None or df_periodo.empty or "Instituição" not in df_periodo.columns:
            continue
        instituicoes.update(df_periodo["Instituição"].dropna().astype(str).unique().tolist())

    periodos_validos = tuple(sorted(set(periodos_validos), key=lambda item: (item[1], item[2], item[0])))
    return {
        "instituicoes": tuple(sorted(instituicoes)),
        "periodos_validos": periodos_validos,
    }


@st.cache_data(ttl=900, show_spinner=False)
def _get_evolucao_instituicao_base_df(
    principal_token: str,
    alias_sig: tuple,
    instituicao: str,
    periodos_filter: tuple,
) -> pd.DataFrame:
    # [CHANGE] Data: 2026-04-05 | Aba: Evolução | Prioridade: P1
    # Motivo: a troca de IF recalculava/concatenava dados de todas as instituições.
    # Solução: carregar só a série da instituição/períodos selecionados.
    # Impacto: reduz custo de troca de IF; sem alterar fórmulas nem memória de cálculo.
    # Testado em: py_compile e medição direta do slice por instituição.
    """Carrega apenas a série necessária da instituição selecionada para a aba Evolução."""
    dados_periodos = _carregar_dados_periodos_preparados(principal_token, alias_sig)
    if not dados_periodos or not instituicao:
        return pd.DataFrame()

    periodos_set = {str(p) for p in periodos_filter if p is not None}
    frames = []
    for periodo, df_periodo in dados_periodos.items():
        if periodos_set and str(periodo) not in periodos_set:
            continue
        if df_periodo is None or df_periodo.empty or "Instituição" not in df_periodo.columns:
            continue
        df_slice = df_periodo[df_periodo["Instituição"].astype(str) == str(instituicao)].copy()
        if not df_slice.empty:
            frames.append(df_slice)

    if not frames:
        return pd.DataFrame()

    result = pd.concat(frames, ignore_index=True)
    result = _normalizar_lucro_liquido(result.copy())
    result = _recalcular_roe_anualizado_df(result)
    result = _recalcular_roe_trimestral_df(result)
    return result


RANKINGS_FAMILY_PRINCIPAL_PREPARED = frozenset(
    {
        "Ativo Total",
        "Carteira de Crédito*",
        "Core Funding*",
        "Patrimônio Líquido",
    }
)
RANKINGS_FAMILY_CAPITAL_PREPARED = frozenset(
    {
        "Índice de Capital Principal (CET1)",
        "Índice de Capital T1 (%)",
        "Índice de Basileia Total (%)",
    }
)
RANKINGS_FAMILY_ANALYTICAL = frozenset(
    {
        "Lucro Líquido Trimestral",
        "ROE Trim. Anualizado (%)",
    }
)


def _rankings_periodos_selecionados(periodos_selecionados: Sequence[str]) -> tuple[str, ...]:
    return tuple(sorted({str(periodo) for periodo in periodos_selecionados if periodo}))


def _rankings_periodo_mesma_representacao(periodo: str, tri_idx: int) -> Optional[str]:
    parsed = _parse_periodo(periodo)
    if not parsed:
        return None
    parte_txt = str(parsed[0]).strip()
    if parte_txt in {"03", "06", "09", "12"}:
        tri_para_parte = {1: 3, 2: 6, 3: 9, 4: 12}
    else:
        tri_para_parte = {1: 1, 2: 2, 3: 3, 4: 4}
    novo_parte = tri_para_parte.get(tri_idx)
    if novo_parte is None:
        return None
    return _periodo_mesma_estrutura(periodo, novo_parte)


def _expandir_periodos_evolucao_calculo(periodos_exibicao: Sequence[str]) -> tuple[str, ...]:
    """Inclui dependências temporais usadas para LL YTD semestral e ROE."""
    periodos_set = {str(periodo) for periodo in periodos_exibicao if periodo}
    for periodo in list(periodos_set):
        parsed = _parse_periodo(periodo)
        if not parsed:
            continue
        parte, _, _ = parsed
        tri_idx = _parte_periodo_para_trimestre_idx(parte)
        if tri_idx in (3, 4):
            periodo_jun = _rankings_periodo_mesma_representacao(periodo, 2)
            if periodo_jun:
                periodos_set.add(periodo_jun)
        periodo_dez_anterior = _periodo_dez_ano_anterior(periodo)
        if periodo_dez_anterior:
            periodos_set.add(periodo_dez_anterior)
    return tuple(ordenar_periodos(list(periodos_set), reverso=False))


def _rankings_expandir_periodos_analiticos(
    periodos_selecionados: Sequence[str],
    *,
    incluir_prev_dez: bool,
    incluir_contexto_trimestral: bool,
) -> tuple[str, ...]:
    """Expande apenas os períodos realmente exigidos por métricas analíticas.

    - ROE anualizado: precisa de dezembro do ano anterior para PL médio.
    - Lucro trimestral / ROE trimestral: precisam do trimestre-base e, para Jun/Dez,
      também do trimestre imediatamente anterior do mesmo ano para decomposição do YTD.
    """
    periodos_set = set(_rankings_periodos_selecionados(periodos_selecionados))
    for periodo in list(periodos_set):
        if incluir_prev_dez:
            periodo_dez = _periodo_dez_ano_anterior(periodo)
            if periodo_dez:
                periodos_set.add(periodo_dez)

        if not incluir_contexto_trimestral:
            continue

        parsed = _periodo_para_ano_trimestre(periodo)
        tri_idx = parsed[1] if parsed else None
        if tri_idx == 2:
            periodo_aux = _rankings_periodo_mesma_representacao(periodo, 1)
            if periodo_aux:
                periodos_set.add(periodo_aux)
        elif tri_idx == 4:
            periodo_aux = _rankings_periodo_mesma_representacao(periodo, 3)
            if periodo_aux:
                periodos_set.add(periodo_aux)

    return tuple(sorted(periodos_set))


def _rankings_expandir_periodos_ytd_acumulado(
    periodos_selecionados: Sequence[str],
    *,
    incluir_prev_dez: bool,
) -> tuple[str, ...]:
    """Inclui dependências para LL/ROE YTD no regime semestral do IFData."""
    periodos_set = set(_rankings_periodos_selecionados(periodos_selecionados))
    for periodo in list(periodos_set):
        if incluir_prev_dez:
            periodo_dez = _periodo_dez_ano_anterior(periodo)
            if periodo_dez:
                periodos_set.add(periodo_dez)

        parsed = _periodo_para_ano_trimestre(periodo)
        tri_idx = parsed[1] if parsed else None
        if tri_idx in (3, 4):
            periodo_jun = _rankings_periodo_mesma_representacao(periodo, 2)
            if periodo_jun:
                periodos_set.add(periodo_jun)

    return tuple(sorted(periodos_set))


def _resolve_rankings_source_family(indicador_label: str) -> str:
    if indicador_label in RANKINGS_FAMILY_PRINCIPAL_PREPARED:
        return "principal_prepared"
    if indicador_label in RANKINGS_FAMILY_CAPITAL_PREPARED:
        return "capital_prepared"
    if indicador_label in RANKINGS_FAMILY_ANALYTICAL:
        return "analytical_principal"
    return "analytical_principal"


def _resolve_rankings_source_request(
    grafico_base: str,
    indicador_label: str,
    periodos_resumo: Sequence[str],
    *,
    periodo_tabela: Optional[str] = None,
    modo_tabela: Optional[str] = None,
) -> dict:
    """Resolve a família de dados e os períodos auxiliares necessários para Rankings."""
    if grafico_base == "Tabela":
        periodo_base = periodo_tabela or (periodos_resumo[0] if periodos_resumo else None)
        periodos_base = [periodo_base] if periodo_base else []
        if modo_tabela == "Trimestral":
            return {
                "source_kind": "analytical_with_capital",
                "periodos_filter": _rankings_expandir_periodos_analiticos(
                    periodos_base,
                    incluir_prev_dez=True,
                    incluir_contexto_trimestral=True,
                ),
                "needs_capital": True,
                "perf_label": "rankings_df_source_table_trimestral",
            }
        return {
            "source_kind": "analytical_with_capital",
            "periodos_filter": _rankings_expandir_periodos_ytd_acumulado(
                periodos_base,
                incluir_prev_dez=True,
            ),
            "needs_capital": True,
            "perf_label": "rankings_df_source_table_acumulado",
        }

    source_family = _resolve_rankings_source_family(indicador_label)
    if indicador_label == "Lucro Líquido Acumulado YTD":
        source_family = "analytical_principal"
        periodos_filter = _rankings_expandir_periodos_ytd_acumulado(
            periodos_resumo,
            incluir_prev_dez=False,
        )
        perf_label = "rankings_df_source_analytical"
    elif indicador_label == "ROE Ac. Anualizado (%)":
        source_family = "analytical_principal"
        periodos_filter = _rankings_expandir_periodos_ytd_acumulado(
            periodos_resumo,
            incluir_prev_dez=True,
        )
        perf_label = "rankings_df_source_analytical"
    elif source_family == "principal_prepared":
        periodos_filter = _rankings_periodos_selecionados(periodos_resumo)
        perf_label = "rankings_df_source_principal_prepared"
    elif source_family == "capital_prepared":
        periodos_filter = _rankings_periodos_selecionados(periodos_resumo)
        perf_label = "rankings_df_source_capital_prepared"
    else:
        periodos_filter = _rankings_expandir_periodos_analiticos(
            periodos_resumo,
            incluir_prev_dez=True,
            incluir_contexto_trimestral=True,
        )
        perf_label = "rankings_df_source_analytical"

    return {
        "source_kind": source_family,
        "periodos_filter": periodos_filter,
        "needs_capital": source_family == "capital_prepared",
        "perf_label": perf_label,
    }


def get_df_periodo_brincar(periodo: str) -> pd.DataFrame:
    """Obtém DataFrame de um período específico sem concatenar todos os períodos."""
    dados_periodos = st.session_state.get('dados_periodos', {})
    df_periodo = dados_periodos.get(periodo)
    if df_periodo is None:
        return pd.DataFrame()
    return df_periodo




@st.cache_data(ttl=900, show_spinner=False)
def _get_analise_base_df(
    principal_token: str,
    alias_sig: tuple,
    capital_mesclado: bool,
    periodos_filter: Optional[tuple] = None,
) -> pd.DataFrame:
    """Base unificada para abas analíticas com dependências explícitas para cache."""
    _arg_hash = hashlib.md5(
        str((principal_token, alias_sig, capital_mesclado, periodos_filter)).encode()
    ).hexdigest()
    print(f"[CACHE DEBUG] _get_analise_base_df CALLED | arg_hash={_arg_hash}")
    _ = (principal_token, capital_mesclado)
    dados_periodos = _carregar_dados_periodos_preparados(principal_token, alias_sig)
    if not dados_periodos:
        return pd.DataFrame()

    if periodos_filter is not None:
        periodos_set = {str(p) for p in periodos_filter if p is not None}
        dados_periodos = {
            periodo: df_periodo
            for periodo, df_periodo in dados_periodos.items()
            if str(periodo) in periodos_set
        }

    if not dados_periodos:
        return pd.DataFrame()

    result = pd.concat(dados_periodos.values(), ignore_index=True)
    assert result.shape[0] > 0, "get_analise_base_df retornou vazio"

    if result is None or result.empty:
        return pd.DataFrame()

    result = _normalizar_lucro_liquido(result.copy())
    result = _recalcular_roe_anualizado_df(result)
    result = _recalcular_roe_trimestral_df(result)
    return result


def get_analise_base_df(
    cache_token: Optional[str] = None,
    periodos_filter: Optional[list] = None,
) -> pd.DataFrame:
    """Retorna base memoizada para Peers e Scatter."""
    principal_token = str(cache_token if cache_token is not None else _cache_version_token("principal"))
    alias_sig = _alias_signature_cache_key()
    capital_mesclado = bool(_to_cache_key(st.session_state.get('_dados_capital_mesclados', False)))
    periodos_filter_key = _to_cache_key(periodos_filter) if periodos_filter is not None else None
    return _get_analise_base_df(
        principal_token,
        alias_sig,
        capital_mesclado,
        periodos_filter=periodos_filter_key,
    )


def _get_cache_data_mtime(cache_obj) -> Optional[float]:
    if cache_obj is None:
        return None
    if cache_obj.arquivo_dados.exists():
        return cache_obj.arquivo_dados.stat().st_mtime
    if cache_obj.arquivo_dados_pickle.exists():
        return cache_obj.arquivo_dados_pickle.stat().st_mtime
    return None


def _load_cache_metadata(cache_obj) -> dict:
    if cache_obj is None or not cache_obj.arquivo_metadata.exists():
        return {}
    try:
        return json.loads(cache_obj.arquivo_metadata.read_text())
    except Exception:
        return {}


def ensure_derived_metrics_cache(
    derived_cache_name: str = "derived_metrics",
    dre_cache_name: str = "dre",
    principal_cache_name: str = "principal",
) -> Tuple[Optional[object], Optional[str], dict]:
    manager = get_cache_manager()
    cache_derivado = manager.get_cache(derived_cache_name) if manager else None
    if cache_derivado is None:
        return None, "cache de métricas derivadas não configurado", {}

    mtime_derivado = _get_cache_data_mtime(cache_derivado)
    dre_cache = manager.get_cache(dre_cache_name)
    principal_cache = manager.get_cache(principal_cache_name)
    mtime_dre = _get_cache_data_mtime(dre_cache)
    mtime_principal = _get_cache_data_mtime(principal_cache)

    precisa_recalcular = True
    if mtime_derivado is not None:
        referencia = max([t for t in [mtime_dre, mtime_principal] if t is not None], default=None)
        if referencia is None or mtime_derivado >= referencia:
            precisa_recalcular = False

    if not precisa_recalcular:
        return cache_derivado, None, _load_cache_metadata(cache_derivado)

    resultado_dre = manager.carregar(dre_cache_name) if manager else None
    if not resultado_dre or not resultado_dre.sucesso or resultado_dre.dados is None:
        msg = resultado_dre.mensagem if resultado_dre else "falha ao carregar DRE"
        return cache_derivado, msg, {}

    resultado_principal = manager.carregar(principal_cache_name) if manager else None
    if not resultado_principal or not resultado_principal.sucesso or resultado_principal.dados is None:
        msg = resultado_principal.mensagem if resultado_principal else "falha ao carregar principal"
        return cache_derivado, msg, {}

    _perf_start("derived_metrics_build")
    resultado_materializacao = materialize_derived_metrics_cache(
        manager=manager,
        derived_cache_name=derived_cache_name,
        dre_cache_name=dre_cache_name,
        principal_cache_name=principal_cache_name,
        force=True,
    )
    elapsed = _perf_end("derived_metrics_build")
    if not resultado_materializacao.sucesso:
        return cache_derivado, resultado_materializacao.mensagem, {}

    metadata_atual = _load_cache_metadata(cache_derivado)
    extra = metadata_atual.setdefault("extra", {})
    extra["tempo_execucao_s"] = round(elapsed, 3)
    if cache_derivado.arquivo_metadata.exists():
        try:
            cache_derivado.arquivo_metadata.write_text(
                json.dumps(metadata_atual, indent=2, ensure_ascii=False),
                encoding="utf-8",
            )
        except Exception:
            pass
    return cache_derivado, None, _load_cache_metadata(cache_derivado)


def carregar_metricas_derivadas_slice(periodos=None, instituicoes=None, metricas=None) -> pd.DataFrame:
    cache_derivado, erro, _ = ensure_derived_metrics_cache()
    if cache_derivado is None or erro:
        st.session_state["derived_metrics_last_error"] = erro or "cache derivado indisponível"
        return pd.DataFrame()
    st.session_state.pop("derived_metrics_last_error", None)
    return load_derived_metrics_slice(
        cache_derivado,
        periodos=periodos,
        instituicoes=instituicoes,
        metricas=metricas,
    )


def carregar_metricas_derivadas_individual_slice(periodos=None, instituicoes=None, metricas=None) -> pd.DataFrame:
    cache_derivado, erro, _ = ensure_derived_metrics_cache(
        derived_cache_name="derived_metrics_individual",
        dre_cache_name="dre_individual",
        principal_cache_name="principal_individual",
    )
    if cache_derivado is None or erro:
        st.session_state["derived_metrics_individual_last_error"] = erro or "cache derivado individual indisponível"
        return pd.DataFrame()
    st.session_state.pop("derived_metrics_individual_last_error", None)
    return load_derived_metrics_slice(
        cache_derivado,
        periodos=periodos,
        instituicoes=instituicoes,
        metricas=metricas,
    )


def _df_mem_mb(df: Optional[pd.DataFrame]) -> float:
    if df is None or df.empty:
        return 0.0
    return df.memory_usage(deep=True).sum() / (1024 * 1024)


def anexar_metricas_derivadas_periodo(df_periodo: pd.DataFrame, periodo: str):
    if df_periodo is None or df_periodo.empty:
        return df_periodo, {}
    _perf_start("scatter_derived_load")
    df_derived = carregar_metricas_derivadas_slice(
        periodos=[periodo],
        instituicoes=df_periodo["Instituição"].dropna().unique().tolist(),
        metricas=DERIVED_METRICS,
    )
    tempo = _perf_end("scatter_derived_load")
    if df_derived.empty:
        df_out = df_periodo.copy()
        for metric in DERIVED_METRICS:
            if metric not in df_out.columns:
                df_out[metric] = pd.NA
        return df_out, {"tempo_s": round(tempo, 3), "linhas": 0, "mem_mb": 0.0}
    df_pivot = df_derived.pivot_table(
        index="Instituição",
        columns="Métrica",
        values="Valor",
        aggfunc="first",
        observed=False,
    ).reset_index()
    df_pivot.columns.name = None
    df_out = df_periodo.merge(df_pivot, on="Instituição", how="left")
    for metric in DERIVED_METRICS:
        if metric not in df_out.columns:
            df_out[metric] = pd.NA
    diag = {
        "tempo_s": round(tempo, 3),
        "linhas": len(df_derived),
        "mem_mb": _df_mem_mb(df_derived),
    }
    return df_out, diag


@st.cache_data(ttl=900, show_spinner=False)
def get_scatter_periodo_df(periodo: str, principal_token: str, derived_token: str, alias_sig: tuple, capital_mesclado: bool):
    """Carrega dataframe de um período do Scatter já com métricas derivadas anexadas.

    Diagnóstico definitivo de Basileia no Scatter:
    - garante a coluna canônica ``Índice de Basileia``;
    - normaliza para base decimal (0-1);
    - corrige casos residuais de dupla divisão por 100.

    Isso evita o erro recorrente de exibir 0.15% quando o correto é 15.00%.
    """
    _ = derived_token
    df_base = _get_analise_base_df(principal_token, alias_sig, capital_mesclado)
    if df_base is None or df_base.empty or 'Período' not in df_base.columns:
        return pd.DataFrame(), {"tempo_s": 0.0, "linhas": 0, "mem_mb": 0.0}

    df_periodo = df_base[df_base['Período'] == periodo].copy()
    df_periodo = _garantir_indice_basileia_coluna(df_periodo)
    df_periodo = _ajustar_basileia_para_scatter(df_periodo)
    df_periodo, diag = anexar_metricas_derivadas_periodo(df_periodo, periodo)
    if 'Lucro Líquido Trimestral' not in df_periodo.columns:
        if 'Lucro Líquido' in df_periodo.columns:
            df_periodo['Lucro Líquido Trimestral'] = pd.to_numeric(df_periodo['Lucro Líquido'], errors='coerce')
        else:
            df_periodo['Lucro Líquido Trimestral'] = pd.NA
    return df_periodo, diag


