def _cache_file_token(tipo_cache: str) -> str:
    cache_manager = get_cache_manager()
    cache_obj = cache_manager.get_cache(tipo_cache) if cache_manager else None
    if cache_obj is None:
        return f"{tipo_cache}:missing"

    arquivo = None
    if cache_obj.arquivo_dados.exists():
        arquivo = cache_obj.arquivo_dados
    elif cache_obj.arquivo_dados_pickle.exists():
        arquivo = cache_obj.arquivo_dados_pickle

    if arquivo is None:
        return f"{tipo_cache}:empty"

    stat = arquivo.stat()
    return f"{tipo_cache}:{int(stat.st_mtime)}:{stat.st_size}"


def _cache_version_token(tipo_cache: str) -> str:
    """Token estável para invalidar caches processados quando arquivo base muda."""
    token = _cache_file_token(tipo_cache)
    if tipo_cache == "critical_screens":
        deps = (
            _cache_file_token("principal"),
            _cache_file_token("passivo"),
        )
        return "|".join((token, *deps))
    return token


def _alias_signature() -> tuple:
    return ()


def _alias_signature_cache_key() -> tuple:
    """Compatibilidade: não há mais assinatura variável de Alias institucional."""
    return ()


def _precisa_recalcular_metricas_rapido(dados_periodos: dict) -> bool:
    """Heurística conservadora para evitar recálculo global desnecessário."""
    if not dados_periodos:
        return False

    colunas_obsoletas = {'Risco/Retorno', 'Funding Gap (%)', 'Lucro Líquido', 'ROE An. (%)', 'Crédito/PL', 'Crédito/PL (%)'}
    for _, df in dados_periodos.items():
        if df is None or df.empty:
            continue
        cols = set(df.columns)

        if cols & colunas_obsoletas:
            return True

        if {"Lucro Líquido Acumulado YTD", "Patrimônio Líquido"}.issubset(cols) and not ({"ROE Ac. YTD an. (%)", "ROE Ac. Anualizado (%)"} & cols):
            return True
        if {"Carteira de Crédito", "Patrimônio Líquido"}.issubset(cols) and "Carteira de Crédito Bruta / PL" not in cols:
            return True
        if {"Carteira de Crédito", "Core Funding"}.issubset(cols) and "Carteira de Crédito/Core Funding (%)" not in cols:
            return True
        if {"Carteira de Crédito", "Ativo Total"}.issubset(cols) and "Crédito/Ativo (%)" not in cols:
            return True

        for col_pct in (
            "Índice de Basileia",
            "Índice de Basileia Total",
            "Índice de Imobilização",
            "Índice de Capital Principal",
            "Índice de Capital Principal (CET1)",
        ):
            if col_pct in cols:
                serie = pd.to_numeric(df[col_pct], errors='coerce')
                if (serie.abs() > 1).any():
                    return True

    return False

@st.cache_resource(show_spinner=False)
def _carregar_dados_periodos_preparados(cache_token: str, alias_sig: tuple):
    """Carrega e prepara cache principal com memoização entre sessões.

    Evita recomputar métricas derivadas e aplicação de aliases em todo reload.
    """
    cache_manager = get_cache_manager()
    cache_principal = cache_manager.get_cache("principal") if cache_manager else None
    dados_cache = cache_principal.carregar_formato_antigo() if cache_principal else None
    if not dados_cache:
        return None

    dados_cache = _anexar_carteira_credito_bruta(dados_cache)
    dados_cache = _anexar_core_funding(dados_cache)

    if _precisa_recalcular_metricas_rapido(dados_cache):
        dados_cache = recalcular_metricas_derivadas(dados_cache)

    # Garante coluna canônica e valores consistentes de ROE entre abas.
    dados_cache = _sincronizar_roe_anualizado(dados_cache)

    return dados_cache


@st.cache_resource(show_spinner=False)
def _carregar_dados_capital_preparados(cache_token: str, alias_sig: tuple):
    """Carrega e prepara cache de capital com memoização entre sessões."""
    cache_manager = get_cache_manager()
    cache_capital = cache_manager.get_cache("capital") if cache_manager else None
    dados_capital = cache_capital.carregar_formato_antigo() if cache_capital else None
    if not dados_capital:
        return None

    return dados_capital


def carregar_dados_periodos():
    if 'dados_periodos' in st.session_state and st.session_state['dados_periodos']:
        return
    _perf_start("init_dados_periodos")

    cache_token = _cache_version_token("principal")
    alias_sig = _alias_signature_cache_key()

    _perf_start("principal_preparado_cache")
    dados_cache = _carregar_dados_periodos_preparados(cache_token, alias_sig)
    print(_perf_log("principal_preparado_cache"))

    if dados_cache:
        st.session_state['dados_periodos'] = dados_cache
        if 'cache_fonte' not in st.session_state:
            st.session_state['cache_fonte'] = 'local (cache preparado)'
        if 'dados_periodos_erro' in st.session_state:
            del st.session_state['dados_periodos_erro']
    else:
        st.session_state['dados_periodos_erro'] = "cache principal não disponível ou vazio"
        st.session_state['dados_periodos_fonte'] = 'desconhecida'
    print(_perf_log("init_dados_periodos"))




@st.cache_data(ttl=3600, show_spinner=False)
def _get_rankings_base_df(
    principal_token: str,
    capital_token: str,
    capital_mesclado: bool,
    alias_sig: tuple,
    periodos_filter: Optional[tuple] = None,
) -> pd.DataFrame:
    """Pré-processa DataFrame base de Rankings uma única vez por versão de cache.

    Reutiliza get_analise_base_df (concat + ROE) e adiciona apenas etapas
    específicas de Rankings: merge de capital e normalização de indicadores.
    """
    _ = (capital_mesclado,)
    df = _get_rankings_analytical_df(
        principal_token,
        alias_sig,
        periodos_filter=periodos_filter,
    )
    if df is None or df.empty:
        return pd.DataFrame()

    return _merge_rankings_capital(df, capital_token, alias_sig, periodos_filter)


def _merge_rankings_capital(
    df_base: pd.DataFrame,
    capital_token: str,
    alias_sig: tuple,
    periodos_filter: Optional[tuple] = None,
) -> pd.DataFrame:
    if df_base is None or df_base.empty:
        return pd.DataFrame()

    df = df_base.copy()
    df_capital_idx = _get_rankings_capital_slice(
        capital_token,
        alias_sig,
        tuple(periodos_filter or ()),
    )
    if not df_capital_idx.empty:
        left_df = df.set_index(["Período", "Instituição"])
        right_df = df_capital_idx.set_index(["Período", "Instituição"])
        df = left_df.join(right_df, how="left", rsuffix="_capital_idx").reset_index()
    return _normalizar_indicadores_rankings(df)


@st.cache_data(ttl=3600, show_spinner=False)
def _get_rankings_analytical_df(
    principal_token: str,
    alias_sig: tuple,
    periodos_filter: Optional[tuple] = None,
) -> pd.DataFrame:
    _ = (principal_token, alias_sig)
    df = _get_analise_base_df(
        principal_token,
        alias_sig,
        False,
        periodos_filter=periodos_filter,
    )
    if df is None or df.empty:
        return pd.DataFrame()
    return _normalizar_indicadores_rankings(df)


@st.cache_data(ttl=3600, show_spinner=False)
def _get_rankings_direct_df(
    principal_token: str,
    alias_sig: tuple,
    periodos_filter: Optional[tuple] = None,
) -> pd.DataFrame:
    # [CHANGE] Data: 2026-04-05 | Aba: Rankings | Prioridade: P1
    # Motivo: indicadores diretos como Ativo Total pagavam a base analítica completa
    # (concat + recálculo de lucro/ROE), embora dependam apenas do cache principal preparado.
    # Solução: recorte direto por período a partir de dados_periodos preparados, com
    # normalização leve de aliases/nomes de coluna já usada nos Rankings.
    # Impacto: reduz o custo do caminho frio de Rankings sem alterar fórmulas financeiras.
    # Testado em: py_compile, pytest e execução headless da aba Rankings.
    """Retorna recorte direto de Rankings para indicadores que não exigem recálculo analítico."""
    _ = (principal_token, alias_sig)
    dados_periodos = _carregar_dados_periodos_preparados(principal_token, alias_sig)
    if not dados_periodos:
        return pd.DataFrame()

    if periodos_filter is not None:
        periodos_set = {str(p) for p in periodos_filter if p is not None}
    else:
        periodos_set = set()

    frames = []
    for periodo, df_periodo in dados_periodos.items():
        if periodos_set and str(periodo) not in periodos_set:
            continue
        if df_periodo is None or df_periodo.empty:
            continue
        frames.append(df_periodo.copy())

    if not frames:
        return pd.DataFrame()

    df = pd.concat(frames, ignore_index=True)
    if df.empty:
        return pd.DataFrame()

    return _normalizar_indicadores_rankings(df)


@st.cache_data(ttl=3600, show_spinner=False)
def _get_rankings_principal_with_capital_df(
    principal_token: str,
    capital_token: str,
    alias_sig: tuple,
    periodos_filter: Optional[tuple] = None,
) -> pd.DataFrame:
    df = _get_rankings_direct_df(
        principal_token,
        alias_sig,
        periodos_filter=periodos_filter,
    )
    if df is None or df.empty:
        return pd.DataFrame()
    return _merge_rankings_capital(df, capital_token, alias_sig, periodos_filter)


def _normalizar_indicadores_rankings(df: pd.DataFrame) -> pd.DataFrame:
    """Padroniza colunas-chave dos Rankings com a mesma semântica da aba Peers."""
    if df is None or df.empty:
        return pd.DataFrame()

    df_out = canonicalize_institution_dataframe(
        df,
        catalog_map=build_institution_to_conglomerate_map(APP_DIR),
        base_dir=APP_DIR,
    )

    def _coalesce_colunas(colunas_candidatas: list[str]) -> Optional[pd.Series]:
        serie_out = None
        for col in colunas_candidatas:
            if col not in df_out.columns:
                continue
            serie = pd.to_numeric(df_out[col], errors="coerce")
            serie_out = serie if serie_out is None else serie_out.combine_first(serie)
        return serie_out

    serie_carteira = _coalesce_colunas([
        "Carteira de Crédito*",
        "Carteira de Crédito Bruta",
        "Carteira de Crédito",
    ])
    if serie_carteira is not None:
        df_out["Carteira de Crédito Bruta"] = serie_carteira
        df_out["Carteira de Crédito*"] = serie_carteira

    serie_core = _coalesce_colunas([
        "Core Funding*",
        "Core Funding",
        "Captações",
    ])
    if serie_core is not None:
        df_out["Core Funding"] = serie_core
        df_out["Core Funding*"] = serie_core

    serie_cet1 = _coalesce_colunas([
        "Índice de Capital Principal (CET1)",
        "Índice de Capital Principal (CET1)_capital_idx",
        "Índice de Capital Principal",
        "Índice de CET1",
    ])
    if serie_cet1 is not None:
        df_out["Índice de Capital Principal (CET1)"] = _normalizar_indice_para_decimal(serie_cet1)

    serie_t1 = _coalesce_colunas([
        "Índice de Capital T1 (%)",
        "Índice de Capital T1 (%)_capital_idx",
        "Índice de Capital Nível I",
        "Índice Capital Nível I",
        "Índice de Capital Nivel I",
        "Índice de Capital T1",
        "Índice Capital T1",
    ])
    if serie_t1 is not None:
        df_out["Índice de Capital T1 (%)"] = _normalizar_indice_para_decimal(serie_t1)

    serie_basileia_total = _coalesce_colunas([
        "Índice de Basileia Total (%)",
        "Índice de Basileia Total (%)_capital_idx",
        "Índice de Basileia",
        "Índice de Basileia Total",
    ])
    if serie_basileia_total is not None:
        df_out["Índice de Basileia Total (%)"] = _normalizar_indice_para_decimal(serie_basileia_total)

    return df_out


@st.cache_data(ttl=900, show_spinner=False)
def _get_rankings_capital_slice(
    capital_token: str,
    alias_sig: tuple,
    periodos_filter: tuple,
) -> pd.DataFrame:
    """Recorte enxuto de capital para o branch de Basileia em Rankings."""
    df_capital = _construir_componentes_capital_rankings_slice(
        capital_token,
        alias_sig,
        tuple(periodos_filter or ()),
    )
    if df_capital is None or df_capital.empty:
        return pd.DataFrame()
    if not periodos_filter:
        return _normalizar_indicadores_rankings(df_capital.copy())
    periodos_set = {str(p) for p in periodos_filter if p is not None}
    df_capital = df_capital[df_capital["Período"].astype(str).isin(periodos_set)].copy()
    return _normalizar_indicadores_rankings(df_capital)


@st.cache_data(ttl=3600, show_spinner=False)
def _get_rankings_source_df(
    principal_token: str,
    capital_token: str,
    alias_sig: tuple,
    source_kind: str,
    periodos_filter: Optional[tuple] = None,
) -> pd.DataFrame:
    if source_kind == "principal_prepared":
        return _get_rankings_direct_df(
            principal_token,
            alias_sig,
            periodos_filter=periodos_filter,
        )
    if source_kind == "capital_prepared":
        return _get_rankings_capital_slice(
            capital_token,
            alias_sig,
            tuple(periodos_filter or ()),
        )
    if source_kind == "principal_with_capital":
        return _get_rankings_principal_with_capital_df(
            principal_token,
            capital_token,
            alias_sig,
            periodos_filter=periodos_filter,
        )
    if source_kind == "analytical_with_capital":
        return _get_rankings_base_df(
            principal_token,
            capital_token,
            False,
            alias_sig,
            periodos_filter=periodos_filter,
        )
    return _get_rankings_analytical_df(
        principal_token,
        alias_sig,
        periodos_filter=periodos_filter,
    )

